/* GENERATED by scripts/build-classic-css.mjs from design-classic (bb55a3f). Do not edit by hand.
   The Classic design: every rule is scoped under html[data-design="classic"]; loaded only when someone picks Classic. */
@import url("https://fonts.googleapis.com/css2?family=Public+Sans:ital,wght@0,400;0,500;0,600;0,700;0,800;1,400&display=swap");

/* ── src/index.css ── */
/* Box-model reset only. Everything else (body, button, input/textarea/
   select, focus rings) is defined once, from tokens, in styles/base.css
   — this file used to duplicate all of those with hardcoded, untokenized
   values (#f5f5f5, #333, a flat 6px radius, a bare #6366f1 focus color),
   loaded before base.css and never updated when the token system was
   introduced. Kept only what has nowhere else to live. */
html[data-design="classic"] * { margin: 0; padding: 0; box-sizing: border-box; }


/* ── src/styles/base.css ── */
/* =========================================================
   PROWOSMA — PROFESSIONAL DESIGN SYSTEM
   ========================================================= */

html[data-design="classic"] {
  /* ── Accent — one deliberate ink-indigo, used sparingly for interactive
     state (primary actions, active nav, focus, links). Previously there
     were two competing accent hues (a sky-blue "brand" scale and a
     separate indigo "accent" scale) — consolidated to one family so
     nothing is fighting for attention. --accent-* kept as an alias so
     any component still referencing it directly keeps working. */
  /* Studio indigo. 500 is the primary action / link colour (5.9:1 on
     white); 600/700 are its hover and pressed steps and the text colour
     on brand-50 tints. */
  --brand-50: #EEEEFD;
  --brand-100: #E1E1FB;
  --brand-200: #C7C8F5;
  --brand-400: #7C7FE8;
  --brand-500: #4B4FD8;
  --brand-600: #3F42C4;
  --brand-700: #3437A6;
  --brand-900: #1E2066;

  --accent-50: var(--brand-50);
  --accent-100: var(--brand-100);
  --accent-400: var(--brand-400);
  --accent-500: var(--brand-500);
  --accent-600: var(--brand-600);

  /*  Neutrals (Cool Slate)  */
  --gray-50: #f8fafc;
  --gray-100: #f1f5f9;
  --gray-200: #e2e8f0;
  --gray-300: #cbd5e1;
  --gray-400: #94a3b8;
  --gray-500: #64748b;
  --gray-600: #475569;
  --gray-700: #334155;
  --gray-800: #1e293b;
  --gray-900: #0f172a;

  /*  Semantic — muted rather than neon-saturated, per brief  */
  --success: #1E8E5A;
  --warning: #C17D22;
  --danger: #C8372D;
  /* Text-safe steps of the semantic colours (4.5:1+ on white and on their
     own -soft tint). The base colours above are for dots, bars and icons;
     amber at #C17D22 is only 3.2:1, too light for text. */
  --success-text: #17663F;
  --warning-text: #8A4B05;
  --danger-text: #B42318;
  --success-soft: #E7F6EE;
  --warning-soft: #FDF1DE;
  --danger-soft: #FDECEA;
  --purple: #7C5CBF;
  --info: var(--brand-500);

  /* Data-viz categorical palette — fixed roles, not "whichever hex was
     closest to hand". Dashboards/charts had accumulated 7+ unrelated
     hues (bare #6366f1/#f59e0b/#10b981/#8b5cf6/#ef4444/#ec4899/#d97706)
     assigned ad hoc per component; this is the one set every chart/status
     indicator should draw from, so the same category (e.g. "in progress")
     is always the same color everywhere it appears. */
  --viz-todo:     var(--brand-500);   /* not-yet-started */
  --viz-progress: var(--warning);     /* active/in-progress */
  --viz-done:     var(--success);     /* complete */
  --viz-overdue:  var(--danger);      /* needs attention */
  --viz-goal:     var(--purple);      /* goals — kept distinct from tasks/projects */

  /*  Surfaces — neutral, not hue-tinted (previously a pale sky-blue tint
     on every page background, which read as decorative branding rather
     than a working surface) */
  --bg-page: #F4F5F8;
  --bg-card: #ffffff;
  --bg-input: #ffffff;
  --border: #E2E5EC;
  --border-strong: #D7DBE4;   /* inputs, secondary buttons */

  /* ── Design Switcher tokens (overridden by DesignSwitcher.applyDesign) ── */
  /* These defaults reproduce the current Prowosma appearance exactly.      */
  /* Clearing all applyDesign overrides restores these values automatically.  */
  --sidebar-bg:          #14172B;
  --sidebar-text:        rgba(255,255,255,0.72);
  --sidebar-active-bg:   rgba(124,128,255,0.18);
  --sidebar-active-text: #ffffff;
  --sidebar-label:       rgba(255,255,255,0.45);
  --topbar-bg:           #ffffff;

  /* ── Extended design tokens ── */
  --card-bg:             #ffffff;
  --card-border:         #E2E5EC;
  --card-shadow:         var(--elevation-1);
  --text-primary:        #172033;
  --text-secondary:      #4A5265;
  --text-muted:          #5D6577;
  --text-on-brand:       #ffffff;
  --input-bg:            #ffffff;
  --input-border:        #D7DBE4;
  --search-bg:           #f8fafc;
  --search-border:       #E2E5EC;
  --btn-primary-bg:      var(--brand-500);
  --btn-primary-text:    #ffffff;

  /* AI insight card — flat, not a gradient wash */
  --ai-card-bg:          #14163A;
  --ai-card-border:      rgba(91,95,238,0.35);
  --ai-card-text:        #ffffff;
  --ai-card-btn:         var(--brand-500);
  --border-focus: var(--brand-500);

  /*  Shadows — neutral (grayscale), not tinted to the brand hue — and a
     felt elevation scale, not a decorative one. Each step pairs a soft
     ambient falloff with a tighter contact shadow from one consistent
     light source (above), so nearer tiers read as nearer rather than
     just "more blur". Previous values (0.04-0.07 opacity) were correct
     in spirit but too faint to actually register against a near-white
     page — Tier 1 (cards, sidebar) needs to be *seen*, not just
     technically present. Always pair with a 1px border in the component
     itself: the border gives the edge, the shadow gives the lift — that
     combination is what keeps this from reading as glassmorphism/blur,
     which has lift with no firm edge. */
  --shadow-xs: 0 1px 2px rgba(15, 23, 42, 0.06);
  --shadow-sm: 0 1px 3px rgba(15, 23, 42, 0.09), 0 1px 2px rgba(15, 23, 42, 0.05);
  --shadow-md:
    0 3px 8px -2px rgba(15, 23, 42, 0.12), 0 1px 3px -1px rgba(15, 23, 42, 0.07);
  --shadow-lg:
    0 10px 20px -6px rgba(15, 23, 42, 0.16), 0 3px 8px -3px rgba(15, 23, 42, 0.08);
  --shadow-xl:
    0 20px 32px -8px rgba(15, 23, 42, 0.22),
    0 8px 12px -6px rgba(15, 23, 42, 0.1);

  /*  Elevation tiers — what each shadow step MEANS, so components
     reference a role ("this is a floating surface") instead of picking a
     shadow size by feel. Every raised/floating element in the app maps
     to exactly one of these four; nothing gets a one-off shadow value.
       Tier 1  Surface   cards, sidebar, table rows        — sits on the page
       Tier 2  Raised    topbar, dropdowns, popovers        — nearer than Tier 1
       Tier 3  Overlay   modals, drawers, command palette   — in front of everything
       Tier 4  Transient toasts, tooltips, context menus    — Tier 3 weight, arrives with motion */
  --elevation-1: var(--shadow-sm);
  --elevation-2: var(--shadow-md);
  --elevation-3: var(--shadow-xl);
  --elevation-4: var(--shadow-xl);

  /* Canvas vs surface — a real background step (not the ~2% difference
     --bg-page/--bg-card had before) so a card reads as a distinct object
     sitting on the page even before its shadow is noticed. */
  --bg-canvas: #F4F5F8;
  --surface-1: #ffffff;   /* cards, list rows */
  --surface-2: #ffffff;   /* topbar, dropdowns — same fill in light mode, differentiated by --elevation-2's tighter shadow; dark theme gives this its own step */

  /* Motion — used for state transitions only (hover/press/open/close),
     never as a page-load/scroll-triggered flourish. */
  --transition-fast: 120ms ease;
  --transition-base: 180ms cubic-bezier(0.2, 0, 0, 1);


  /*  Typography  */
  /* Public Sans: an open-licence (OFL) workhorse with tabular figures,
     sturdy at 12-14px in dense tables, and less ubiquitous than Inter. */
  --font-sans:
    "Public Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;

  /* Type scale — intentional steps, not ad-hoc px values per component.
     Weight discipline: 800 reserved for hero numbers/greetings only,
     700 for interactive labels & eyebrows, 600 for emphasis, 400/500
     for body copy. Previously most UI text was 9-11px at weight 700-800
     regardless of role, which reads cramped and shouty at once. */
  --text-2xs: 10.5px;  /* micro labels, badges */
  --text-xs:  12px;    /* captions, meta text */
  --text-sm:  13px;    /* default UI text, list items */
  --text-md:  14.5px;  /* body copy, card titles */
  --text-lg:  17px;    /* section headers */
  --text-xl:  21px;    /* page titles */
  --text-2xl: 27px;    /* hero greeting, headline numbers */
  --leading-tight: 1.25;
  --leading-normal: 1.5;

  /* Spacing scale — replaces one-off 4/6/7/9/10/11/14px choices with a
     consistent rhythm. Not enforced everywhere yet, but new/updated
     components should use these instead of inventing new px values. */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-8: 32px;

  /*  Radius — tightened from the previous 6/10/14/18 scale for a
     crisper, less "rounded SaaS card" feel */
  --radius-sm: 6px;   /* chips, small icon buttons */
  --radius-md: 8px;   /* buttons, inputs, menus */
  --radius-lg: 10px;  /* panels, cards, tables */
  --radius-xl: 14px;  /* dialogs */
  /* Control heights */
  --control-h-sm: 32px;
  --control-h: 36px;
  --radius-full: 9999px;

  /*  Layout  */
  --sidebar-w: 240px;
  --topbar-h: 60px;
}

/*  Reset & Base  */
html[data-design="classic"] *,
html[data-design="classic"] *::before,
html[data-design="classic"] *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html[data-design="classic"] {
  font-size: 14px;
}

html[data-design="classic"] body {
  font-family: var(--font-sans);
  background: var(--bg-page);
  color: var(--text-primary);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/*  Buttons  */
html[data-design="classic"] button {
  cursor: pointer;
  border: none;
  border-radius: var(--radius-sm);
  padding: 8px 16px;
  font-size: 14px;
  font-family: var(--font-sans);
  font-weight: 500;
  transition: all 0.15s ease;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}

html[data-design="classic"] .btn-primary {
  background: var(--brand-500);
  color: #fff;
  min-height: var(--control-h);
  padding: 0 14px;
  border-radius: var(--radius-md);
  font-size: 13.5px;
  font-weight: 600;
  justify-content: center;
}
html[data-design="classic"] .btn-primary:hover {
  background: var(--brand-600);
}
html[data-design="classic"] .btn-primary:active {
  background: var(--brand-700);
}
html[data-design="classic"] .btn-primary:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

html[data-design="classic"] .btn-secondary {
  background: var(--bg-card);
  color: var(--text-primary);
  min-height: var(--control-h);
  padding: 0 14px;
  border-radius: var(--radius-md);
  font-size: 13.5px;
  font-weight: 600;
  border: 1px solid var(--border-strong);
  justify-content: center;
}
html[data-design="classic"] .btn-secondary:hover {
  background: var(--gray-50);
  border-color: var(--gray-300);
}

html[data-design="classic"] .btn-icon {
  background: transparent;
  padding: 6px 8px;
  font-size: 15px;
  border-radius: var(--radius-sm);
  color: var(--gray-500);
}
html[data-design="classic"] .btn-icon:hover {
  background: var(--gray-100);
  color: var(--gray-700);
}

html[data-design="classic"] .btn-link {
  background: transparent;
  color: var(--brand-500);
  font-size: 13px;
  font-weight: 500;
  padding: 4px 6px;
}
html[data-design="classic"] .btn-link:hover {
  color: var(--brand-600);
  text-decoration: underline;
}

/*  Inputs  */
html[data-design="classic"] input,
html[data-design="classic"] textarea,
html[data-design="classic"] select {
  border: 1px solid var(--input-border);
  border-radius: var(--radius-md);
  padding: 8px 12px;
  font-size: 14px;
  font-family: var(--font-sans);
  width: 100%;
  outline: none;
  background: var(--bg-input);
  color: var(--gray-800);
  transition:
    border-color 0.15s,
    box-shadow 0.15s;
}
/* Checkboxes and radios keep their natural size: the full-width rule above
   stretched them across the row and shoved their label to the far edge
   (Admin Centre policies, DLP, email TLS, white-label…). :where() keeps this
   at the same weight as `input`, so any component's own sizing still wins. */
html[data-design="classic"] input:where([type="checkbox"], [type="radio"]) {
  width: auto;
  padding: 0;
  flex-shrink: 0;
  accent-color: var(--brand-500);
}
html[data-design="classic"] input:focus,
html[data-design="classic"] textarea:focus,
html[data-design="classic"] select:focus {
  border-color: var(--brand-500);
  box-shadow: 0 0 0 3px rgba(75, 79, 216, 0.16);
}
html[data-design="classic"] input::placeholder,
html[data-design="classic"] textarea::placeholder {
  color: var(--gray-400);
}

html[data-design="classic"] .form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 14px;
}
html[data-design="classic"] .form-group label,
html[data-design="classic"] .form-group legend,
html[data-design="classic"] .form-group .field-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--gray-700);
}
html[data-design="classic"] .form-row {
  display: flex;
  gap: 14px;
}
html[data-design="classic"] .form-row .form-group {
  flex: 1;
}

/*  App Layout  */
html[data-design="classic"] .app {
  display: flex;
  min-height: 100vh;
}

/* ========================================
   PERFORMANCE & POLISH

/*  Skeleton shimmer  */
@keyframes classic-shimmer {
  0%   { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}
html[data-design="classic"] .skeleton {
  background: linear-gradient(90deg,
    var(--gray-100,#f1f5f9) 25%,
    var(--gray-50,#f8fafc)  50%,
    var(--gray-100,#f1f5f9) 75%);
  background-size: 200% 100%;
  animation: classic-shimmer 1.4s ease-in-out infinite;
  border-radius: 8px;
}
html[data-design="classic"][data-theme="dark"] .skeleton {
  background: linear-gradient(90deg,
    rgba(255,255,255,0.06) 25%,
    rgba(255,255,255,0.12) 50%,
    rgba(255,255,255,0.06) 75%);
  background-size: 200% 100%;
}

/*  Optimistic UI  instant feedback  */
html[data-design="classic"] .optimistic { opacity: 0.7; pointer-events: none; }

/*  Page transition  smooth enter  */
html[data-design="classic"] .page-enter {
  animation: classic-pageEnter 0.18s ease-out;
}
@keyframes classic-pageEnter {
  from { opacity: 0; transform: translateY(6px); }
  to   { opacity: 1; transform: translateY(0); }
}

/*  Button press micro-interaction  */
html[data-design="classic"] button:active:not(:disabled) { transform: scale(0.97); }

/*  Focus visible (keyboard nav)  */
html[data-design="classic"] :focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: 2px;
  border-radius: 4px;
}

/*  Instant hover on nav links  */
html[data-design="classic"] .sidebar-nav a, html[data-design="classic"] .topbar-right-cluster button {
  transition: background 0.1s, color 0.1s;
}

/*  Reduce motion for accessibility  */
@media (prefers-reduced-motion: reduce) {
  html[data-design="classic"] *, html[data-design="classic"] *::before, html[data-design="classic"] *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

/*  Card hover lift  premium feel  */
html[data-design="classic"] .card-hover {
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}
html[data-design="classic"] .card-hover:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0,0,0,0.08);
}

/*  Empty states  polished  */
html[data-design="classic"] .empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px 24px;
  text-align: center;
  gap: 12px;
}
html[data-design="classic"] .empty-state-icon {
  font-size: 40px;
  opacity: 0.35;
}
html[data-design="classic"] .empty-state-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--gray-700, #334155);
}
html[data-design="classic"] .empty-state-sub {
  font-size: 13px;
  color: var(--gray-400, #94a3b8);
  max-width: 280px;
  line-height: 1.6;
}
html[data-design="classic"] .empty-state-cta {
  margin-top: 4px;
  padding: 8px 18px;
  background: #6366f1;
  color: #fff;
  border: none;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.14s;
}
html[data-design="classic"] .empty-state-cta:hover {
  background: #4f46e5;
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(99,102,241,0.35);
}

/*  Loading spinner (used where skeleton isn't suitable)  */
html[data-design="classic"] .spinner {
  width: 20px; height: 20px;
  border: 2px solid var(--gray-200, #e2e8f0);
  border-top-color: #6366f1;
  border-radius: 50%;
  animation: classic-spin 0.7s linear infinite;
}
@keyframes classic-spin { to { transform: rotate(360deg); } }

/*  Toast / snackbar  */
html[data-design="classic"] .toast-container {
  position: fixed;
  bottom: 90px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 9000;
  display: flex;
  flex-direction: column;
  gap: 8px;
  pointer-events: none;
}
html[data-design="classic"] .toast {
  background: #1e293b;
  color: #fff;
  padding: 10px 18px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 500;
  box-shadow: 0 8px 24px rgba(0,0,0,0.2);
  animation: classic-toastIn 0.2s cubic-bezier(0.34,1.56,0.64,1);
  pointer-events: auto;
}
html[data-design="classic"] .toast.success { background: #065f46; }
html[data-design="classic"] .toast.error   { background: #7f1d1d; }
@keyframes classic-toastIn {
  from { opacity:0; transform:translateY(8px) scale(0.96); }
  to   { opacity:1; transform:translateY(0) scale(1); }
}

/*  Screen-reader-only text: read aloud, not shown  */
html[data-design="classic"] .sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}


/* ── src/styles/layout.css ── */
/* ========================================
   SIDEBAR  Professional Dark Design
   /* = */

html[data-design="classic"] .sidebar {
  width: var(--sidebar-w);
  background: var(--sidebar-bg, #0B1220);
  padding: 0;
  display: flex;
  flex-direction: column;
  position: fixed;
  height: 100vh;
  z-index: 200;
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  border-right: 1px solid rgba(255, 255, 255, 0.05);
  overflow-y: auto;
  overflow-x: hidden;
}

html[data-design="classic"] .sidebar-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 20px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  margin-bottom: 8px;
  flex-shrink: 0;
}

html[data-design="classic"] .logo {
  color: #fff;
  font-size: 18px;
  font-weight: 700;
  letter-spacing: -0.3px;
  display: flex;
  align-items: center;
  gap: 10px;
}
html[data-design="classic"] .logo-icon {
  height: 26px;
  width: auto;
  flex-shrink: 0;
}

html[data-design="classic"] .sidebar a {
  color: rgba(255, 255, 255, 0.68);
  text-decoration: none;
  padding: 8px 16px 8px 17px;
  font-size: 13.5px;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 10px;
  border-left: 3px solid transparent;
  transition: background 0.13s, color 0.13s, border-color 0.13s;
  margin: 1px 8px;
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
}

html[data-design="classic"] .sidebar a:hover {
  background: rgba(255, 255, 255, 0.06);
  color: rgba(255, 255, 255, 0.92);
}

html[data-design="classic"] .sidebar a.active {
  background: rgba(91, 95, 238, 0.16);
  color: #fff;
  border-left-color: var(--brand-400);
  font-weight: 600;
}

html[data-design="classic"] .sidebar-section-label {
  font-size: 11px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.4);
  padding: 14px 20px 4px;
}

html[data-design="classic"] .menu-close {
  display: none;
  background: transparent;
  color: rgba(255, 255, 255, 0.5);
  font-size: 18px;
  padding: 4px 8px;
}
/* sidebar-top hides when empty on desktop */
html[data-design="classic"] .sidebar-top:has(.menu-close:only-child) {
  display: none;
}
@media (max-width: 768px) {
  html[data-design="classic"] .sidebar-top:has(.menu-close:only-child) {
    display: flex;
  }
}

/* ========================================
   CONTENT & TOPBAR
   /* = */

html[data-design="classic"] .content-wrapper {
  margin-left: var(--sidebar-w);
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

/* Elevation Tier 2 — Raised: sticky over the scrolling canvas below it,
   so it needs to read as nearer than a Tier 1 card, not just outlined.
   The border still does the crisp-edge work; --elevation-2 is what
   makes it register as "in front of" rather than merely "on top of". */
html[data-design="classic"] .topbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 14px;
  background: var(--surface-2, var(--topbar-bg, var(--bg-card, #ffffff)));
  border-bottom: 1px solid var(--border, var(--border));
  height: var(--topbar-h);
  position: sticky;
  top: 0;
  z-index: 99;
  box-shadow: var(--elevation-2);
}
html[data-design="classic"][data-theme="dark"] .topbar {
  background: var(--bg-card, #111827);
  border-bottom-color: rgba(255,255,255,0.07);
}

/* Sidebar toggle icon button */
html[data-design="classic"] .topbar-sidebar-toggle {
  display: flex; align-items: center; justify-content: center;
  width: 30px; height: 30px; border-radius: 7px;
  background: transparent; border: none; cursor: pointer;
  color: var(--gray-500); transition: background 0.13s, color 0.13s;
  flex-shrink: 0;
}
html[data-design="classic"] .topbar-sidebar-toggle:hover { background: var(--gray-100); color: var(--gray-800); }
html[data-design="classic"][data-theme="dark"] .topbar-sidebar-toggle { color: rgba(255,255,255,0.5); }
html[data-design="classic"][data-theme="dark"] .topbar-sidebar-toggle:hover { background: rgba(255,255,255,0.08); color: #fff; }

/* Logo in topbar */
html[data-design="classic"] .topbar-logo-row {
  display: flex; align-items: center;
  gap: 8px;
  flex-shrink: 0;
  border-right: 1px solid var(--border, var(--border));
  padding-right: 16px; margin-right: 4px;
}
html[data-design="classic"] .topbar-logo-img {
  height: 26px;
  width: auto;
  flex-shrink: 0;
}
html[data-design="classic"][data-theme="dark"] .topbar-logo-row { border-right-color: rgba(255,255,255,0.08); }
html[data-design="classic"] .topbar-logo-txt {
  font-size: 18px;
  font-weight: 700;
  letter-spacing: -0.3px;
  white-space: nowrap;
  color: var(--gray-900);
  line-height: 1;
  transition: color 0.15s;
}
html[data-design="classic"] .topbar-logo-txt:hover {
  color: var(--brand-600);
}
html[data-design="classic"][data-theme="dark"] .topbar-logo-txt {
  color: #ffffff;
}
html[data-design="classic"][data-theme="dark"] .topbar-logo-txt:hover {
  color: var(--brand-400);
}

/* Search  grows to fill space */
html[data-design="classic"] .topbar-search-wrap { flex: 1; max-width: 480px; }
html[data-design="classic"] .topbar-search-btn {
  display: flex; align-items: center; gap: 8px;
  height: 32px; padding: 0 12px;
  background: var(--gray-50, var(--gray-50));
  border: 1px solid var(--border, var(--border));
  border-radius: 8px; width: 100%;
  font-size: 12.5px; color: var(--gray-400);
  text-decoration: none; cursor: pointer;
  transition: all 0.13s; box-sizing: border-box;
}
html[data-design="classic"] .topbar-search-btn:hover {
  background: #fff; border-color: var(--brand-400);
  box-shadow: 0 0 0 2px rgba(91,95,238,0.12);
}
html[data-design="classic"] .topbar-search-placeholder { flex: 1; }
html[data-design="classic"] .topbar-search-kbd {
  font-size: 10px; font-weight: 700;
  background: var(--gray-200, var(--border));
  color: var(--gray-500, var(--gray-500));
  padding: 1px 5px; border-radius: 4px;
}
html[data-design="classic"][data-theme="dark"] .topbar-search-btn {
  background: rgba(255,255,255,0.05);
  border-color: rgba(255,255,255,0.1); color: rgba(255,255,255,0.4);
}
html[data-design="classic"][data-theme="dark"] .topbar-search-btn:hover {
  background: rgba(255,255,255,0.08);
  border-color: var(--brand-400,var(--brand-400));
}

/* Right cluster */
html[data-design="classic"] .topbar-right-cluster {
  display: flex; align-items: center;
  gap: 2px; margin-left: auto; flex-shrink: 0;
}
html[data-design="classic"] .topbar-divider-v {
  width: 1px; height: 20px;
  background: var(--border, var(--border));
  margin: 0 4px; flex-shrink: 0;
}
html[data-design="classic"][data-theme="dark"] .topbar-divider-v { background: rgba(255,255,255,0.08); }

/* topbar-search-btn moved to new topbar block */

html[data-design="classic"] .main-content {
  padding: 10px 16px;
  flex: 1;
  overflow: hidden;
  height: calc(100vh - var(--topbar-h));
  max-height: calc(100vh - var(--topbar-h));
  min-height: 0;
  box-sizing: border-box;
  background: var(--bg-main, rgba(255, 255, 255, 0.88));
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  display: flex;
  flex-direction: column;
}
/* Dashboard shell — no padding, scrolling handled by db-root */
html[data-design="classic"] .main-content.db-shell {
  padding: 0;
  overflow: hidden;
}

/* No-padding pages (Docs, etc.) — fills full content area */
html[data-design="classic"] .main-content.no-padding {
  padding: 0;
  overflow: hidden;
  min-height: 0;
}

/* Non-dashboard pages use this class to re-enable scroll */
html[data-design="classic"] .main-content.page-scrollable {
  overflow-y: auto;
  padding: 28px 32px;
}

html[data-design="classic"] .overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(2px);
  z-index: 150;
}

/* ========================================
   PAGE HEADER  Warm Orange Gradient
   /* = */

html[data-design="classic"] .page-header-block {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 28px;
  padding: 22px 28px;
  background: var(--brand-50);
  border-radius: var(--radius-xl);
  border: 1px solid var(--brand-200);
  position: relative;
  overflow: visible;
}
html[data-design="classic"] .page-header-block::before {
  display: none;
}
html[data-design="classic"] .page-header-block::after {
  display: none;
}
html[data-design="classic"] .page-header-geo {
  position: absolute;
  right: 0;
  top: 0;
  width: 280px;
  height: 100%;
  opacity: 0.08;
  pointer-events: none;
  overflow: hidden;
  border-radius: var(--radius-xl);
}
html[data-design="classic"] .page-header-left {
  display: flex;
  flex-direction: column;
  gap: 4px;
  z-index: 1;
}
html[data-design="classic"] .page-header-breadcrumb {
  font-size: 11px;
  color: #0284c7;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  opacity: 0.85;
}
html[data-design="classic"] .page-header-title {
  display: flex;
  align-items: center;
  gap: 10px;
}
html[data-design="classic"] .page-header-title h1 {
  font-size: 24px;
  font-weight: 800;
  color: var(--gray-800);
  letter-spacing: -0.4px;
  line-height: 1.2;
}
html[data-design="classic"] .page-header-icon {
  font-size: 26px;
  line-height: 1;
}
html[data-design="classic"] .page-header-desc {
  font-size: 13px;
  color: var(--brand-700);
  margin-top: 2px;
  opacity: 0.8;
}
html[data-design="classic"] .page-header-action {
  flex-shrink: 0;
  z-index: 1;
}

/* ========================================
   CARDS
   /* = */

html[data-design="classic"] .cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 18px;
  align-items: start;
}

html[data-design="classic"] .project-card {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  overflow: visible;
  box-shadow: var(--shadow-sm);
  transition:
    box-shadow 0.2s,
    transform 0.2s;
}
html[data-design="classic"] .project-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

html[data-design="classic"] .project-color-bar {
  width: 5px;
  flex-shrink: 0;
  border-radius: var(--radius-lg) 0 0 var(--radius-lg);
}
html[data-design="classic"] .project-card-top {
  display: flex;
  border-radius: var(--radius-lg);
  overflow: hidden;
}
html[data-design="classic"] .project-card-body {
  padding: 18px;
  flex: 1;
}
html[data-design="classic"] .project-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 6px;
}
html[data-design="classic"] .project-card-header h3 {
  font-size: 15px;
  font-weight: 700;
  color: var(--gray-800);
}
html[data-design="classic"] .project-desc {
  color: var(--gray-500);
  font-size: 13px;
  margin-bottom: 14px;
  min-height: 20px;
  line-height: 1.5;
}
html[data-design="classic"] .project-card-footer {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 10px;
  font-size: 12px;
  color: var(--gray-500);
}
html[data-design="classic"] .project-footer-row1 {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
html[data-design="classic"] .project-progress-text {
  font-size: 12px;
  color: var(--gray-500);
}
html[data-design="classic"] .project-footer-actions {
  display: flex;
  gap: 2px;
  align-items: center;
}
html[data-design="classic"] .project-footer-row2 {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  align-items: center;
}

/*  Progress Bar  */
html[data-design="classic"] .progress-bar {
  height: 6px;
  background: var(--gray-100);
  border-radius: var(--radius-full);
  overflow: hidden;
  margin-bottom: 8px;
}
html[data-design="classic"] .progress-fill {
  height: 100%;
  border-radius: var(--radius-full);
  transition: width 0.4s ease;
}

/*  Badges  */
html[data-design="classic"] .badge {
  font-size: 11px;
  padding: 3px 9px;
  border-radius: var(--radius-full);
  font-weight: 600;
  letter-spacing: 0.02em;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  /* Same fix as .role-badge in workspace.css: without this, a badge
     sitting in a flex row next to a flex:1 sibling can get compressed
     below its own text's natural width and visually spill past its pill
     background instead of the row simply running out of horizontal
     space gracefully. */
  white-space: nowrap;
  flex-shrink: 0;
}
html[data-design="classic"] .badge-active {
  background: #e0f2fe;
  color: #0369a1;
}
html[data-design="classic"] .badge-done {
  background: #d1fae5;
  color: #065f46;
}
html[data-design="classic"] .badge-achieved {
  background: #d1fae5;
  color: #065f46;
}
html[data-design="classic"] .badge-inactive {
  background: var(--gray-100);
  color: var(--gray-600);
}
html[data-design="classic"] .badge-todo {
  background: #ede9fe;
  color: #5b21b6;
}
html[data-design="classic"] .badge-in_progress {
  background: #fef3c7;
  color: #92400e;
}

/*  Card Actions  */
html[data-design="classic"] .card-actions {
  display: flex;
  gap: 4px;
}

/* ========================================
   TASK ROWS
   /* = */

html[data-design="classic"] .task-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

html[data-design="classic"] .task-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  background: var(--bg-card);
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-xs);
  transition: all 0.15s;
}
html[data-design="classic"] .task-row:hover {
  border-color: var(--brand-200);
  box-shadow: var(--shadow-sm);
  background: var(--bg-card);
}

html[data-design="classic"] .task-status-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  flex-shrink: 0;
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.8);
}

html[data-design="classic"] .task-info {
  flex: 1;
  min-width: 0;
}
html[data-design="classic"] .task-title {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--gray-800);
  margin-bottom: 3px;
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
html[data-design="classic"] .task-meta {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  align-items: center;
  font-size: 12px;
  color: var(--gray-500);
}
html[data-design="classic"] .task-project {
  color: #0369a1;
  font-weight: 500;
  background: #e0f2fe;
  padding: 1px 8px;
  border-radius: var(--radius-full);
}
html[data-design="classic"] .task-tag {
  background: var(--gray-100);
  color: var(--gray-600);
  padding: 1px 8px;
  border-radius: var(--radius-full);
  font-size: 11px;
  font-weight: 500;
}
html[data-design="classic"] .task-badges {
  display: flex;
  gap: 6px;
  align-items: center;
  flex-shrink: 0;
}

/*  Task Highlight  */
html[data-design="classic"] .task-row-highlight {
  border-color: var(--highlight-color, var(--danger)) !important;
  background: var(--highlight-bg, #fff5f5) !important;
  box-shadow: 0 0 0 3px var(--highlight-shadow, rgba(239, 68, 68, 0.15)) !important;
  animation: classic-highlightPulse 2s ease;
}
@keyframes classic-highlightPulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.8;
  }
}

/* ========================================
   MODALS
   /* = */

html[data-design="classic"] .modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 10, 5, 0.65);
  /* backdrop-filter removed */
  z-index: 500;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: classic-fadeIn 0.2s ease;
}
@keyframes classic-fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

html[data-design="classic"] .modal {
  background: var(--bg-card);
  border-radius: var(--radius-xl);
  padding: 28px;
  width: 100%;
  max-width: 540px;
  max-height: 90vh;
  overflow-y: auto;
  box-shadow: var(--shadow-xl);
  border: 1px solid rgba(255, 255, 255, 0.8);
  animation: classic-slideUp 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}
@keyframes classic-slideUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

html[data-design="classic"] .modal h2 {
  font-size: 18px;
  font-weight: 700;
  color: var(--gray-900);
  margin-bottom: 20px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--border);
}

html[data-design="classic"] .form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid var(--border);
}

/* ========================================
   GOAL CARDS
   /* = */

html[data-design="classic"] .goal-card {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  box-shadow: var(--shadow-sm);
  transition:
    box-shadow 0.2s,
    transform 0.2s;
}
html[data-design="classic"] .goal-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}
html[data-design="classic"] .goal-card-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 10px;
}
html[data-design="classic"] .goal-card-header h3 {
  font-size: 15px;
  font-weight: 700;
  color: var(--gray-800);
}
html[data-design="classic"] .goal-date {
  font-size: 12px;
  color: var(--gray-500);
  display: flex;
  align-items: center;
  gap: 4px;
}
html[data-design="classic"] .goal-progress-label {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: var(--gray-500);
  margin-bottom: 4px;
  font-weight: 500;
}
html[data-design="classic"] .goal-stats-row {
  display: flex;
  gap: 16px;
  font-size: 12px;
  color: var(--gray-500);
}
html[data-design="classic"] .goal-card-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: auto;
}

/* ========================================
   CATEGORY CARDS
   /* = */

html[data-design="classic"] .category-card {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  padding: 18px;
  display: flex;
  align-items: center;
  gap: 14px;
  box-shadow: var(--shadow-sm);
  transition: all 0.2s;
}
html[data-design="classic"] .category-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}
html[data-design="classic"] .category-icon {
  font-size: 26px;
}
html[data-design="classic"] .category-info {
  flex: 1;
}
html[data-design="classic"] .category-info h3 {
  font-size: 15px;
  font-weight: 700;
}

/* ========================================
   FILTER BAR
   /* = */

html[data-design="classic"] .filter-bar {
  display: flex;
  gap: 10px;
  margin-bottom: 20px;
  flex-wrap: wrap;
  align-items: center;
  background: var(--bg-card);
  padding: 14px 18px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-xs);
}
html[data-design="classic"] .filter-bar select,
html[data-design="classic"] .filter-bar input {
  max-width: 180px;
  font-size: 13px;
  padding: 7px 12px;
}

/* ========================================
   EMPTY STATE
   /* = */

html[data-design="classic"] .empty-state {
  text-align: center;
  color: var(--gray-400);
  padding: 48px 24px;
  font-size: 14px;
  font-weight: 500;
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  border: 2px dashed var(--border);
}

/* ========================================
   BREADCRUMB
   /* = */

html[data-design="classic"] .breadcrumb-bar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 2px;
  margin-bottom: 14px;
  padding: 0;
  background: transparent;
  border-radius: 0;
  border: none;
  font-size: 12px;
  box-shadow: none;
  width: fit-content;
}
html[data-design="classic"] .breadcrumb-item {
  display: flex;
  align-items: center;
  gap: 2px;
}
html[data-design="classic"] .breadcrumb-sep {
  color: var(--gray-400);
  margin: 0 3px;
  font-size: 12px;
}
html[data-design="classic"] .breadcrumb-link {
  background: transparent;
  color: #0284c7;
  font-size: 12px;
  font-weight: 500;
  padding: 2px 6px;
  border-radius: var(--radius-sm);
}
html[data-design="classic"] .breadcrumb-link:hover {
  background: #e0f2fe;
}
html[data-design="classic"] .breadcrumb-current {
  color: var(--gray-600);
  font-weight: 600;
  font-size: 12px;
  padding: 2px 6px;
}

/*  Topbar icon buttons  all consistent  */
html[data-design="classic"] .theme-toggle,
html[data-design="classic"] .notif-bell-btn,
html[data-design="classic"] .theme-switcher-btn {
  background: transparent;
  font-size: 17px;
  width: 34px;
  height: 34px;
  padding: 0;
  border-radius: 9px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  flex-shrink: 0;
  border: 1.5px solid transparent;
  color: var(--gray-500);
  transition: all 0.15s;
  position: relative;
  box-sizing: border-box;
}
html[data-design="classic"] .theme-toggle:hover,
html[data-design="classic"] .notif-bell-btn:hover,
html[data-design="classic"] .theme-switcher-btn:hover {
  background: linear-gradient(var(--gray-50,var(--gray-50)),var(--gray-50,var(--gray-50))) padding-box,
              linear-gradient(135deg,var(--danger),#f97316,var(--warning),var(--success),var(--brand-500)) border-box;
  color: var(--gray-800);
  box-shadow: 0 0 10px rgba(99,102,241,0.15);
  transform: translateY(-1px);
}
html[data-design="classic"][data-theme="dark"] .theme-toggle,
html[data-design="classic"][data-theme="dark"] .notif-bell-btn,
html[data-design="classic"][data-theme="dark"] .theme-switcher-btn {
  color: rgba(255,255,255,0.6);
}
html[data-design="classic"][data-theme="dark"] .theme-toggle:hover,
html[data-design="classic"][data-theme="dark"] .notif-bell-btn:hover,
html[data-design="classic"][data-theme="dark"] .theme-switcher-btn:hover {
  background: linear-gradient(rgba(255,255,255,0.08),rgba(255,255,255,0.08)) padding-box,
              linear-gradient(135deg,var(--danger),#f97316,var(--warning),var(--success),var(--brand-500)) border-box;
  color: #fff;
  box-shadow: 0 0 14px rgba(99,102,241,0.25);
}

html[data-design="classic"] .notif-bell-wrapper {
  position: relative;
}
html[data-design="classic"] .notif-bell-badge {
  position: absolute;
  top: 3px;
  right: 3px;
  background: var(--danger);
  color: #fff;
  font-size: 9px;
  font-weight: 700;
  min-width: 16px;
  height: 16px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 3px;
  pointer-events: none;
  line-height: 1;
}
html[data-design="classic"] .user-avatar-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 34px;
  padding: 0 10px 0 5px;
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.15s;
  margin-left: 4px;
  position: relative;
  border: 1.5px solid transparent;
  box-sizing: border-box;
}
html[data-design="classic"] .user-avatar-btn:hover {
  background: linear-gradient(var(--gray-50,var(--gray-50)),var(--gray-50,var(--gray-50))) padding-box,
              linear-gradient(135deg,var(--danger),#f97316,var(--warning),var(--success),var(--brand-500)) border-box;
  box-shadow: 0 0 12px rgba(99,102,241,0.15);
  transform: translateY(-1px);
}
html[data-design="classic"][data-theme="dark"] .user-avatar-btn:hover {
  background: linear-gradient(rgba(255,255,255,0.07),rgba(255,255,255,0.07)) padding-box,
              linear-gradient(135deg,var(--danger),#f97316,var(--warning),var(--success),var(--brand-500)) border-box;
  box-shadow: 0 0 16px rgba(99,102,241,0.25);
}

html[data-design="classic"] .user-avatar {
  width: 32px; height: 32px;
  border-radius: 50%;
  background: linear-gradient(135deg, #0ea5e9, #0369a1);
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  box-shadow: 0 2px 4px rgba(99,102,241,0.3);
}
html[data-design="classic"] .user-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--gray-700);
  max-width: 140px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
html[data-design="classic"] .user-menu-dropdown {
  position: absolute;
  right: 0;
  top: calc(100% + 6px);
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  z-index: 1000;
  width: 230px;
  overflow: hidden;
}
html[data-design="classic"] .user-menu-info {
  padding: 14px 16px;
  background: var(--gray-50);
  border-bottom: 1px solid var(--border);
}
html[data-design="classic"] .user-menu-divider {
  height: 1px;
  background: var(--border);
}
html[data-design="classic"] .user-menu-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  text-align: left;
  padding: 11px 16px;
  font-size: 13px;
  background: transparent;
  color: var(--gray-700);
  border-radius: 0;
  font-weight: 500;
  cursor: pointer;
  border: none;
  transition: background 0.1s;
}
html[data-design="classic"] .user-menu-item:hover {
  background: var(--gray-50);
  color: var(--brand-600);
}

/* ========================================
   NOTIFICATION PANEL
   /* = */

html[data-design="classic"] .notif-panel {
  position: absolute;
  right: 0;
  top: calc(100% + 8px);
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-xl);
  z-index: 1000;
  width: 380px;
  overflow: hidden;
  animation: classic-slideUp 0.2s ease;
}
html[data-design="classic"] .notif-panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 18px;
  border-bottom: 1px solid var(--border);
  background: var(--gray-50);
}
html[data-design="classic"] .notif-unread-badge {
  background: var(--brand-500);
  color: #fff;
  border: 1px solid var(--brand-600);
  font-size: 10px;
  padding: 2px 8px;
  border-radius: var(--radius-full);
  margin-left: 8px;
  font-weight: 600;
}
html[data-design="classic"] .notif-list {
  max-height: 420px;
  overflow-y: auto;
}
html[data-design="classic"] .notif-item {
  display: flex;
  gap: 12px;
  padding: 14px 18px;
  cursor: pointer;
  transition: background 0.15s;
  border-bottom: 1px solid var(--gray-50);
  align-items: flex-start;
}
html[data-design="classic"] .notif-item:hover  { background: var(--gray-50); }
html[data-design="classic"] .notif-item.unread { background: var(--brand-50); }
html[data-design="classic"] .notif-item-icon {
  width: 34px;
  height: 34px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  flex-shrink: 0;
}
html[data-design="classic"] .notif-item-content { flex: 1; min-width: 0; }
html[data-design="classic"] .notif-item-title {
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 2px;
}
html[data-design="classic"] .notif-item-message {
  font-size: 12px;
  color: var(--gray-500);
  margin-bottom: 3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
html[data-design="classic"] .notif-item-time { font-size: 11px; color: var(--gray-400); }
html[data-design="classic"] .notif-unread-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--brand-500);
  flex-shrink: 0;
  margin-top: 4px;
}
html[data-design="classic"] .notif-empty {
  text-align: center;
  padding: 40px 16px;
  color: var(--gray-400);
}

html[data-design="classic"][data-theme="dark"] .notif-panel         { background: #071525; border-color: #1e3a5a; }
html[data-design="classic"][data-theme="dark"] .notif-panel-header  { background: #050f1e; border-color: #1e3a5a; }
html[data-design="classic"][data-theme="dark"] .notif-item          { border-color: #050f1e; }
html[data-design="classic"][data-theme="dark"] .notif-item:hover    { background: #0a1e35; }
html[data-design="classic"][data-theme="dark"] .notif-item.unread   { background: #1e1f35; }

/* ========================================
   REAL-TIME: CONNECTION STATUS + LIVE FEED
   /* = */

/* Connection status dot in topbar */
html[data-design="classic"] .ws-status {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 34px;
  padding: 0 12px;
  border-radius: var(--radius-full);
  cursor: default;
  border: 1.5px solid transparent;
  box-sizing: border-box;
  /* Solid green background so text is readable against it */
  background: linear-gradient(var(--success),var(--success)) padding-box,
              linear-gradient(135deg,var(--success),var(--success),#6ee7b7) border-box;
  transition: all 0.15s;
  flex-shrink: 0;
}
html[data-design="classic"][data-theme="dark"] .ws-status {
  background: linear-gradient(var(--success),var(--success)) padding-box,
              linear-gradient(135deg,var(--success),var(--success),#6ee7b7) border-box;
}
html[data-design="classic"] .ws-dot {
  width: 7px; height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}
html[data-design="classic"] .ws-dot-live {
  background: #fff;
  box-shadow: 0 0 0 2px rgba(255,255,255,0.35);
  animation: classic-ws-pulse 2s ease-in-out infinite;
}
html[data-design="classic"] .ws-dot-off  { background: rgba(255,255,255,0.5); }
/* White text on green background  always readable in light AND dark mode */
html[data-design="classic"] .ws-label    { font-size: 11px; font-weight: 700; color: #ffffff; letter-spacing: 0.04em; }

@keyframes classic-ws-pulse-inner {
  0%, 100% { box-shadow: 0 0 0 2px rgba(255,255,255,0.35); }
  50%       { box-shadow: 0 0 0 5px rgba(255,255,255,0.1); }
}

@keyframes classic-ws-pulse {
  0%, 100% { box-shadow: 0 0 0 2px rgba(16,185,129,0.25); }
  50%       { box-shadow: 0 0 0 5px rgba(16,185,129,0.1);  }
}

/* Live activity feed  bottom-right floating toasts */
html[data-design="classic"] .live-feed-container {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  gap: 8px;
  pointer-events: none;
  max-width: 340px;
}
html[data-design="classic"] .live-feed-toast {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-left: 4px solid #0ea5e9;
  border-radius: var(--radius-lg);
  padding: 12px 14px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.12);
  pointer-events: all;
  animation: classic-toast-in 0.25s cubic-bezier(0.34,1.56,0.64,1);
}
html[data-design="classic"] .live-feed-toast.leaving {
  animation: classic-toast-out 0.25s ease forwards;
}
@keyframes classic-toast-in {
  from { opacity: 0; transform: translateX(60px) scale(0.95); }
  to   { opacity: 1; transform: translateX(0)    scale(1);    }
}
@keyframes classic-toast-out {
  from { opacity: 1; transform: translateX(0)    scale(1);    }
  to   { opacity: 0; transform: translateX(60px) scale(0.95); }
}
html[data-design="classic"] .live-feed-icon    { font-size: 18px; flex-shrink: 0; margin-top: 1px; }
html[data-design="classic"] .live-feed-body    { flex: 1; min-width: 0; }
html[data-design="classic"] .live-feed-message { font-size: 13px; font-weight: 500; color: var(--gray-800); line-height: 1.4; }
html[data-design="classic"] .live-feed-close {
  background: transparent; border: none;
  font-size: 12px; color: var(--gray-400);
  cursor: pointer; padding: 0 2px;
  flex-shrink: 0; line-height: 1;
  transition: color 0.1s;
}
html[data-design="classic"] .live-feed-close:hover { color: var(--gray-700); }

html[data-design="classic"][data-theme="dark"] .live-feed-toast   { background: #071525; border-color: #1e3a5a; }
html[data-design="classic"][data-theme="dark"] .live-feed-message { color: var(--gray-200); }

/* ========================================
   COMMAND PALETTE
   /* = */

html[data-design="classic"] .cp-overlay {
  position: fixed; inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 9000;
  display: flex; align-items: flex-start; justify-content: center;
  padding-top: 80px;
  backdrop-filter: blur(2px);
}
html[data-design="classic"] .cp-modal {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  width: 100%; max-width: 580px;
  box-shadow: 0 24px 60px rgba(0,0,0,0.25);
  overflow: hidden;
  animation: classic-cp-in 0.15s cubic-bezier(0.34,1.56,0.64,1);
}
@keyframes classic-cp-in {
  from { opacity:0; transform: scale(0.96) translateY(-10px); }
  to   { opacity:1; transform: scale(1)    translateY(0);     }
}
html[data-design="classic"] .cp-input-wrap {
  display: flex; align-items: center; gap: 10px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--border);
}
html[data-design="classic"] .cp-search-icon { font-size: 18px; color: var(--gray-400); flex-shrink: 0; }
html[data-design="classic"] .cp-input {
  flex: 1; border: none; background: transparent;
  font-size: 16px; color: var(--gray-800);
  outline: none; padding: 0;
}
html[data-design="classic"] .cp-input::placeholder { color: var(--gray-400); }
html[data-design="classic"] .cp-clear {
  background: transparent; border: none;
  color: var(--gray-400); cursor: pointer;
  font-size: 14px; padding: 2px 6px;
  border-radius: var(--radius-sm);
  transition: background 0.1s;
}
html[data-design="classic"] .cp-clear:hover { background: var(--gray-100); }
html[data-design="classic"] .cp-results { max-height: 400px; overflow-y: auto; }
html[data-design="classic"] .cp-empty { padding: 32px; text-align: center; color: var(--gray-400); font-size: 14px; }
html[data-design="classic"] .cp-group { }
html[data-design="classic"] .cp-group-label {
  font-size: 10px; font-weight: 800; letter-spacing: 0.08em;
  text-transform: uppercase; color: var(--gray-400);
  padding: 10px 16px 4px;
}
html[data-design="classic"] .cp-item {
  display: flex; align-items: center; gap: 12px;
  padding: 10px 16px;
  cursor: pointer; transition: background 0.1s;
}
html[data-design="classic"] .cp-item:hover, html[data-design="classic"] .cp-item-selected { background: var(--brand-50); }
html[data-design="classic"] .cp-item-icon  { font-size: 16px; flex-shrink: 0; width: 24px; text-align: center; }
html[data-design="classic"] .cp-item-body  { flex: 1; min-width: 0; display: flex; align-items: center; gap: 8px; }
html[data-design="classic"] .cp-item-label { font-size: 14px; font-weight: 500; color: var(--gray-800); }
html[data-design="classic"] .cp-item-sub   { font-size: 11px; color: var(--gray-400); }
html[data-design="classic"] .cp-item-hint  {
  font-size: 10px; font-weight: 700;
  padding: 2px 6px; border-radius: 4px;
  background: var(--gray-100); color: var(--gray-500);
  flex-shrink: 0;
}
html[data-design="classic"] .cp-item-hint-action { background: var(--brand-100); color: var(--brand-700); }
html[data-design="classic"] .cp-highlight  { background: #fef08a; color: inherit; border-radius: 2px; font-weight: 700; }
html[data-design="classic"] .cp-footer {
  display: flex; gap: 16px; align-items: center;
  padding: 8px 16px;
  border-top: 1px solid var(--border);
  background: var(--gray-50);
  font-size: 11px; color: var(--gray-400);
}
html[data-design="classic"] .cp-footer kbd {
  background: var(--gray-200); color: var(--gray-600);
  padding: 1px 5px; border-radius: 3px;
  font-size: 10px; font-family: inherit;
}

/* Shortcuts help modal */
html[data-design="classic"] .shortcuts-modal {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  width: 100%; max-width: 440px;
  box-shadow: 0 24px 60px rgba(0,0,0,0.25);
  overflow: hidden;
  animation: classic-cp-in 0.15s ease;
}
html[data-design="classic"] .shortcuts-header {
  display: flex; justify-content: space-between; align-items: center;
  padding: 16px 20px;
  font-size: 15px; font-weight: 800; color: var(--gray-800);
  border-bottom: 1px solid var(--border);
}
html[data-design="classic"] .shortcuts-list    { padding: 8px 0; max-height: 440px; overflow-y: auto; }
html[data-design="classic"] .shortcuts-section {
  font-size: 10px; font-weight: 800; letter-spacing: 0.08em;
  text-transform: uppercase; color: var(--gray-400);
  padding: 10px 20px 4px;
}
html[data-design="classic"] .shortcuts-row {
  display: flex; align-items: center; justify-content: space-between;
  padding: 7px 20px; font-size: 13px;
}
html[data-design="classic"] .shortcuts-row:hover { background: var(--gray-50); }
html[data-design="classic"] .shortcuts-keys { display: flex; gap: 3px; align-items: center; }
html[data-design="classic"] .shortcuts-kbd  {
  background: var(--gray-100); color: var(--gray-700);
  border: 1px solid var(--gray-200);
  padding: 2px 7px; border-radius: 4px;
  font-size: 11px; font-weight: 700; font-family: inherit;
  box-shadow: 0 1px 0 var(--gray-200);
}
html[data-design="classic"] .shortcuts-desc { color: var(--gray-600); font-size: 13px; }

/* K topbar button */
html[data-design="classic"] .topbar-cmdK-btn {
  display: flex;
  align-items: center;
  gap: 2px;
  height: 34px;
  padding: 0 10px;
  border-radius: 9px;
  cursor: pointer;
  font-size: 11px;
  font-weight: 800;
  color: var(--gray-500);
  transition: all 0.15s;
  letter-spacing: 0.02em;
  box-sizing: border-box;
  /* Rainbow gradient border */
  background: linear-gradient(var(--gray-50,var(--gray-50)),var(--gray-50,var(--gray-50))) padding-box,
              linear-gradient(135deg,var(--danger),#f97316,var(--warning),var(--success),var(--brand-500)) border-box;
  border: 1.5px solid transparent;
  flex-shrink: 0;
}
html[data-design="classic"] .topbar-cmdK-btn:hover {
  color: var(--gray-800);
  background: linear-gradient(#fff,#fff) padding-box,
              linear-gradient(135deg,var(--danger),#f97316,var(--warning),var(--success),var(--brand-500)) border-box;
  box-shadow: 0 0 10px rgba(99,102,241,0.15);
  transform: translateY(-1px);
}
html[data-design="classic"] .topbar-cmdK-icon { font-size: 13px; }
html[data-design="classic"] .topbar-cmdK-label { font-size: 11px; }
html[data-design="classic"][data-theme="dark"] .topbar-cmdK-btn {
  color: rgba(255,255,255,0.5);
  background: linear-gradient(rgba(255,255,255,0.06),rgba(255,255,255,0.06)) padding-box,
              linear-gradient(135deg,var(--danger),#f97316,var(--warning),var(--success),var(--brand-500)) border-box;
}
html[data-design="classic"][data-theme="dark"] .topbar-cmdK-btn:hover {
  color: rgba(255,255,255,0.9);
  background: linear-gradient(rgba(255,255,255,0.1),rgba(255,255,255,0.1)) padding-box,
              linear-gradient(135deg,var(--danger),#f97316,var(--warning),var(--success),var(--brand-500)) border-box;
  box-shadow: 0 0 14px rgba(99,102,241,0.25);
}

html[data-design="classic"][data-theme="dark"] .cp-modal           { background: #071525; }
html[data-design="classic"][data-theme="dark"] .cp-input           { color: var(--gray-200); }
html[data-design="classic"][data-theme="dark"] .cp-item:hover,
html[data-design="classic"][data-theme="dark"] .cp-item-selected   { background: #1e1f35; }
html[data-design="classic"][data-theme="dark"] .cp-footer          { background: #050f1e; }
html[data-design="classic"][data-theme="dark"] .shortcuts-modal    { background: #071525; }
html[data-design="classic"][data-theme="dark"] .shortcuts-row:hover { background: #0a1e35; }
html[data-design="classic"][data-theme="dark"] .topbar-cmdK-btn    { background: #0a1e35; color: var(--gray-500); border-color: #1e3a5a; }

/* ========================================
   PWA INSTALL & NOTIFICATION BANNERS
   /* = */

/*  PWA Install Modal  */
html[data-design="classic"] .pwa-backdrop {
  position: fixed; inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 8000;
  backdrop-filter: blur(4px);
  animation: classic-fadeIn 0.2s ease;
}
@keyframes classic-fadeIn { from { opacity:0; } to { opacity:1; } }

html[data-design="classic"] .pwa-modal {
  position: fixed;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  z-index: 8001;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 36px 32px;
  width: 100%; max-width: 420px;
  box-shadow: 0 24px 60px rgba(0,0,0,0.25);
  text-align: center;
  animation: classic-cp-in 0.25s cubic-bezier(0.34,1.56,0.64,1);
}
html[data-design="classic"] .pwa-modal-icon {
  margin-bottom: 20px;
  display: flex; justify-content: center;
}
html[data-design="classic"] .pwa-modal-title {
  font-size: 22px; font-weight: 800;
  color: var(--gray-900); margin: 0 0 10px;
}
html[data-design="classic"] .pwa-modal-desc {
  font-size: 14px; color: var(--gray-500);
  line-height: 1.6; margin: 0 0 24px;
}
html[data-design="classic"] .pwa-modal-features {
  display: flex; flex-direction: column; gap: 14px;
  margin-bottom: 28px; text-align: left;
}
html[data-design="classic"] .pwa-modal-feature {
  display: flex; align-items: flex-start; gap: 12px;
  padding: 12px 14px;
  background: var(--gray-50);
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
}
html[data-design="classic"] .pwa-modal-feature-icon { font-size: 22px; flex-shrink: 0; margin-top: 1px; }
html[data-design="classic"] .pwa-modal-feature-title { font-size: 13px; font-weight: 700; color: var(--gray-800); margin-bottom: 2px; }
html[data-design="classic"] .pwa-modal-feature-desc  { font-size: 12px; color: var(--gray-500); line-height: 1.4; }
html[data-design="classic"] .pwa-modal-actions {
  display: flex; gap: 10px; justify-content: center;
}
html[data-design="classic"] .pwa-modal-cancel  { min-width: 100px; }
html[data-design="classic"] .pwa-modal-install { min-width: 150px; font-size: 14px; padding: 10px 20px; }
html[data-design="classic"] .pwa-modal-success { padding: 8px 0; }

html[data-design="classic"][data-theme="dark"] .pwa-modal         { background: #071525; border-color: #1e3a5a; }
html[data-design="classic"][data-theme="dark"] .pwa-modal-title   { color: var(--gray-100); }
html[data-design="classic"][data-theme="dark"] .pwa-modal-feature { background: #0a1e35; border-color: #1e3a5a; }

/* PWA manual install steps */
html[data-design="classic"] .pwa-install-steps {
  display: flex; flex-direction: column; gap: 12px;
  text-align: left; margin-bottom: 4px;
}
html[data-design="classic"] .pwa-install-step {
  display: flex; gap: 12px; align-items: flex-start;
  padding: 12px 14px;
  background: var(--gray-50); border: 1px solid var(--border);
  border-radius: var(--radius-md);
}
html[data-design="classic"] .pwa-step-num {
  width: 24px; height: 24px; border-radius: 50%;
  background: var(--brand-500); color: #fff;
  font-size: 12px; font-weight: 800;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0; margin-top: 1px;
}
html[data-design="classic"] .pwa-step-title { font-size: 13px; font-weight: 700; color: var(--gray-800); margin-bottom: 3px; }
