html[data-design="classic"][data-theme="dark"] select,
html[data-design="classic"][data-theme="dark"] input,
html[data-design="classic"][data-theme="dark"] textarea                 { background: var(--bg-input); border-color: var(--border); color: var(--gray-700); }
