html[data-design="classic"][data-theme="dark"] .form-group label,
html[data-design="classic"][data-theme="dark"] .form-group legend,
html[data-design="classic"][data-theme="dark"] .form-group .field-label { color: var(--gray-600); }
html[data-design="classic"][data-theme="dark"] .btn-secondary           { background: #1a3550; border-color: var(--border); color: var(--gray-600); }
html[data-design="classic"][data-theme="dark"] .btn-secondary:hover     { background: #163355; color: var(--gray-800); }

/*  Form row (side-by-side fields)  */
html[data-design="classic"] .form-row {
