}
html[data-design="classic"] .task-comment-input-wrap { flex: 1; display: flex; flex-direction: column; gap: 6px; }
html[data-design="classic"] .task-comment-input-row  { position: relative; }
html[data-design="classic"] .task-comment-textarea {
