}
html[data-design="classic"] .comment-reaction-count { font-size: 11px; color: var(--gray-500); font-weight: 600; }

html[data-design="classic"] .comment-reaction-add-wrap { position: relative; }
html[data-design="classic"] .comment-reaction-add-btn {
  padding: 2px 6px;
  border: 1px dashed var(--border);
