}
html[data-design="classic"] .comment-reaction-add-btn:hover { border-color: var(--brand-400); color: var(--brand-500); }
html[data-design="classic"] .comment-reaction-picker {
  position: absolute;
  bottom: calc(100% + 6px);
  left: 0;
  z-index: 200;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
  display: flex;
  gap: 2px;
  padding: 6px;
  flex-wrap: wrap;
