html[data-design="classic"] .comment-reaction-picker-btn {
  font-size: 18px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
  border-radius: 6px;
  transition: background .1s;
}
html[data-design="classic"] .comment-reaction-picker-btn:hover { background: var(--gray-100); }

/*  @Mention autocomplete  */
html[data-design="classic"] .comment-mention {
  color: var(--brand-500);
  font-weight: 600;
  background: rgba(99,102,241,0.08);
  padding: 0 3px;
  border-radius: 3px;
}
html[data-design="classic"] .mention-dropdown {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  z-index: 300;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
  overflow: hidden;
}
html[data-design="classic"] .mention-option {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  cursor: pointer;
  transition: background .1s;
}
html[data-design="classic"] .mention-option:hover, html[data-design="classic"] .mention-option.active { background: var(--gray-50); }
html[data-design="classic"] .mention-avatar {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--brand-500), var(--purple));
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  font-weight: 800;
  flex-shrink: 0;
}
html[data-design="classic"] .mention-name  { font-size: 12px; font-weight: 600; color: var(--gray-700); }
html[data-design="classic"] .mention-email { font-size: 10px; color: var(--gray-400); }

/*  Presence dot  */
html[data-design="classic"] .presence-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  border: 1.5px solid var(--bg-card);
  flex-shrink: 0;
}
html[data-design="classic"] .presence-dot.online  { background: var(--success); }
html[data-design="classic"] .presence-dot.offline { background: var(--gray-300); }


/* ── Priority tag (components/ui/PriorityTag.jsx) ─────────────── */
html[data-design="classic"] .priority-tag { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 600; white-space: nowrap; }
html[data-design="classic"] .priority-tag--high { color: var(--danger-text); }
html[data-design="classic"] .priority-tag--medium { color: var(--warning-text); }
html[data-design="classic"] .priority-tag--low { color: var(--text-secondary, #4A5265); }
/* themes.css sets `[data-theme="dark"] [title] { color: inherit }`; PriorityTag carries a title */
html[data-design="classic"][data-theme="dark"] .priority-tag.priority-tag--high { color: var(--danger-text); }
html[data-design="classic"][data-theme="dark"] .priority-tag.priority-tag--medium { color: var(--warning-text); }
html[data-design="classic"][data-theme="dark"] .priority-tag.priority-tag--low { color: var(--text-secondary); }

/* SecretInput — an API key box drawn as dots, with a Show / Hide button */
html[data-design="classic"] .secret-input-wrap { position: relative; display: flex; align-items: center; flex: 1; min-width: 0; }
html[data-design="classic"] .secret-input-wrap .secret-input { width: 100%; padding-right: 40px; }
html[data-design="classic"] .secret-input--masked { -webkit-text-security: disc; text-security: disc; }
html[data-design="classic"] .secret-input-toggle {
  position: absolute; right: 4px; top: 50%; transform: translateY(-50%);
  display: inline-flex !important; align-items: center; justify-content: center;
  width: 30px; height: 30px; padding: 0 !important;
  border: 0; border-radius: var(--radius-sm); background: transparent; color: var(--text-muted);
}
html[data-design="classic"] .secret-input-toggle:hover { background: var(--gray-100); color: var(--text-primary); }
html[data-design="classic"] .secret-input-toggle:active:not(:disabled) { transform: translateY(-50%); }
html[data-design="classic"][data-theme="dark"] .secret-input-toggle:hover { background: rgba(255,255,255,0.08); }


/* ── src/styles/modals.css ── */
/* ========================================
   MODALS
   /* = */

html[data-design="classic"] .modal-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(15, 10, 5, 0.65);
  /* No backdrop-filter here — it creates a stacking context that breaks
     fixed positioning of child modals */
  z-index: 500;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  box-sizing: border-box;
  animation: classic-fadeIn 0.2s ease;
  overflow-y: auto;
}
@keyframes classic-fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

html[data-design="classic"] .modal {
  background: var(--bg-card);
  border-radius: var(--radius-xl);
  padding: 28px;
  width: 100%;
  max-width: 540px;
  max-height: calc(100vh - 80px);
  overflow-y: auto;
  overflow-x: hidden;
  box-shadow: var(--shadow-xl);
  border: 1px solid rgba(255, 255, 255, 0.8);
  animation: classic-slideUp 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  box-sizing: border-box;
  /* Scrollbar styling */
  scrollbar-width: thin;
  scrollbar-color: var(--gray-300) transparent;
}
html[data-design="classic"] .modal::-webkit-scrollbar { width: 5px; }
html[data-design="classic"] .modal::-webkit-scrollbar-track { background: transparent; }
html[data-design="classic"] .modal::-webkit-scrollbar-thumb { background: var(--gray-300); border-radius: var(--radius-full); }
@keyframes classic-slideUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

html[data-design="classic"] .modal h2 {
  font-size: 18px;
  font-weight: 700;
  color: var(--gray-900);
  margin-bottom: 20px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--border);
}

html[data-design="classic"] .form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid var(--border);
}

   html[data-design="classic"] CONFIRM DIALOG
   

.confirm-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9998;
  animation: classic-fadeIn 0.15s ease;
  backdrop-filter: blur(2px);
}
html[data-design="classic"] .confirm-dialog {
  background: var(--bg-card);
  border-radius: var(--radius-xl, 16px);
  padding: 32px 28px 24px;
  width: 100%;
  max-width: 380px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
  animation: classic-slideUp 0.2s ease;
  text-align: center;
}
html[data-design="classic"] .confirm-icon {
  font-size: 40px;
  margin-bottom: 14px;
  line-height: 1;
}
html[data-design="classic"] .confirm-icon.danger {
  filter: drop-shadow(0 2px 4px rgba(239, 68, 68, 0.3));
}
html[data-design="classic"] .confirm-title {
  font-size: 17px;
  font-weight: 700;
  color: var(--gray-900);
  margin-bottom: 8px;
  line-height: 1.4;
}
html[data-design="classic"] .confirm-message {
  font-size: 13px;
  color: var(--gray-500);
