}
html[data-design="classic"] .confirm-actions .btn-primary,
html[data-design="classic"] .confirm-actions .btn-danger,
html[data-design="classic"] .confirm-actions .btn-secondary {
  min-width: 100px;
  padding: 10px 20px;
}

@keyframes classic-fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
html[data-design="classic"][data-theme="dark"] .confirm-dialog {
