/* ========================================
   DATE TIME PICKER
   /* = */

html[data-design="classic"] .dtp-container {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
}
html[data-design="classic"] .dtp-time {
  display: flex;
  align-items: center;
  gap: 4px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 4px 8px;
  height: 38px;
}
html[data-design="classic"] .dtp-time.dtp-disabled {
  opacity: 0.4;
  pointer-events: none;
}
html[data-design="classic"] .dtp-hm {
  width: 32px !important;
  border: none !important;
  background: transparent !important;
  text-align: center;
  font-size: 14px;
  font-weight: 600;
  padding: 0 !important;
  color: var(--gray-800);
}
html[data-design="classic"] .dtp-hm:focus {
  outline: none;
}
html[data-design="classic"] .dtp-colon {
  font-weight: 700;
  color: var(--gray-500);
  font-size: 14px;
  line-height: 1;
  margin: 0 1px;
}
html[data-design="classic"] .dtp-period {
  display: flex;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  overflow: hidden;
  margin-left: 6px;
}
html[data-design="classic"] .dtp-period-btn {
  padding: 3px 7px;
  font-size: 11px;
  font-weight: 700;
  background: transparent;
  color: var(--gray-500);
  transition: all 0.15s;
  line-height: 1;
}
html[data-design="classic"] .dtp-period-btn.active {
  background: var(--brand-600);
  color: #fff;
}
html[data-design="classic"] .dtp-period-btn:hover:not(.active) {
  background: var(--gray-50);
}

html[data-design="classic"][data-theme="dark"] .dtp-hm {
  color: var(--gray-800);
}
html[data-design="classic"][data-theme="dark"] .dtp-time {
  background: var(--bg-card);
}

/* ========================================
   TOAST NOTIFICATIONS
   /* = */

html[data-design="classic"] .toast-container {
  position: fixed;
  top: 24px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 9999;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  width: auto;
  max-width: 480px;
  pointer-events: none;
}
html[data-design="classic"] .toast {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 13px 16px;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-xl);
  font-size: 14px;
  font-weight: 500;
  animation: classic-slideUp 0.25s ease;
  pointer-events: all;
  min-width: 280px;
}
html[data-design="classic"] .toast-success {
  background: #d1fae5;
  color: #065f46;
  border: 1px solid #a7f3d0;
}
html[data-design="classic"] .toast-error {
  background: #fef2f2;
  color: #991b1b;
  border: 1px solid #fecaca;
}
html[data-design="classic"] .toast-warning {
  background: #fffbeb;
  color: #92400e;
  border: 1px solid #fde68a;
}
html[data-design="classic"] .toast-info {
  background: #eff6ff;
  color: #1e40af;
  border: 1px solid #bfdbfe;
}
html[data-design="classic"] .toast-icon {
  font-size: 16px;
  flex-shrink: 0;
}
html[data-design="classic"] .toast-message {
  flex: 1;
  line-height: 1.4;
}
html[data-design="classic"] .toast-close {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 14px;
  opacity: 0.5;
  padding: 0;
  flex-shrink: 0;
  color: inherit;
  transition: opacity 0.15s;
}
html[data-design="classic"] .toast-close:hover {
  opacity: 1;
}

html[data-design="classic"][data-theme="dark"] .toast-success {
  background: #052e16;
  border-color: #166534;
  color: #86efac;
}
html[data-design="classic"][data-theme="dark"] .toast-error {
  background: #1e0808;
  border-color: #7f1d1d;
  color: #fca5a5;
}
html[data-design="classic"][data-theme="dark"] .toast-warning {
  background: #1c1207;
  border-color: #78350f;
  color: #fcd34d;
}
html[data-design="classic"][data-theme="dark"] .toast-info {
  background: #0c1a3a;
  border-color: #1e3a8a;
  color: #93c5fd;
}


/* ========================================
   MODALS  DARK MODE (comprehensive)
   /* = */

html[data-design="classic"][data-theme="dark"] .modal-overlay          { background: rgba(0,0,0,0.75); }
html[data-design="classic"][data-theme="dark"] .modal                  { background: #081628; border-color: #1a3550; }
html[data-design="classic"][data-theme="dark"] .modal-header           { border-color: #1a3550; color: var(--gray-800); }
html[data-design="classic"][data-theme="dark"] .modal-footer           { border-color: #1a3550; background: #050f1e; }
html[data-design="classic"][data-theme="dark"] .modal-section-title    { color: var(--gray-600); border-color: #1a3550; }
html[data-design="classic"][data-theme="dark"] .confirm-dialog         { background: #081628; border-color: #1a3550; }
html[data-design="classic"][data-theme="dark"] .confirm-title          { color: var(--gray-800); }
html[data-design="classic"][data-theme="dark"] .confirm-message        { color: var(--gray-600); }
html[data-design="classic"][data-theme="dark"] .toast                  { background: #071525; border-color: #1e3a5a; color: var(--gray-700); }
html[data-design="classic"][data-theme="dark"] .toast-success          { border-left-color: var(--success); }
html[data-design="classic"][data-theme="dark"] .toast-error            { border-left-color: var(--danger); }
html[data-design="classic"][data-theme="dark"] .toast-info             { border-left-color: #0ea5e9; }
html[data-design="classic"][data-theme="dark"] .datetime-picker        { background: #081628; border-color: #1a3550; }
html[data-design="classic"][data-theme="dark"] .datetime-picker input  { background: var(--bg-input); border-color: var(--border); color: var(--gray-700); }

/* ── Structured modal with fixed header/footer and scrollable body ── */
html[data-design="classic"] .modal-structured {
  background: var(--bg-card);
  border-radius: var(--radius-xl);
  width: 100%;
  max-width: 560px;
  max-height: calc(100vh - 80px);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-shadow: var(--shadow-xl);
  border: 1px solid rgba(255,255,255,0.8);
  animation: classic-slideUp 0.25s cubic-bezier(0.4,0,0.2,1);
  box-sizing: border-box;
}
html[data-design="classic"] .modal-structured .modal-header {
  padding: 18px 22px;
  border-bottom: 1px solid var(--border);
  flex-shrink: 0;
}
html[data-design="classic"] .modal-structured .modal-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 20px 22px;
  scrollbar-width: thin;
  scrollbar-color: var(--gray-300) transparent;
}
html[data-design="classic"] .modal-structured .modal-body::-webkit-scrollbar { width: 5px; }
html[data-design="classic"] .modal-structured .modal-body::-webkit-scrollbar-thumb { background: var(--gray-300); border-radius: var(--radius-full); }
html[data-design="classic"] .modal-structured .modal-footer {
  padding: 14px 22px;
  border-top: 1px solid var(--border);
  flex-shrink: 0;
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}


/* ── src/styles/tasks.css ── */
/* ========================================
   TASK ROWS
   /* = */

html[data-design="classic"] .task-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

html[data-design="classic"] .task-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  padding: 12px 16px;
  background: #fff;
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-xs);
  transition: all 0.15s;
  position: relative;
}
html[data-design="classic"] .task-row:hover {
  border-color: var(--brand-200);
  box-shadow: var(--shadow-sm);
  background: var(--bg-card);
}

html[data-design="classic"] .task-status-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  flex-shrink: 0;
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.8);
}

html[data-design="classic"] .task-info {
  flex: 1;
  min-width: 0;
}
html[data-design="classic"] .task-title {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--gray-800);
  margin-bottom: 3px;
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: nowrap;
}
html[data-design="classic"] .task-meta {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  align-items: center;
  font-size: 12px;
  color: var(--gray-500);
}
html[data-design="classic"] .task-project {
  color: var(--brand-500);
  font-weight: 500;
  background: #e0f2fe;
  padding: 1px 8px;
  border-radius: var(--radius-full);
}
html[data-design="classic"] .task-tag {
  background: var(--gray-100);
  color: var(--gray-600);
  padding: 1px 8px;
  border-radius: var(--radius-full);
  font-size: 11px;
  font-weight: 500;
}
html[data-design="classic"] .task-badges {
  display: flex;
  gap: 6px;
  align-items: center;
  flex-shrink: 0;
}

/*  Task Highlight  */
html[data-design="classic"] .task-row-highlight {
  border-color: var(--highlight-color, var(--danger)) !important;
  background: var(--highlight-bg, #fff5f5) !important;
  box-shadow: 0 0 0 3px var(--highlight-shadow, rgba(239, 68, 68, 0.15)) !important;
  animation: classic-highlightPulse 2s ease;
}
@keyframes classic-highlightPulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.8;
  }
}

/* ========================================
   TASK INLINE TOOLS (Comments, Time, Files, Deps)
   /* = */

html[data-design="classic"] .task-comments-wrapper,
html[data-design="classic"] .time-tracker-wrapper,
html[data-design="classic"] .file-attachments-wrapper,
html[data-design="classic"] .task-deps-wrapper {
  position: relative;
}

html[data-design="classic"] .task-comments-toggle,
html[data-design="classic"] .time-tracker-toggle,
html[data-design="classic"] .file-attach-toggle,
html[data-design="classic"] .task-deps-toggle {
  background: transparent;
  color: var(--gray-500);
  font-size: 11px;
  padding: 3px 10px;
  border-radius: var(--radius-full);
  border: 1px solid var(--border);
  height: 24px;
  display: inline-flex;
  align-items: center;
  white-space: nowrap;
  gap: 4px;
  transition: all 0.15s;
  font-weight: 500;
}
html[data-design="classic"] .task-comments-toggle:hover {
  background: var(--brand-50);
  color: var(--brand-600);
  border-color: var(--brand-200);
}
html[data-design="classic"] .time-tracker-toggle:hover {
  background: #f0f9ff;
  color: var(--brand-500);
  border-color: #bae6fd;
}
html[data-design="classic"] .file-attach-toggle:hover {
  background: #fff7ed;
  color: var(--warning);
  border-color: #fed7aa;
}
html[data-design="classic"] .task-deps-toggle:hover {
  background: #f0f9ff;
  color: var(--brand-500);
  border-color: #bae6fd;
}

html[data-design="classic"] .task-comments-panel,
html[data-design="classic"] .time-tracker-panel,
html[data-design="classic"] .file-attachments-panel,
html[data-design="classic"] .task-deps-panel {
  position: absolute;
  left: 0;
  top: 30px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  z-index: 60;
  padding: 16px;
  animation: classic-slideUp 0.2s ease;
}
html[data-design="classic"] .task-comments-panel {
  width: 340px;
}
html[data-design="classic"] .time-tracker-panel {
  width: 300px;
}
html[data-design="classic"] .file-attachments-panel {
  width: 320px;
}
html[data-design="classic"] .task-deps-panel {
  width: 340px;
}

html[data-design="classic"] .task-comments-header {
  font-size: 11px;
  font-weight: 700;
  color: var(--gray-500);
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
html[data-design="classic"] .task-comments-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 12px;
  max-height: 220px;
  overflow-y: auto;
}
html[data-design="classic"] .task-comment-item {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  background: var(--gray-50);
  border-radius: var(--radius-md);
  padding: 10px 12px;
}
html[data-design="classic"] .task-comment-body {
  flex: 1;
}
html[data-design="classic"] .task-comment-author {
  font-size: 11px;
  font-weight: 700;
  color: var(--brand-500);
  margin-bottom: 2px;
}
html[data-design="classic"] .task-comment-text {
  font-size: 12px;
  color: var(--gray-700);
  margin-bottom: 2px;
}
html[data-design="classic"] .task-comment-date {
  font-size: 10px;
  color: var(--gray-400);
}
html[data-design="classic"] .task-comment-add {
  display: flex;
  flex-direction: column;
  gap: 6px;
  border-top: 1px solid var(--border);
  padding-top: 12px;
}

html[data-design="classic"] .time-tracker-total {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  margin-bottom: 12px;
  padding: 10px 12px;
  background: #f0f9ff;
  border-radius: var(--radius-md);
}
html[data-design="classic"] .time-tracker-timer {
  margin-bottom: 14px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--border);
}
html[data-design="classic"] .time-tracker-elapsed {
  font-size: 20px;
  font-weight: 800;
  color: var(--success);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.5px;
}
html[data-design="classic"] .time-tracker-manual {
  margin-bottom: 14px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--border);
}
html[data-design="classic"] .time-tracker-logs {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 150px;
  overflow-y: auto;
}
html[data-design="classic"] .time-log-item {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  background: var(--gray-50);
  border-radius: var(--radius-sm);
  padding: 7px 10px;
}

html[data-design="classic"] .attachments-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 12px;
  max-height: 220px;
  overflow-y: auto;
}
html[data-design="classic"] .attachment-item {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--gray-50);
  border-radius: var(--radius-md);
  padding: 9px 12px;
}
html[data-design="classic"] .attachment-icon {
  font-size: 22px;
  flex-shrink: 0;
}
html[data-design="classic"] .attachment-info {
  flex: 1;
  min-width: 0;
}
html[data-design="classic"] .attachment-name {
  font-size: 12px;
  font-weight: 600;
  color: var(--brand-500);
  text-decoration: none;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
