}
html[data-design="classic"] .attachment-meta {
  font-size: 10px;
  color: var(--gray-400);
  margin-top: 1px;
}
html[data-design="classic"] .attachment-upload {
  border-top: 1px solid var(--border);
  padding-top: 12px;
}

html[data-design="classic"] .deps-blocked-warning {
  background: #fef2f2;
