html[data-design="classic"] .deps-section {
  margin-bottom: 12px;
}
html[data-design="classic"] .deps-section-title {
  font-size: 11px;
  font-weight: 700;
  color: var(--gray-400);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 6px;
}
html[data-design="classic"] .deps-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
html[data-design="classic"] .deps-item {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--gray-50);
  border-radius: var(--radius-sm);
  padding: 7px 10px;
}
html[data-design="classic"] .deps-item-title {
  flex: 1;
  font-size: 12px;
  font-weight: 500;
}
html[data-design="classic"] .deps-done {
