html[data-design="classic"] .deps-add-section {
  border-top: 1px solid var(--border);
  padding-top: 12px;
}
html[data-design="classic"] .deps-search-results {
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
}
html[data-design="classic"] .deps-search-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 12px;
  cursor: pointer;
  transition: background 0.15s;
}
html[data-design="classic"] .deps-search-item:hover {
  background: var(--brand-50);
}

/* ========================================
   STATUS DROPDOWN
   /* = */

html[data-design="classic"] .status-quick-btn {
