/* al-filter-bar styles merged into .al-sidebar above */


/* Activity toggle button on task row */
html[data-design="classic"] .task-activity-btn {
  opacity: 0.5;
  transition: opacity 0.15s;
  flex-shrink: 0;
}
html[data-design="classic"] .task-activity-btn:hover,
html[data-design="classic"] .task-activity-btn.active {
  opacity: 1;
}
html[data-design="classic"] .task-activity-btn.active {
  background: var(--brand-50);
  border-radius: var(--radius-sm);
}

/* Activity panel  spans full width as second row when toggled */
html[data-design="classic"] .task-activity-inline {
  flex: 0 0 100%;
  width: 100%;
  padding-top: 8px;
  border-top: 1px solid var(--border);
  margin-top: -4px;
}

/*  Bulk actions toolbar  */
html[data-design="classic"] .bulk-toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  margin-bottom: 8px;
  flex-wrap: wrap;
  min-height: 40px;
}
html[data-design="classic"] .bulk-select-all {
  display: flex; align-items: center; gap: 6px;
