}
html[data-design="classic"] .bulk-actions {
  display: flex; align-items: center; gap: 5px; flex-wrap: wrap;
}

/* Checkbox on task row */
html[data-design="classic"] .task-row-checkbox {
  width: 15px; height: 15px;
  flex-shrink: 0;
  cursor: pointer;
  accent-color: var(--brand-500);
}
html[data-design="classic"] .task-row-selected {
  background: var(--brand-50) !important;
  border-color: var(--brand-200) !important;
}
html[data-design="classic"][data-theme="dark"] .task-row-selected { background: #1e1f35 !important; }

/* ========================================
   TASKS  DARK MODE (comprehensive)
   /* = */

html[data-design="classic"][data-theme="dark"] .task-row                { background: var(--bg-card); border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .task-row:hover          { background: #081628; border-color: #163355; }
html[data-design="classic"][data-theme="dark"] .task-row-selected       { background: #1e1f35 !important; border-color: #2a3a6a !important; }
html[data-design="classic"][data-theme="dark"] .task-title              { color: var(--gray-800); }
html[data-design="classic"][data-theme="dark"] .task-meta              { color: var(--gray-500); }
