html[data-design="classic"][data-theme="dark"] .status-dropdown-panel  { background: #071525; border-color: #1e3a5a; }
html[data-design="classic"][data-theme="dark"] .status-option:hover    { background: #0a1e35; }
html[data-design="classic"][data-theme="dark"] .task-comments-panel    { background: #081628; border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .comment-item           { background: var(--bg-card); border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .time-tracker-panel     { background: #081628; border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .time-log-item          { background: var(--bg-card); border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .files-panel            { background: #081628; border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .file-item              { background: var(--bg-card); border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .deps-panel             { background: #081628; border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .project-task-group-header { background: #081628; border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .project-task-group .task-list { border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .tag-group-header       { border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .bulk-toolbar           { background: var(--bg-card); border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .task-activity-inline   { border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .task-filter-active     { background: #1a3550; color: var(--gray-600); }

/*  Linked docs panel in task row  */
html[data-design="classic"] .task-linked-docs {
  display: flex; align-items: center; gap: 6px;
  flex-wrap: wrap; margin-top: 4px; width: 100%;
}
html[data-design="classic"] .task-linked-docs-label {
  font-size: 11px; color: var(--gray-400); font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.06em;
  flex-shrink: 0;
}
html[data-design="classic"] .task-linked-doc-chip {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 2px 8px; background: var(--brand-50);
  border: 1px solid var(--brand-200); border-radius: 20px;
  font-size: 12px; color: var(--brand-700); text-decoration: none;
  transition: background 0.15s, border-color 0.15s;
}
html[data-design="classic"] .task-linked-doc-chip:hover { background: var(--brand-100); border-color: var(--brand-400); }

html[data-design="classic"][data-theme="dark"] .task-linked-doc-chip {
  background: rgba(56,189,248,.1); border-color: rgba(56,189,248,.25); color: #38bdf8;
}
html[data-design="classic"][data-theme="dark"] .task-linked-doc-chip:hover {
  background: rgba(56,189,248,.2);
}


/* ── src/styles/goals.css ── */
/* ========================================
   GOAL CARDS
   /* = */

html[data-design="classic"] .goal-card {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  box-shadow: var(--shadow-sm);
  transition:
    box-shadow 0.2s,
    transform 0.2s;
}
html[data-design="classic"] .goal-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}
html[data-design="classic"] .goal-card-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 10px;
}
html[data-design="classic"] .goal-card-header h3 {
  font-size: 15px;
  font-weight: 700;
  color: var(--gray-800);
}
html[data-design="classic"] .goal-date {
  font-size: 12px;
  color: var(--gray-500);
  display: flex;
  align-items: center;
  gap: 4px;
}
html[data-design="classic"] .goal-progress-label {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: var(--gray-500);
  margin-bottom: 4px;
  font-weight: 500;
}
html[data-design="classic"] .goal-stats-row {
  display: flex;
  gap: 16px;
  font-size: 12px;
  color: var(--gray-500);
}
html[data-design="classic"] .goal-card-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: auto;
}

/* ========================================
   SUB-GOALS & STEPS
   /* = */

html[data-design="classic"] .subgoals-container {
  margin-top: 14px;
  border-top: 1px dashed var(--border);
  padding-top: 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
html[data-design="classic"] .subgoals-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}
html[data-design="classic"] .subgoals-label {
  font-size: 11px;
  font-weight: 700;
  color: var(--gray-400);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
html[data-design="classic"] .subgoal-card {
  background: var(--gray-50);
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
  padding: 12px;
}
html[data-design="classic"] .subgoal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  margin-bottom: 4px;
}
html[data-design="classic"] .subgoal-title-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
}
html[data-design="classic"] .subgoal-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--gray-700);
}
html[data-design="classic"] .subgoal-status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
html[data-design="classic"] .subgoal-status-dot.achieved {
  background: var(--success);
}
html[data-design="classic"] .subgoal-status-dot.active {
  background: var(--brand-500);
}
html[data-design="classic"] .steps-container {
  margin-top: 10px;
  border-top: 1px dashed var(--border);
  padding-top: 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
html[data-design="classic"] .steps-label {
  font-size: 10px;
  font-weight: 700;
  color: var(--gray-400);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 6px;
}
html[data-design="classic"] .step-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 10px;
  border-radius: var(--radius-md);
  background: var(--bg-card);
  border: 1px solid var(--border);
}
html[data-design="classic"] .step-checkbox-area {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
  cursor: pointer;
}
html[data-design="classic"] .step-checkbox {
  width: 18px;
  height: 18px;
  border-radius: var(--radius-sm);
  border: 2px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  flex-shrink: 0;
  transition: all 0.2s;
}
html[data-design="classic"] .step-checkbox.checked {
  background: var(--success);
  border-color: var(--success);
  color: #fff;
}
html[data-design="classic"] .step-title {
  font-size: 12px;
  color: var(--gray-700);
}
html[data-design="classic"] .step-done {
  text-decoration: line-through;
  color: var(--gray-400);
}
html[data-design="classic"] .step-add-row {
  display: flex;
  gap: 8px;
  margin-top: 8px;
}


/*  Step inline tools  */
html[data-design="classic"] .step-item-wrap { display: flex; flex-direction: column; }
html[data-design="classic"] .step-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 8px;
  border-radius: var(--radius-sm);
  transition: background 0.1s;
}
html[data-design="classic"] .step-item:hover { background: var(--gray-50); }
html[data-design="classic"] .step-tools {
  display: flex;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
}
html[data-design="classic"] .step-tool-btn {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 13px;
  padding: 3px 7px;
  border-radius: var(--radius-sm);
  background: transparent;
  border: none;
  cursor: pointer;
  color: var(--gray-500);
  transition: background 0.1s, color 0.1s;
}
html[data-design="classic"] .step-tool-btn:hover, html[data-design="classic"] .step-tool-btn.active {
  background: var(--gray-100);
  color: var(--gray-800);
}
html[data-design="classic"] .step-tool-count {
  font-size: 10px;
  font-weight: 700;
  background: var(--brand-100);
  color: var(--brand-700);
  border-radius: 8px;
  padding: 0 4px;
  line-height: 1.4;
}

/* Step panels */
html[data-design="classic"] .step-panel {
  margin: 4px 0 8px 28px;
  padding: 10px 12px;
  background: var(--gray-50);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  display: flex;
  flex-direction: column;
  gap: 8px;
}
html[data-design="classic"] .step-panel-empty { font-size: 12px; color: var(--gray-400); margin: 0; }
html[data-design="classic"] .step-panel-label { font-size: 10px; font-weight: 700; color: var(--gray-400); text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 4px; }

/* Comment rows */
html[data-design="classic"] .step-comment {
  display: flex; align-items: flex-start; gap: 6px;
  font-size: 12px; background: var(--bg-card);
  padding: 6px 8px; border-radius: var(--radius-sm);
  border: 1px solid var(--border);
}
html[data-design="classic"] .step-comment-author { font-weight: 700; color: var(--brand-600); flex-shrink: 0; }
html[data-design="classic"] .step-comment-text   { flex: 1; color: var(--gray-700); }
html[data-design="classic"] .step-comment-input  { display: flex; gap: 6px; }
html[data-design="classic"] .step-comment-input input { flex: 1; font-size: 12px; padding: 5px 8px; }

/* File rows */
html[data-design="classic"] .step-file-row {
  display: flex; align-items: center; gap: 6px;
  font-size: 12px; padding: 4px 6px;
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-sm);
}
html[data-design="classic"] .step-file-name { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--gray-700); }
html[data-design="classic"] .step-file-size { font-size: 10px; color: var(--gray-400); flex-shrink: 0; }

/* Dependency rows */
html[data-design="classic"] .step-dep-row {
  display: flex; align-items: center; gap: 6px;
  font-size: 12px; padding: 4px 6px;
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-sm); margin-bottom: 4px;
}
html[data-design="classic"] .step-dep-title { flex: 1; color: var(--gray-700); }
html[data-design="classic"] .step-dep-dot {
  width: 8px; height: 8px;
  border-radius: 50%; background: var(--gray-300); flex-shrink: 0;
}
html[data-design="classic"] .step-dep-dot.done { background: var(--success); }
html[data-design="classic"] .step-dep-add-list { display: flex; flex-wrap: wrap; gap: 5px; }

/* ========================================
   GOALS  DARK MODE
   /* = */

html[data-design="classic"][data-theme="dark"] .goal-card                { background: var(--bg-card); border-color: var(--border); }
