html[data-design="classic"][data-theme="dark"] .step-panel               { background: #081628; border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .step-comment            { background: var(--bg-card); border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .step-file-row           { background: var(--bg-card); border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .step-dep-row            { background: var(--bg-card); border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .goal-form               { background: var(--bg-card); border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .category-card           { background: var(--bg-card); border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .category-card:hover     { background: #081628; }

/* ========================================
   B-1: CASCADING GOALS  Level badges, filter bar, children
   /* = */

