html[data-design="classic"] .goal-child-level-icon { font-size: 14px; width: 20px; flex-shrink: 0; }
html[data-design="classic"] .goal-child-title { flex: 1; font-size: 13px; font-weight: 600; color: var(--gray-700); }
html[data-design="classic"] .goal-child-progress-bar {
