}
html[data-design="classic"] .goal-child-progress-fill {
  height: 100%; background: var(--brand-500); border-radius: var(--radius-full); transition: width .3s;
}
html[data-design="classic"] .goal-child-pct { font-size: 11px; font-weight: 700; color: var(--gray-500); min-width: 30px; text-align: right; }
html[data-design="classic"] .goal-child-status { font-size: 10px; color: var(--gray-400); min-width: 60px; text-align: right; }

/* ========================================
   B-2: CONFIDENCE METER + SPARKLINE
   /* = */

html[data-design="classic"] .goal-confidence {
  margin: 10px 0 0; padding: 10px 12px;
  background: var(--gray-50); border: 1px solid var(--border);
  border-radius: var(--radius-md);
}
html[data-design="classic"] .goal-confidence-header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 6px;
}
html[data-design="classic"] .goal-confidence-label {
  font-size: 11px; font-weight: 700; text-transform: uppercase;
  letter-spacing: .07em; color: var(--gray-400);
}
html[data-design="classic"] .goal-confidence-right {
  display: flex; align-items: center; gap: 8px;
}
html[data-design="classic"] .goal-confidence-spark { display: block; }
html[data-design="classic"] .goal-confidence-value {
  font-size: 14px; font-weight: 800; min-width: 36px; text-align: right;
}
html[data-design="classic"] .goal-confidence-edit-btn {
  background: none; border: none; color: var(--gray-400);
  cursor: pointer; font-size: 12px; padding: 1px 5px;
  border-radius: 4px; transition: background .15s;
}
html[data-design="classic"] .goal-confidence-edit-btn:hover { background: var(--gray-100); }
html[data-design="classic"] .goal-confidence-bar {
  height: 6px; background: var(--gray-200); border-radius: var(--radius-full); overflow: hidden;
}
html[data-design="classic"] .goal-confidence-fill {
  height: 100%; border-radius: var(--radius-full); transition: width .4s;
}
html[data-design="classic"] .goal-confidence-form {
  margin-top: 10px; display: flex; flex-direction: column; gap: 8px;
}
html[data-design="classic"] .goal-ci-input {
  width: 100%; padding: 6px 10px; border: 1px solid var(--border);
  border-radius: var(--radius-sm); font-size: 12px;
  background: var(--bg-card); color: var(--gray-700); outline: none;
  box-sizing: border-box;
}
html[data-design="classic"] .goal-ci-input:focus { border-color: var(--brand-400); }

/* ========================================
   B-3: WEEKLY CHECK-INS
   /* = */

html[data-design="classic"] .goal-checkin-panel {
  margin-top: 14px; padding-top: 14px; border-top: 1px solid var(--border);
}
html[data-design="classic"] .goal-section-label {
  display: flex; align-items: center; gap: 6px;
  font-size: 12px; font-weight: 700; color: var(--gray-600);
  margin-bottom: 10px;
}
html[data-design="classic"] .goal-checkin-header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 10px;
}
html[data-design="classic"] .goal-checkin-form {
  background: var(--gray-50); border: 1px solid var(--border);
  border-radius: var(--radius-md); padding: 12px; margin-bottom: 10px;
  display: flex; flex-direction: column; gap: 8px;
}
html[data-design="classic"] .goal-checkin-item {
  padding: 8px 10px; border: 1px solid var(--border);
  border-left: 3px solid var(--brand-500); border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  background: var(--bg-card); margin-bottom: 6px;
}
html[data-design="classic"] .goal-checkin-meta {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-bottom: 4px;
}
html[data-design="classic"] .goal-checkin-author { font-size: 11px; font-weight: 700; color: var(--gray-600); }
html[data-design="classic"] .goal-checkin-date   { font-size: 11px; color: var(--gray-400); }
html[data-design="classic"] .goal-checkin-snap   { font-size: 11px; color: var(--gray-400); margin-left: auto; }
html[data-design="classic"] .goal-ci-delete-btn  {
  background: none; border: none; color: var(--gray-400);
  cursor: pointer; font-size: 12px; padding: 1px 4px; border-radius: 4px;
  transition: color .15s;
}
html[data-design="classic"] .goal-ci-delete-btn:hover { color: var(--danger); }
html[data-design="classic"] .goal-checkin-update   { font-size: 13px; color: var(--gray-700); line-height: 1.5; }
html[data-design="classic"] .goal-checkin-blockers { font-size: 12px; color: var(--warning); margin-top: 4px; }
html[data-design="classic"] .goal-checkin-more {
  font-size: 11px; color: var(--gray-400); text-align: center; padding: 4px;
}

/* ========================================
   B-4: KEY RESULTS
   /* = */

html[data-design="classic"] .goal-kr-panel {
  margin-top: 14px; padding-top: 14px; border-top: 1px solid var(--border);
}
html[data-design="classic"] .goal-kr-header {
  display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px;
}
html[data-design="classic"] .goal-kr-form {
  background: var(--gray-50); border: 1px solid var(--border);
  border-radius: var(--radius-md); padding: 12px;
  display: flex; flex-direction: column; gap: 8px; margin-bottom: 10px;
}
html[data-design="classic"] .goal-kr-item {
  padding: 10px 12px; border: 1px solid var(--border);
  border-radius: var(--radius-md); background: var(--bg-card); margin-bottom: 6px;
  display: flex; flex-direction: column; gap: 6px;
}
html[data-design="classic"] .goal-kr-top {
  display: flex; align-items: flex-start; justify-content: space-between; gap: 8px;
}
html[data-design="classic"] .goal-kr-title { font-size: 13px; font-weight: 700; color: var(--gray-700); flex: 1; }
html[data-design="classic"] .goal-kr-actions { display: flex; align-items: center; gap: 6px; flex-shrink: 0; }
html[data-design="classic"] .goal-kr-status-badge {
  font-size: 10px; font-weight: 700; padding: 2px 7px; border-radius: var(--radius-full);
}
html[data-design="classic"] .goal-kr-status-select {
  font-size: 11px; padding: 2px 6px; border: 1px solid var(--border);
  border-radius: 5px; background: var(--bg-card); color: var(--gray-600);
  cursor: pointer; outline: none;
}
html[data-design="classic"] .goal-kr-progress-row {
  display: flex; align-items: center; gap: 8px;
}
html[data-design="classic"] .goal-kr-progress-bar {
  flex: 1; height: 6px; background: var(--gray-200);
  border-radius: var(--radius-full); overflow: hidden;
}
html[data-design="classic"] .goal-kr-progress-fill {
  height: 100%; border-radius: var(--radius-full); transition: width .4s;
}
html[data-design="classic"] .goal-kr-pct { font-size: 12px; font-weight: 700; color: var(--gray-600); min-width: 36px; text-align: right; }
html[data-design="classic"] .goal-kr-values {
  display: flex; align-items: center; gap: 6px; flex-wrap: wrap;
  font-size: 12px; color: var(--gray-600);
}
html[data-design="classic"] .goal-kr-current {
  font-weight: 700; color: var(--brand-500); cursor: pointer;
  display: flex; align-items: center; gap: 3px;
}
html[data-design="classic"] .goal-kr-edit-hint { font-size: 10px; opacity: 0.6; }
html[data-design="classic"] .goal-kr-current:hover .goal-kr-edit-hint { opacity: 1; }
html[data-design="classic"] .goal-kr-metric { font-size: 11px; color: var(--gray-400); }
html[data-design="classic"] .goal-kr-value-input {
  width: 80px; padding: 3px 7px; border: 1px solid var(--brand-400);
  border-radius: 5px; font-size: 12px; font-weight: 700;
  background: var(--bg-card); color: var(--gray-800); outline: none;
}
html[data-design="classic"] .goal-kr-empty {
  font-size: 12px; color: var(--gray-400); padding: 10px 0; text-align: center;
}


/* ========================================
   B-5: GOAL SCORECARD
   /* = */

html[data-design="classic"] .scorecard-wrap { display:flex; flex-direction:column; gap:16px; }

html[data-design="classic"] .scorecard-summary {
  display:flex; gap:0; border:1px solid var(--border);
  border-radius:var(--radius-md); overflow:hidden; background:var(--bg-card);
}
html[data-design="classic"] .scorecard-kpi {
  flex:1; padding:14px 12px; text-align:center;
  border-right:1px solid var(--border);
}
html[data-design="classic"] .scorecard-kpi:last-child { border-right:none; }
html[data-design="classic"] .scorecard-kpi-num   { font-size:24px; font-weight:800; line-height:1; margin-bottom:4px; }
html[data-design="classic"] .scorecard-kpi-label { font-size:11px; color:var(--gray-400); font-weight:500; }

html[data-design="classic"] .scorecard-table-wrap { overflow-x:auto; border:1px solid var(--border); border-radius:var(--radius-md); }
html[data-design="classic"] .scorecard-table { width:100%; border-collapse:collapse; font-size:12px; }
html[data-design="classic"] .scorecard-table thead th {
  padding:10px 12px; text-align:left; font-size:10px; font-weight:700;
  text-transform:uppercase; letter-spacing:.07em; color:var(--gray-400);
  background:var(--gray-50); border-bottom:1px solid var(--border);
  white-space:nowrap;
}
html[data-design="classic"] .scorecard-row { border-bottom:1px solid var(--border); transition:background .15s; }
html[data-design="classic"] .scorecard-row:last-child { border-bottom:none; }
html[data-design="classic"] .scorecard-row:hover { background:var(--gray-50); }
html[data-design="classic"] .scorecard-row td { padding:10px 12px; vertical-align:middle; }
html[data-design="classic"] .scorecard-title-cell { max-width:200px; }
html[data-design="classic"] .scorecard-goal-title { font-weight:600; color:var(--gray-700); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:190px; }
html[data-design="classic"] .scorecard-child-tag { font-size:10px; color:var(--gray-400); }
html[data-design="classic"] .scorecard-meta { color:var(--gray-500); font-size:11px; white-space:nowrap; }
html[data-design="classic"] .scorecard-level-chip { font-size:11px; font-weight:600; padding:2px 8px; border-radius: var(--radius-full); white-space:nowrap; }
html[data-design="classic"] .scorecard-progress-wrap { display:flex; align-items:center; gap:8px; min-width:120px; }
html[data-design="classic"] .scorecard-progress-bar { flex:1; height:6px; background:var(--gray-200); border-radius: var(--radius-full); overflow:hidden; }
html[data-design="classic"] .scorecard-progress-fill { height:100%; border-radius: var(--radius-full); transition:width .3s; }
html[data-design="classic"] .scorecard-progress-pct { font-size:11px; font-weight:700; color:var(--gray-500); min-width:30px; }
html[data-design="classic"] .scorecard-conf-bar { width:60px; height:6px; background:var(--gray-200); border-radius: var(--radius-full); overflow:hidden; }
html[data-design="classic"] .scorecard-status-badge { font-size:11px; font-weight:600; padding:2px 8px; border-radius: var(--radius-full); }
html[data-design="classic"] .scorecard-status-active    { background:rgba(99,102,241,0.12);  color:var(--brand-400); }
html[data-design="classic"] .scorecard-status-achieved  { background:rgba(5,150,105,0.12);   color:var(--success); }
html[data-design="classic"] .scorecard-status-paused    { background:rgba(245,158,11,0.12);  color:var(--warning); }
html[data-design="classic"] .scorecard-empty { padding:24px; text-align:center; color:var(--gray-400); }

/* ========================================
   B-6: QUARTERLY PLANNING
   /* = */

html[data-design="classic"] .quarterly-wrap { display:flex; flex-direction:column; gap:20px; }

html[data-design="classic"] .quarterly-group {
  border:1px solid var(--border); border-radius:var(--radius-lg);
  background:var(--bg-card); overflow:hidden;
}
html[data-design="classic"] .quarterly-header {
  padding:16px 20px; border-bottom:1px solid var(--border);
  background:var(--gray-50);
}
html[data-design="classic"] .quarterly-title {
  display:flex; align-items:center; gap:10px;
  font-size:16px; font-weight:800; color:var(--gray-800); margin-bottom:8px;
}
html[data-design="classic"] .quarterly-icon { font-size:18px; }
html[data-design="classic"] .quarterly-count {
  font-size:12px; font-weight:500; color:var(--gray-400);
  padding:2px 8px; background:var(--gray-200); border-radius: var(--radius-full);
}
html[data-design="classic"] .quarterly-meta-row { display:flex; gap:16px; margin-bottom:8px; }
html[data-design="classic"] .quarterly-stat { font-size:12px; color:var(--gray-500); }
html[data-design="classic"] .quarterly-progress-bar {
  height:6px; background:var(--gray-200); border-radius: var(--radius-full); overflow:hidden;
}
html[data-design="classic"] .quarterly-progress-fill {
  height:100%; background:linear-gradient(90deg,var(--brand-500),var(--purple));
  border-radius: var(--radius-full); transition:width .5s;
}

html[data-design="classic"] .quarterly-goals-grid {
  display:grid; grid-template-columns:repeat(auto-fill,minmax(240px,1fr));
  gap:12px; padding:16px 20px;
}
html[data-design="classic"] .quarterly-goal-card {
  border:1px solid var(--border); border-radius:var(--radius-md);
  padding:12px 14px; background:var(--bg-card);
  display:flex; flex-direction:column; gap:6px;
  transition:box-shadow .15s;
}
html[data-design="classic"] .quarterly-goal-card:hover { box-shadow:var(--shadow-sm); }
html[data-design="classic"] .quarterly-goal-top { display:flex; align-items:flex-start; gap:8px; }
html[data-design="classic"] .quarterly-level-chip { font-size:14px; flex-shrink:0; }
html[data-design="classic"] .quarterly-goal-title { flex:1; font-size:13px; font-weight:700; color:var(--gray-700); line-height:1.35; }
html[data-design="classic"] .quarterly-status { font-size:10px; font-weight:600; padding:2px 6px; border-radius: var(--radius-full); flex-shrink:0; }
html[data-design="classic"] .quarterly-owner { font-size:11px; color:var(--gray-400); }
html[data-design="classic"] .quarterly-goal-progress-row { display:flex; align-items:center; gap:8px; }
html[data-design="classic"] .quarterly-goal-progress-bar { flex:1; height:5px; background:var(--gray-200); border-radius: var(--radius-full); overflow:hidden; }
html[data-design="classic"] .quarterly-pct { font-size:11px; font-weight:700; color:var(--gray-500); min-width:28px; text-align:right; }
html[data-design="classic"] .quarterly-goal-footer { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
html[data-design="classic"] .quarterly-kr-count {
  font-size:10px; color:var(--gray-400); padding:1px 6px;
  background:var(--gray-100); border-radius: var(--radius-full);
}

/* View switcher */
html[data-design="classic"] .goal-view-switcher {
  display:flex; gap:4px; background:var(--gray-100);
  border-radius:var(--radius-sm); padding:3px;
}
html[data-design="classic"] .goal-view-btn {
  padding:5px 12px; border:none; border-radius:5px; font-size:12px;
  font-weight:600; background:transparent; color:var(--gray-500);
  cursor:pointer; transition:all .15s; white-space:nowrap;
}
html[data-design="classic"] .goal-view-btn.active { background:var(--bg-card); color:var(--brand-600); box-shadow:var(--shadow-xs); }


/* ── src/styles/sprints.css ── */
/* ========================================
   SPRINTS PAGE  C-1 through C-3
   /* = */


html[data-design="classic"] .sprint-summary-bar {
  display:flex; gap:0; margin-bottom:20px;
  border:1px solid var(--border); border-radius:var(--radius-md);
  background:var(--bg-card); overflow:hidden;
}
html[data-design="classic"] .sprint-summary-stat {
  flex:1; padding:14px 16px; text-align:center;
  border-right:1px solid var(--border);
}
html[data-design="classic"] .sprint-summary-stat:last-child { border-right:none; }
html[data-design="classic"] .sprint-summary-num   { font-size:24px; font-weight:800; line-height:1; margin-bottom:4px; color:var(--gray-800); }
html[data-design="classic"] .sprint-summary-label { font-size:11px; color:var(--gray-400); font-weight:500; }

html[data-design="classic"] .sprint-filter-bar {
  display:flex; gap:6px; flex-wrap:wrap; margin-bottom:20px;
}
html[data-design="classic"] .sprint-filter-btn {
  padding:5px 14px; border:1px solid var(--border); border-radius: var(--radius-full);
  font-size:12px; font-weight:600; background:var(--bg-card);
  color:var(--gray-500); cursor:pointer; transition:all .15s;
}
html[data-design="classic"] .sprint-filter-btn:hover  { border-color:var(--brand-400); color:var(--brand-600); }
html[data-design="classic"] .sprint-filter-btn.active { background:var(--brand-500); color:#fff; border-color:var(--brand-500); }

html[data-design="classic"] .sprint-cards-grid {
  display:grid; grid-template-columns:repeat(auto-fill,minmax(540px,1fr));
  gap:20px;
}

/* Sprint Card */
html[data-design="classic"] .sprint-card {
  background:var(--bg-card); border:1px solid var(--border);
  border-radius:var(--radius-lg); padding:20px;
  box-shadow:var(--shadow-xs); display:flex; flex-direction:column; gap:14px;
}
html[data-design="classic"] .sprint-card-header { display:flex; flex-direction:column; gap:6px; }
html[data-design="classic"] .sprint-card-top    { display:flex; align-items:center; justify-content:space-between; gap:10px; }
html[data-design="classic"] .sprint-card-title  { font-size:17px; font-weight:800; color:var(--gray-800); }
html[data-design="classic"] .sprint-status-chip { font-size:11px; font-weight:700; padding:3px 10px; border-radius: var(--radius-full); flex-shrink:0; }
html[data-design="classic"] .sprint-goal-text   { font-size:13px; color:var(--gray-500); line-height:1.5; }
html[data-design="classic"] .sprint-dates       { display:flex; align-items:center; gap:10px; font-size:12px; color:var(--gray-400); }
html[data-design="classic"] .sprint-days-left   { font-size:11px; font-weight:700; padding:2px 8px; border-radius: var(--radius-full);
  background:rgba(5,150,105,0.12); color:var(--success); }
html[data-design="classic"] .sprint-days-left.urgent { background:rgba(239,68,68,0.12); color:var(--danger); }

html[data-design="classic"] .sprint-progress-section { display:flex; flex-direction:column; gap:5px; }
html[data-design="classic"] .sprint-progress-label   { display:flex; justify-content:space-between; font-size:12px; color:var(--gray-500); }
html[data-design="classic"] .sprint-progress-bar     { height:7px; background:var(--gray-200); border-radius: var(--radius-full); overflow:hidden; }
html[data-design="classic"] .sprint-progress-fill    { height:100%; border-radius: var(--radius-full); transition:width .4s; }

html[data-design="classic"] .sprint-card-actions {
  display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px;
  padding-top:10px; border-top:1px solid var(--border);
}

/* Backlog */
html[data-design="classic"] .sprint-backlog { border-top:1px solid var(--border); padding-top:14px; display:flex; flex-direction:column; gap:10px; }
html[data-design="classic"] .sprint-backlog-header { display:flex; align-items:center; justify-content:space-between; }
html[data-design="classic"] .sprint-section-label  { font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.08em; color:var(--gray-400); }
html[data-design="classic"] .sprint-points-badge   { font-size:12px; font-weight:700; color:var(--brand-500); padding:2px 8px;
  background:rgba(99,102,241,0.1); border-radius: var(--radius-full); }
html[data-design="classic"] .sprint-task-list      { display:flex; flex-direction:column; gap:4px; }
html[data-design="classic"] .sprint-task-row {
  display:flex; align-items:center; gap:8px; padding:7px 10px;
  background:var(--gray-50); border:1px solid var(--border);
  border-radius:var(--radius-sm); font-size:12px;
}
html[data-design="classic"] .sprint-task-status {
  width:8px; height:8px; border-radius:50%; flex-shrink:0;
  background:var(--gray-300);
}
html[data-design="classic"] .sprint-status-done        { background:var(--success); }
html[data-design="classic"] .sprint-status-in_progress { background:var(--warning); }
html[data-design="classic"] .sprint-status-todo        { background:var(--brand-500); }
html[data-design="classic"] .sprint-task-title  { flex:1; color:var(--gray-700); font-weight:500; }
html[data-design="classic"] .sprint-task-points { font-size:11px; font-weight:700; color:var(--gray-400); min-width:30px; text-align:right; }
html[data-design="classic"] .sprint-task-remove-btn {
  background:none; border:none; color:var(--gray-400); cursor:pointer;
  font-size:12px; padding:0 4px; border-radius:4px; transition:color .15s;
}
html[data-design="classic"] .sprint-task-remove-btn:hover { color:var(--danger); }
html[data-design="classic"] .sprint-backlog-empty { font-size:12px; color:var(--gray-400); padding:8px 0; text-align:center; }
html[data-design="classic"] .sprint-backlog-list  { max-height:200px; overflow-y:auto; }
html[data-design="classic"] .sprint-backlog-row   { background:var(--bg-card); }
html[data-design="classic"] .sprint-search {
  width:100%; padding:7px 12px; border:1px solid var(--border);
  border-radius:var(--radius-sm); font-size:12px;
  background:var(--bg-card); color:var(--gray-700); outline:none;
  box-sizing:border-box;
}
html[data-design="classic"] .sprint-search:focus { border-color:var(--brand-400); }

/* Burndown */
html[data-design="classic"] .sprint-burndown { border-top:1px solid var(--border); padding-top:14px; }
html[data-design="classic"] .sprint-loading, html[data-design="classic"] .sprint-empty { font-size:12px; color:var(--gray-400); padding:20px; text-align:center; }

/* Retrospective */
html[data-design="classic"] .sprint-retro { border-top:1px solid var(--border); padding-top:14px; display:flex; flex-direction:column; gap:10px; }
html[data-design="classic"] .sprint-retro-header { display:flex; align-items:center; justify-content:space-between; }
