  background: var(--gray-100);
  opacity: 1;
}
html[data-design="classic"] .sub-projects-container {
  padding: 8px 0 4px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
html[data-design="classic"] .sub-projects-label {
  font-size: 10px;
  font-weight: 700;
  color: var(--gray-400);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 4px;
  padding-left: 4px;
}

/* ── Project cards (Projects page) ─────────────────────────────── */
html[data-design="classic"] .cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 18px;
  align-items: start;
}
html[data-design="classic"] .project-card {
  background: var(--card-bg, var(--bg-card));
  border-radius: var(--radius-lg, 14px);
  border: 1px solid var(--border);
  overflow: visible;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.2s, transform 0.2s;
  min-width: 0;
}
html[data-design="classic"] .project-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
html[data-design="classic"] .project-color-bar  { width: 5px; flex-shrink: 0; border-radius: 14px 0 0 14px; }
html[data-design="classic"] .project-card-top   { display: flex; border-radius: 14px; overflow: visible; }
html[data-design="classic"] .project-card-body  { padding: 18px; flex: 1; min-width: 0; overflow: visible; }
html[data-design="classic"] .project-card-header {
  display: flex; justify-content: space-between;
  align-items: flex-start; margin-bottom: 6px; gap: 8px;
}
html[data-design="classic"] .project-card-header h3 {
  font-size: 15px; font-weight: 700; color: var(--gray-800);
  flex: 1; min-width: 0; overflow: hidden;
  text-overflow: ellipsis; white-space: nowrap;
}
html[data-design="classic"] .project-desc {
  color: var(--gray-500); font-size: 13px;
  margin-bottom: 14px; min-height: 20px; line-height: 1.5;
}
html[data-design="classic"] .project-card-footer  { display: flex; flex-direction: column; gap: 8px; margin-top: 10px; font-size: 12px; color: var(--gray-500); }
html[data-design="classic"] .project-footer-row1  { display: flex; justify-content: space-between; align-items: center; }
html[data-design="classic"] .project-progress-text { font-size: 12px; color: var(--gray-500); }
html[data-design="classic"] .project-footer-actions { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
html[data-design="classic"] .project-footer-actions .btn-icon {
  width: 28px; height: 28px; border: none; background: var(--gray-100);
  border-radius: 6px; cursor: pointer; font-size: 14px;
  display: flex; align-items: center; justify-content: center;
  transition: background 0.12s;
}
html[data-design="classic"] .project-footer-actions .btn-icon:hover { background: var(--gray-200); }
html[data-design="classic"] .project-sub-actions  { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 6px; }
html[data-design="classic"] .progress-bar  { height: 6px; background: var(--gray-100); border-radius: var(--radius-full); overflow: hidden; }
html[data-design="classic"] .progress-fill { height: 100%; border-radius: var(--radius-full); transition: width 0.4s; }

/* ── Badges (from components.css — loaded here since components.css may be missing) */
html[data-design="classic"] .badge {
  font-size: 11px; padding: 3px 9px;
  border-radius: var(--radius-full); font-weight: 600;
  letter-spacing: 0.02em; display: inline-flex;
  align-items: center; gap: 4px; white-space: nowrap; flex-shrink: 0;
}
html[data-design="classic"] .badge-active    { background: #e0f2fe; color: #0369a1; }
html[data-design="classic"] .badge-done      { background: #d1fae5; color: #065f46; }
html[data-design="classic"] .badge-achieved  { background: #d1fae5; color: #065f46; }
html[data-design="classic"] .badge-inactive  { background: var(--gray-100); color: var(--gray-600); }
html[data-design="classic"] .badge-todo      { background: #ede9fe; color: #5b21b6; }
html[data-design="classic"] .badge-in_progress { background: #fef3c7; color: #92400e; }
html[data-design="classic"] .badge-paused    { background: var(--gray-100); color: var(--gray-600); }

/* ── Card actions (shared) */
html[data-design="classic"] .card-actions {
  display: flex; align-items: center; gap: 4px; flex-shrink: 0;
}
html[data-design="classic"] .btn-icon {
  width: 28px; height: 28px; border: none;
  background: transparent; border-radius: 6px;
  cursor: pointer; font-size: 14px;
  display: flex; align-items: center; justify-content: center;
  opacity: 0.6; transition: all 0.12s; flex-shrink: 0;
}
html[data-design="classic"] .btn-icon:hover { background: var(--gray-100); opacity: 1; }
html[data-design="classic"] .btn-link {
  background: none; border: none; cursor: pointer;
  color: var(--brand-600, #0284c7); font-size: 12px;
  font-weight: 600; padding: 0; text-decoration: underline;
}
html[data-design="classic"] .btn-link:hover { color: var(--brand-700); }

/* ── Connection Status (ws-status) — topbar live indicator ──────── */
html[data-design="classic"] .ws-status {
  display: flex; align-items: center; gap: 5px;
  padding: 3px 8px; border-radius: var(--radius-full);
  background: rgba(16,185,129,0.08);
  border: 1px solid rgba(16,185,129,0.2);
}
html[data-design="classic"] .ws-dot { width: 7px; height: 7px; border-radius: 50%; flex-shrink: 0; }
html[data-design="classic"] .ws-dot-live {
  background: var(--success);
  box-shadow: 0 0 0 2px rgba(16,185,129,0.25);
  animation: classic-wsPulse 2s ease-in-out infinite;
}
html[data-design="classic"] .ws-dot-off  { background: var(--gray-300); }
html[data-design="classic"] .ws-label    { font-size: 11px; font-weight: 700; color: var(--success); }
@keyframes classic-wsPulse {
  0%,100% { box-shadow: 0 0 0 2px rgba(16,185,129,0.25); }
  50%      { box-shadow: 0 0 0 4px rgba(16,185,129,0.1); }
}

/* ── DesignSwitcher reset button ──────────────────────────────── */
html[data-design="classic"] .ds-reset-btn {
  background: rgba(239,68,68,0.1);
  border: 1px solid rgba(239,68,68,0.3);
  color: var(--danger);
  border-radius: 6px;
  padding: 3px 8px;
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s;
  white-space: nowrap;
}
html[data-design="classic"] .ds-reset-btn:hover {
  background: rgba(239,68,68,0.2);
  border-color: var(--danger);
}


/* ── src/styles/activity.css ── */
/* ========================================
