/* ========================================
   ACTIVITY LOG  SIDEBAR LAYOUT
   /* = */


/* Two-column layout */
html[data-design="classic"] .al-layout {
  display: grid;
  grid-template-columns: 220px 1fr;
  gap: 16px;
  align-items: start;
  width: 100%;
}

/*  Left sidebar  */
html[data-design="classic"] .al-sidebar {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  position: sticky;
  top: 80px;
}
html[data-design="classic"] .al-sidebar-section {
  padding: 10px 0;
  border-bottom: 1px solid var(--border);
}
html[data-design="classic"] .al-sidebar-section:first-child { padding-top: 0; }
html[data-design="classic"] .al-sidebar-section:last-child  { border-bottom: none; padding-bottom: 0; }
html[data-design="classic"] .al-sidebar-label {
  font-size: 10px;
  font-weight: 700;
  color: var(--gray-400);
  text-transform: uppercase;
  letter-spacing: 0.07em;
  margin-bottom: 6px;
}

/* Filter option rows */
html[data-design="classic"] .al-filter-options {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
html[data-design="classic"] .al-filter-opt {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 7px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  color: var(--gray-600);
  cursor: pointer;
  transition: background 0.12s;
  user-select: none;
}
html[data-design="classic"] .al-filter-opt:hover  { background: var(--gray-100); }
html[data-design="classic"] .al-filter-opt.active { background: var(--brand-50); color: var(--brand-600); font-weight: 600; }
html[data-design="classic"] .al-opt-count {
  margin-left: auto;
  font-size: 10px;
  color: var(--gray-400);
  font-weight: 500;
}
html[data-design="classic"] .al-filter-opt.active .al-opt-count { color: var(--brand-500); }

/* User filter section */
html[data-design="classic"] .al-user-search {
  width: 100%;
  font-size: 11px;
  padding: 5px 8px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-card);
  color: var(--gray-700);
  margin-bottom: 4px;
  box-sizing: border-box;
}
html[data-design="classic"] .al-user-search:focus { outline: none; border-color: var(--brand-400); }
html[data-design="classic"] .al-user-scroll {
  max-height: 180px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--gray-300) transparent;
}
html[data-design="classic"] .al-user-scroll::-webkit-scrollbar { width: 4px; }
html[data-design="classic"] .al-user-scroll::-webkit-scrollbar-thumb { background: var(--gray-300); border-radius: 4px; }
html[data-design="classic"] .al-user-opt-avatar {
  width: 20px; height: 20px; min-width: 20px;
  border-radius: 50%;
  background: var(--gray-200);
  color: var(--gray-600);
  font-size: 8px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
}
html[data-design="classic"] .al-filter-opt.active .al-user-opt-avatar { background: var(--brand-100); color: var(--brand-700); }
html[data-design="classic"] .al-user-opt-name { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
html[data-design="classic"][data-theme="dark"] .al-user-search { background: var(--bg-card); color: var(--gray-300); }
html[data-design="classic"][data-theme="dark"] .al-user-scroll::-webkit-scrollbar-thumb { background: var(--gray-600); }

/* Collapsible event group sections */
html[data-design="classic"] .al-event-group { padding: 0; border-bottom: 1px solid var(--border); }
html[data-design="classic"] .al-event-group:last-child { border-bottom: none; }
html[data-design="classic"] .al-event-group-header {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 9px 7px;
  cursor: pointer;
  border-radius: var(--radius-sm);
  transition: background 0.1s;
  user-select: none;
}
html[data-design="classic"] .al-event-group-header:hover  { background: var(--gray-100); }
html[data-design="classic"] .al-event-group-header.active { background: var(--brand-50); }
html[data-design="classic"] .al-event-group-icon { font-size: 13px; }
html[data-design="classic"] .al-event-group-name {
  flex: 1;
  font-size: 10px;
  font-weight: 700;
  color: var(--gray-500);
  text-transform: uppercase;
  letter-spacing: 0.07em;
}
html[data-design="classic"] .al-event-group-header.active .al-event-group-name { color: var(--brand-600); }
html[data-design="classic"] .al-event-group-caret { font-size: 10px; color: var(--gray-400); }
html[data-design="classic"] .al-event-group-body  { padding: 0 0 6px 0; }
html[data-design="classic"] .al-filter-opt-sub    { padding-left: 18px; font-size: 11.5px; }

html[data-design="classic"][data-theme="dark"] .al-event-group-header:hover  { background: var(--gray-800); }
html[data-design="classic"][data-theme="dark"] .al-event-group-header.active { background: rgba(14,165,233,0.1); }
html[data-design="classic"] .al-dot {
  width: 7px; height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}
html[data-design="classic"] .al-dot-created  { background: var(--success); }
html[data-design="classic"] .al-dot-updated  { background: #2563eb; }
html[data-design="classic"] .al-dot-deleted  { background: var(--danger); }
html[data-design="classic"] .al-dot-status   { background: var(--warning); }
html[data-design="classic"] .al-dot-progress { background: var(--purple); }

/*  Right feed  */
html[data-design="classic"] .al-feed {
  display: flex;
  flex-direction: column;
  gap: 0;
  min-width: 0;
}
html[data-design="classic"] .al-feed-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 0 10px 0;
  font-size: 12px;
  color: var(--gray-500);
}
html[data-design="classic"] .al-feed-count strong { color: var(--gray-800); font-weight: 700; }
html[data-design="classic"] .al-filtered-badge {
  display: inline-block;
  margin-left: 6px;
  background: var(--brand-100);
  color: var(--brand-700);
  font-size: 10px;
  font-weight: 600;
  padding: 1px 6px;
  border-radius: 10px;
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

/* Timeline groups */
html[data-design="classic"] .al-timeline { display: flex; flex-direction: column; gap: 16px; }
html[data-design="classic"] .al-group-label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  font-weight: 700;
  color: var(--gray-400);
  text-transform: uppercase;
  letter-spacing: 0.07em;
  margin-bottom: 4px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--border);
}
html[data-design="classic"] .al-group-count { font-weight: 400; font-size: 10px; color: var(--gray-400); }
html[data-design="classic"] .al-group-items { display: flex; flex-direction: column; }

/* Individual row */
html[data-design="classic"] .al-row {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 7px 10px;
  border-radius: var(--radius-sm);
  transition: background 0.1s;
}
html[data-design="classic"] .al-row:hover { background: var(--gray-50); }

/* Avatar */
html[data-design="classic"] .al-avatar {
  width: 28px; height: 28px; min-width: 28px;
  border-radius: 50%;
  background: var(--gray-200);
  color: var(--gray-600);
  font-size: 9px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 1px;
}

/* Row body */
html[data-design="classic"] .al-row-body  { flex: 1; min-width: 0; }
html[data-design="classic"] .al-row-main  {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  font-size: 12.5px;
  line-height: 1.4;
}
html[data-design="classic"] .al-user        { font-weight: 600; color: var(--gray-900); }
html[data-design="classic"] .al-entity-name { color: var(--gray-600); font-weight: 500; }

/* Action badge */
html[data-design="classic"] .al-badge {
  font-size: 9.5px;
  font-weight: 700;
  padding: 1px 5px;
  border-radius: 3px;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  white-space: nowrap;
  flex-shrink: 0;
}
html[data-design="classic"] .al-badge-created  { background: #dcfce7; color: #15803d; }
html[data-design="classic"] .al-badge-updated  { background: #dbeafe; color: #1d4ed8; }
html[data-design="classic"] .al-badge-deleted  { background: #fee2e2; color: var(--danger); }
html[data-design="classic"] .al-badge-status   { background: #fef9c3; color: #a16207; }
html[data-design="classic"] .al-badge-progress { background: #ede9fe; color: var(--purple); }

/* Change diff */
html[data-design="classic"] .al-change {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 2px;
  font-size: 11px;
}
html[data-design="classic"] .al-change-old   { text-decoration: line-through; color: var(--gray-400); }
html[data-design="classic"] .al-change-arrow { color: var(--gray-300); }
html[data-design="classic"] .al-change-new   { color: var(--gray-700); font-weight: 500; }

/* Meta row */
html[data-design="classic"] .al-row-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 2px;
  font-size: 10.5px;
  color: var(--gray-400);
}
html[data-design="classic"] .al-type-pill {
  background: var(--gray-100);
  color: var(--gray-500);
  font-size: 9px;
  font-weight: 700;
  padding: 1px 5px;
  border-radius: 3px;
  text-transform: uppercase;
  letter-spacing: 0.3px;
}
html[data-design="classic"] .al-meta-email {
  color: var(--gray-400);
}

/* Empty state */
html[data-design="classic"] .al-empty { text-align: center; padding: 48px 0; }

/* Export dropdown */
html[data-design="classic"] .al-export-wrap {
  position: relative;
}
html[data-design="classic"] .al-export-dropdown {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  min-width: 220px;
  z-index: 1000;
  overflow: hidden;
  padding: 4px;
}
html[data-design="classic"] .al-export-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 9px 12px;
  border: none;
  background: transparent;
  cursor: pointer;
  border-radius: var(--radius-md);
  text-align: left;
  transition: background 0.1s;
}
html[data-design="classic"] .al-export-item:hover { background: var(--gray-100); }
html[data-design="classic"] .al-export-icon { font-size: 18px; flex-shrink: 0; }
html[data-design="classic"] .al-export-label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: var(--gray-800);
}
html[data-design="classic"] .al-export-sub {
  display: block;
  font-size: 11px;
  color: var(--gray-400);
  margin-top: 1px;
}
html[data-design="classic"][data-theme="dark"] .al-export-dropdown { background: var(--bg-card); }
html[data-design="classic"][data-theme="dark"] .al-export-item:hover { background: var(--gray-800); }
html[data-design="classic"][data-theme="dark"] .al-export-label { color: var(--gray-200); }

/* Search & inputs */
html[data-design="classic"] .al-search-input {
  width: 100%;
  font-size: 12px;
  padding: 7px 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg-card);
  color: var(--gray-800);
  box-sizing: border-box;
}
html[data-design="classic"] .al-search-input:focus { outline: none; border-color: var(--brand-400); }
html[data-design="classic"] .al-select {
  width: 100%;
  font-size: 12px;
  padding: 6px 8px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg-card);
  color: var(--gray-700);
  cursor: pointer;
  box-sizing: border-box;
}
html[data-design="classic"] .al-select:focus { outline: none; border-color: var(--brand-400); }
html[data-design="classic"] .al-date-input {
  width: 100%;
  font-size: 12px;
  padding: 6px 8px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg-card);
  color: var(--gray-700);
  box-sizing: border-box;
}

/*  Dark mode  */
html[data-design="classic"][data-theme="dark"] .al-sidebar        { background: var(--bg-card); }
html[data-design="classic"][data-theme="dark"] .al-avatar         { background: var(--gray-700); color: var(--gray-300); }
html[data-design="classic"][data-theme="dark"] .al-type-pill      { background: var(--gray-800); color: var(--gray-500); }
html[data-design="classic"][data-theme="dark"] .al-row:hover      { background: var(--gray-800); }
html[data-design="classic"][data-theme="dark"] .al-filter-opt:hover  { background: var(--gray-800); }
html[data-design="classic"][data-theme="dark"] .al-filter-opt.active { background: rgba(14,165,233,0.12); }
html[data-design="classic"][data-theme="dark"] .al-badge-created  { background: #14532d; color: #86efac; }
html[data-design="classic"][data-theme="dark"] .al-badge-updated  { background: #1e3a5f; color: #93c5fd; }
html[data-design="classic"][data-theme="dark"] .al-badge-deleted  { background: #450a0a; color: #fca5a5; }
html[data-design="classic"][data-theme="dark"] .al-badge-status   { background: #422006; color: #fde047; }
html[data-design="classic"][data-theme="dark"] .al-badge-progress { background: #2e1065; color: #c4b5fd; }
html[data-design="classic"][data-theme="dark"] .al-search-input   { background: var(--bg-card); color: var(--gray-200); }
html[data-design="classic"][data-theme="dark"] .al-select         { background: var(--bg-card); color: var(--gray-300); }
html[data-design="classic"][data-theme="dark"] .al-date-input     { background: var(--bg-card); color: var(--gray-300); }
html[data-design="classic"][data-theme="dark"] .al-filtered-badge { background: rgba(14,165,233,0.15); color: var(--brand-400); }

/* Responsive  stack on narrow screens */
@media (max-width: 480px) {
  html[data-design="classic"] .al-layout { grid-template-columns: 1fr; }
  html[data-design="classic"] .al-sidebar { position: static; }
}

