   ACTIVITY LOG  ENTERPRISE UPGRADE
   /* = */


/* Severity indicators */
html[data-design="classic"] .al-severity-dot {
  width: 7px; height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
  display: inline-block;
}
html[data-design="classic"] .sev-warning  { background: var(--warning); }
html[data-design="classic"] .sev-critical { background: var(--danger); box-shadow: 0 0 0 2px #fee2e2; }

html[data-design="classic"] .al-severity-pill {
  font-size: 9px;
  font-weight: 700;
  padding: 1px 5px;
  border-radius: 3px;
  text-transform: uppercase;
  letter-spacing: 0.3px;
}
html[data-design="classic"] .sev-info     { background: #dbeafe; color: #1d4ed8; }
html[data-design="classic"] .sev-warning  { background: #fef3c7; color: var(--warning); }
html[data-design="classic"] .sev-critical { background: #fee2e2; color: var(--danger); }

/* Human-readable sentence */
html[data-design="classic"] .al-human {
  font-size: 12px;
  color: var(--gray-600);
  margin-top: 2px;
  font-style: italic;
}

/* Extra badge classes */
html[data-design="classic"] .al-badge-completed { background: #d1fae5; color: #065f46; }
html[data-design="classic"] .al-badge-archived  { background: var(--gray-100); color: var(--gray-600); }
html[data-design="classic"] .al-badge-warning   { background: #fef3c7; color: #b45309; }
html[data-design="classic"] .al-badge-progress  { background: #ede9fe; color: var(--purple); }
html[data-design="classic"] .al-badge-status    { background: #fef9c3; color: #a16207; }

/* Extra dot classes */
html[data-design="classic"] .al-dot-completed { background: var(--success); }
html[data-design="classic"] .al-dot-archived  { background: var(--gray-400); }
html[data-design="classic"] .al-dot-warning   { background: var(--warning); }
html[data-design="classic"] .al-dot-status    { background: #a16207; }

/*  Health panel  */
html[data-design="classic"] .al-health-panel {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 16px 20px;
  margin-bottom: 16px;
}
html[data-design="classic"] .al-health-title {
  font-size: 11px;
  font-weight: 700;
  color: var(--gray-400);
  text-transform: uppercase;
  letter-spacing: 0.07em;
  margin-bottom: 12px;
}
html[data-design="classic"] .al-health-grid {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 12px;
}
html[data-design="classic"] .al-health-card {
  flex: 1;
  min-width: 120px;
  background: var(--gray-50);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 12px 14px;
}
html[data-design="classic"] .al-health-card-alert { border-color: #fecaca; background: #fff5f5; }
html[data-design="classic"] .al-health-num  { font-size: 26px; font-weight: 800; color: var(--gray-800); line-height: 1; }
html[data-design="classic"] .al-health-lbl  { font-size: 11px; font-weight: 600; color: var(--gray-500); margin-top: 4px; }
html[data-design="classic"] .al-health-sub  { font-size: 10px; color: var(--gray-400); margin-top: 2px; }
html[data-design="classic"] .al-alerts-list { display: flex; flex-direction: column; gap: 4px; border-top: 1px solid var(--border); padding-top: 10px; }
html[data-design="classic"] .al-alert-row   {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  padding: 4px 0;
}
html[data-design="classic"] .al-alert-text  { flex: 1; color: var(--gray-700); }
html[data-design="classic"] .al-alert-time  { color: var(--gray-400); font-size: 11px; }

/*  Burst groups  */
html[data-design="classic"] .al-burst {
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  margin-bottom: 4px;
  overflow: hidden;
}
html[data-design="classic"] .al-burst-header {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 8px 10px;
  cursor: pointer;
  background: var(--gray-50);
  transition: background 0.1s;
}
html[data-design="classic"] .al-burst-header:hover { background: var(--gray-100); }
html[data-design="classic"] .al-burst-summary { flex: 1; }
html[data-design="classic"] .al-burst-count {
  display: inline-block;
  background: var(--brand-100);
  color: var(--brand-700);
  font-size: 10px;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 10px;
}
html[data-design="classic"] .al-burst-hint { color: var(--gray-400); font-size: 10px; }
html[data-design="classic"] .al-burst-entries {
  border-top: 1px solid var(--border);
  background: var(--bg-card);
}
html[data-design="classic"] .al-burst-entries .al-row { padding-left: 20px; }

/*  Entity Activity Tab  */
html[data-design="classic"] .eat-list { display: flex; flex-direction: column; padding: 8px 0; }
html[data-design="classic"] .eat-row  {
  display: flex;
  gap: 0;
  padding: 0;
}
html[data-design="classic"] .eat-line-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 24px;
  flex-shrink: 0;
}
html[data-design="classic"] .eat-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
  margin-top: 4px;
  border: 2px solid var(--bg-card);
  box-shadow: 0 0 0 1px var(--border);
}
html[data-design="classic"] .eat-dot-created   { background: var(--success); }
html[data-design="classic"] .eat-dot-updated   { background: #2563eb; }
html[data-design="classic"] .eat-dot-deleted   { background: var(--danger); }
html[data-design="classic"] .eat-dot-completed { background: var(--success); }
html[data-design="classic"] .eat-dot-status    { background: var(--warning); }
html[data-design="classic"] .eat-dot-progress  { background: var(--purple); }
html[data-design="classic"] .eat-dot-warning   { background: var(--warning); }

html[data-design="classic"] .eat-line {
  width: 2px;
  flex: 1;
  background: var(--border);
  min-height: 16px;
}
html[data-design="classic"] .eat-row:last-child .eat-line { display: none; }

html[data-design="classic"] .eat-body {
  flex: 1;
  padding: 0 12px 16px 10px;
}
html[data-design="classic"] .eat-main  {
  display: flex;
  align-items: flex-start;
  flex-direction: column;
  gap: 2px;
}
html[data-design="classic"] .eat-label  { font-size: 12px; font-weight: 600; color: var(--gray-800); }
html[data-design="classic"] .eat-human  { font-size: 12px; color: var(--gray-500); }
html[data-design="classic"] .eat-diff   { display: flex; align-items: center; gap: 4px; font-size: 11px; }
html[data-design="classic"] .eat-old    { text-decoration: line-through; color: var(--gray-400); }
html[data-design="classic"] .eat-arrow  { color: var(--gray-300); }
html[data-design="classic"] .eat-new    { color: var(--gray-700); font-weight: 500; }
html[data-design="classic"] .eat-meta   { display: flex; align-items: center; gap: 8px; margin-top: 3px; }
html[data-design="classic"] .eat-user   { font-size: 11px; font-weight: 600; color: var(--gray-500); }
html[data-design="classic"] .eat-time   { font-size: 11px; color: var(--gray-400); }
html[data-design="classic"] .eat-severity { font-size: 9px; font-weight: 700; padding: 1px 5px; border-radius: 3px; text-transform: uppercase; }
html[data-design="classic"] .eat-sev-warning  { background: #fef3c7; color: var(--warning); }
html[data-design="classic"] .eat-sev-critical { background: #fee2e2; color: var(--danger); }
html[data-design="classic"] .eat-empty { text-align: center; padding: 32px 0; color: var(--gray-400); font-size: 13px; }

/* Dark mode for new classes */
html[data-design="classic"][data-theme="dark"] .al-health-panel   { background: var(--bg-card); }
html[data-design="classic"][data-theme="dark"] .al-health-card    { background: var(--gray-800); border-color: var(--gray-700); }
html[data-design="classic"][data-theme="dark"] .al-health-num     { color: var(--gray-100); }
html[data-design="classic"][data-theme="dark"] .al-burst-header   { background: var(--gray-800); }
html[data-design="classic"][data-theme="dark"] .al-burst-header:hover { background: var(--gray-700); }
html[data-design="classic"][data-theme="dark"] .al-burst          { border-color: var(--gray-700); }
html[data-design="classic"][data-theme="dark"] .al-badge-completed { background: #064e3b; color: #6ee7b7; }
html[data-design="classic"][data-theme="dark"] .al-badge-archived  { background: var(--gray-800); color: var(--gray-400); }
html[data-design="classic"][data-theme="dark"] .al-badge-warning   { background: #451a03; color: #fcd34d; }

/* ========================================
   ENTITY ACTIVITY PANEL (inline in cards)
   /* = */

html[data-design="classic"] .entity-activity-panel {
  margin-top: 12px;
  border-top: 1px solid var(--border);
  padding-top: 12px;
}
html[data-design="classic"] .entity-activity-panel-title {
  font-size: 11px;
  font-weight: 700;
  color: var(--gray-400);
  text-transform: uppercase;
  letter-spacing: 0.07em;
  margin-bottom: 8px;
}
html[data-design="classic"] .btn-active {
  background: var(--brand-100) !important;
  color: var(--brand-700) !important;
  border-color: var(--brand-300) !important;
}
html[data-design="classic"][data-theme="dark"] .btn-active {
  background: rgba(14,165,233,0.15) !important;
  color: var(--brand-400) !important;
}

/*  Relative time  */
html[data-design="classic"] .al-rel-time {
  color: var(--gray-400);
  font-size: 11px;
  cursor: default;
}
html[data-design="classic"] .al-rel-time:hover { color: var(--gray-600); }

/*  Burst bullet list  */
html[data-design="classic"] .al-burst-bullets {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 5px 0 2px 0;
}
html[data-design="classic"] .al-burst-bullet {
  display: flex;
  align-items: flex-start;
  gap: 5px;
  font-size: 11.5px;
  color: var(--gray-600);
  line-height: 1.4;
}
html[data-design="classic"] .al-burst-bullet-dot {
  color: var(--brand-400);
  font-size: 10px;
  margin-top: 1px;
  flex-shrink: 0;
}
html[data-design="classic"] .al-burst-more {
  color: var(--gray-400);
  font-style: italic;
  font-size: 11px;
}
html[data-design="classic"][data-theme="dark"] .al-burst-bullet  { color: var(--gray-400); }
html[data-design="classic"][data-theme="dark"] .al-burst-more    { color: var(--gray-500); }

/*  Task inline activity row  */
html[data-design="classic"] .task-activity-inline {
  width: 100%;
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid var(--border);
}

/* ========================================
   LEGACY ACTIVITY FILTER BAR
   (used in CustomFields, AISettings pages)
   /* = */

html[data-design="classic"] .activity-filters {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
  flex-wrap: wrap;
  align-items: center;
}

/* ========================================
   LEGACY AL-FILTER-BAR
   (used in ActivityLog sidebar filter area)
   /* = */

html[data-design="classic"] .al-filter-bar {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 12px 16px;
  margin-bottom: 20px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
html[data-design="classic"] .al-filter-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

/* ========================================
   LEGACY ACTIVITY TIMELINE STYLES
   (kept for backward compat with any old references)
   /* = */

html[data-design="classic"] .activity-stats {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 12px;
  margin-bottom: 20px;
}
html[data-design="classic"] .activity-stat-card {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  padding: 16px;
  display: flex;
  align-items: center;
  gap: 14px;
  box-shadow: var(--shadow-sm);
}
html[data-design="classic"] .activity-stat-icon  { font-size: 24px; }
html[data-design="classic"] .activity-stat-value { font-size: 24px; font-weight: 800; line-height: 1; letter-spacing: -1px; }
html[data-design="classic"] .activity-stat-label { font-size: 11px; color: var(--gray-500); text-transform: uppercase; letter-spacing: 0.04em; margin-top: 2px; font-weight: 500; }
html[data-design="classic"] .activity-timeline   { display: flex; flex-direction: column; gap: 24px; }
html[data-design="classic"] .activity-date-label { font-size: 11px; font-weight: 700; color: var(--gray-400); text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 12px; padding-bottom: 8px; border-bottom: 1px solid var(--border); }
html[data-design="classic"] .activity-item       { display: flex; gap: 12px; padding: 6px 0; }
html[data-design="classic"] .activity-icon-col   { display: flex; flex-direction: column; align-items: center; flex-shrink: 0; }
html[data-design="classic"] .activity-icon       { width: 34px; height: 34px; border-radius: var(--radius-md); display: flex; align-items: center; justify-content: center; font-size: 14px; flex-shrink: 0; }
html[data-design="classic"] .activity-line       { width: 2px; background: var(--gray-100); flex: 1; margin-top: 4px; min-height: 16px; }
html[data-design="classic"] .activity-content    { flex: 1; padding-bottom: 14px; }
html[data-design="classic"] .activity-title      { font-size: 13px; margin-bottom: 4px; font-weight: 500; }
html[data-design="classic"] .activity-change     { display: flex; align-items: center; font-size: 12px; margin-bottom: 4px; }
html[data-design="classic"] .activity-old        { background: #fef2f2; color: var(--danger); padding: 1px 6px; border-radius: var(--radius-sm); text-decoration: line-through; }
html[data-design="classic"] .activity-new        { padding: 1px 6px; border-radius: var(--radius-sm); }
html[data-design="classic"] .activity-meta       { display: flex; gap: 8px; font-size: 11px; color: var(--gray-400); flex-wrap: wrap; }
html[data-design="classic"] .activity-entity-type{ background: var(--gray-100); padding: 1px 7px; border-radius: var(--radius-sm); font-weight: 600; color: var(--gray-600); }
html[data-design="classic"] .activity-empty      { text-align: center; padding: 60px 0; }
html[data-design="classic"] .activity-date-group { margin-bottom: 24px; }
html[data-design="classic"] .activity-date-items { display: flex; flex-direction: column; gap: 0; }
html[data-design="classic"] .activity-performer-full { font-size: 11px; color: var(--gray-400); }
html[data-design="classic"] .activity-time       { font-size: 11px; color: var(--gray-400); }

html[data-design="classic"][data-theme="dark"] .activity-stat-card    { background: #071525; border-color: #1e3a5a; }
html[data-design="classic"][data-theme="dark"] .activity-date-label   { border-color: #1e3a5a; }
html[data-design="classic"][data-theme="dark"] .activity-line         { background: #1e3a5a; }
html[data-design="classic"][data-theme="dark"] .activity-entity-type  { background: #0a1e35; color: var(--gray-600); }

/*  Dark mode additions  */
html[data-design="classic"][data-theme="dark"] .activity-stat-card      { background: var(--bg-card); border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .al-filter-bar           { background: var(--bg-card); border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .al-select               { background: var(--bg-input); border-color: var(--border); color: var(--gray-600); }
html[data-design="classic"][data-theme="dark"] .al-group-header         { background: #050f1e; border-color: var(--border); color: var(--gray-600); }
html[data-design="classic"][data-theme="dark"] .activity-burst-group    { background: var(--bg-card); border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .activity-health-panel   { background: var(--bg-card); border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .entity-activity-tab     { background: var(--bg-card); border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .al-sidebar              { background: var(--bg-card); border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .al-sidebar-section      { border-color: #1a3550; }


