html[data-design="classic"] .team-member-header {
  display: flex;
  align-items: flex-start;
  gap: 14px;
}
html[data-design="classic"] .team-member-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
html[data-design="classic"] .team-member-name {
  font-size: 15px;
  font-weight: 700;
  color: var(--gray-800);
}
html[data-design="classic"] .team-member-email {
  font-size: 12px;
  color: var(--gray-500);
}
html[data-design="classic"] .team-member-stats {
  display: flex;
  gap: 16px;
  padding: 12px 16px;
  background: var(--gray-50);
  border-radius: var(--radius-md);
}
html[data-design="classic"] .team-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  flex: 1;
}
html[data-design="classic"] .team-stat-value {
  font-size: 22px;
  font-weight: 800;
  color: var(--gray-800);
  letter-spacing: -1px;
}
html[data-design="classic"] .team-stat-label {
  font-size: 10px;
  color: var(--gray-400);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-weight: 500;
}
html[data-design="classic"] .assignment-section {
