  align-items: center;
  gap: 10px;
  padding: 14px 18px;
  background: var(--gray-50);
  border-bottom: 1px solid var(--border);
}
html[data-design="classic"] .assign-member-row {
  display: flex;
  align-items: center;
  gap: 12px;
