}
html[data-design="classic"] .assign-check {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 2px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
}
html[data-design="classic"] .assign-check.checked {
  background: var(--brand-500);
  border-color: var(--brand-500);
  color: #fff;
}

/* ========================================
   INTEGRATIONS
   /* = */

html[data-design="classic"] .integration-card {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  padding: 22px;
  box-shadow: var(--shadow-sm);
}
html[data-design="classic"] .integration-card-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 8px;
}
html[data-design="classic"] .integration-name {
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 3px;
  color: var(--gray-800);
}
html[data-design="classic"] .integration-desc {
  font-size: 13px;
  color: var(--gray-500);
}
html[data-design="classic"] .integration-status {
  font-size: 12px;
  font-weight: 600;
  padding: 4px 12px;
  border-radius: var(--radius-full);
}
html[data-design="classic"] .integration-status.enabled {
  background: #d1fae5;
  color: #065f46;
}
html[data-design="classic"] .integration-status.disabled {
  background: var(--gray-100);
  color: var(--gray-500);
}
html[data-design="classic"] .integration-form {
  margin-top: 18px;
  padding-top: 18px;
  border-top: 1px solid var(--border);
}
html[data-design="classic"] .integration-result {
  padding: 10px 14px;
  border-radius: var(--radius-md);
  font-size: 13px;
  margin-bottom: 10px;
}
html[data-design="classic"] .integration-result.success {
  background: #d1fae5;
  color: #065f46;
}
html[data-design="classic"] .integration-result.error {
  background: #fef2f2;
  color: var(--danger);
}
html[data-design="classic"] .integration-help {
  margin-top: 32px;
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  padding: 24px;
  box-shadow: var(--shadow-sm);
}
html[data-design="classic"] .integration-help h3 {
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 16px;
  color: var(--gray-700);
}
html[data-design="classic"] .integration-help-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 16px;
}
html[data-design="classic"] .integration-help-card {
  background: var(--gray-50);
  border-radius: var(--radius-md);
  padding: 16px;
  border: 1px solid var(--border);
}
html[data-design="classic"] .integration-help-card code {
  background: var(--brand-50);
  color: var(--brand-600);
  padding: 1px 5px;
  border-radius: var(--radius-sm);
  font-size: 11px;
}

/* ========================================
