/*
   MOBILE
   /* = */

html[data-design="classic"] .mobile-header {
  display: none;
  background: #0f1117;
  padding: 14px 16px;
  align-items: center;
  gap: 12px;
  position: sticky;
  top: 0;
  z-index: 100;
}
html[data-design="classic"] .mobile-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #fff;
  font-size: 17px;
  font-weight: 800;
  background: linear-gradient(135deg, #38bdf8, #0ea5e9);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
html[data-design="classic"] .menu-btn {
  background: transparent;
  color: rgba(255, 255, 255, 0.7);
  font-size: 22px;
  padding: 4px 8px;
}

@media (max-width: 768px) {
  html[data-design="classic"] .sidebar {
    transform: translateX(-100%);
    width: 260px;
  }
  html[data-design="classic"] .sidebar.open {
    transform: translateX(0);
    box-shadow: var(--shadow-xl);
  }
  html[data-design="classic"] .content-wrapper {
    margin-left: 0;
  }
  html[data-design="classic"] .mobile-header {
    display: flex;
  }
  html[data-design="classic"] .overlay {
    display: block;
  }
  html[data-design="classic"] .main-content {
    padding: 20px 16px;
  }
  html[data-design="classic"] .topbar {
    display: none;
  }
  html[data-design="classic"] .kanban-board {
    grid-template-columns: 1fr;
  }
  html[data-design="classic"] .report-charts-row {
    grid-template-columns: 1fr;
  }
  html[data-design="classic"] .ai-assistant-layout {
    grid-template-columns: 1fr;
  }
  html[data-design="classic"] .ai-sidebar-panels {
    flex-direction: row;
    flex-wrap: wrap;
    overflow-x: auto;
  }
  html[data-design="classic"] .ai-provider-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  html[data-design="classic"] .ai-features-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  html[data-design="classic"] .page-header-block {
    flex-direction: column;
    align-items: flex-start;
    gap: 14px;
  }
  html[data-design="classic"] .menu-close {
    display: flex;
  }
}

