html[data-design="classic"][data-theme="dark"] {
  --bg-page:  #030b18;
  --bg-card:  #071525;
  --bg-input: #0a1e35;
  --border:   #122640;

  /* Gray scale: light values for readable text on dark backgrounds */
  --gray-50:  #0a1e35;
  --gray-100: #112338;
  --gray-200: #1a3550;
  --gray-300: #2a4f72;
  --gray-400: #6b90b0;  /* subtle text, placeholders */
  --gray-500: #8cb4d0;  /* secondary text */
  --gray-600: #aecde3;  /* body text */
  --gray-700: #cce0f0;  /* primary text */
  --gray-800: #e2eff8;  /* headings */
  --gray-900: #f0f7fc;  /* high-contrast text */

  /* Brand palette remapped for dark backgrounds */
  --brand-50:  #051220;
  --brand-100: #0a1e35;
  --brand-200: #0f3050;
  --brand-300: #1a4a72;
  --brand-400: #2d7ab0;
  --brand-600: #38bdf8;
  --brand-700: #7dd3fc;
  --brand-800: #bae6fd;

  /* Tokens added with the Studio + Atlas foundation */
  --text-primary:   #e2eff8;
  --text-secondary: #aecde3;
  --text-muted:     #8cb4d0;
  --border-strong:  #1e3a5a;
  --input-border:   #1e3a5a;
  --card-border:    #122640;
  --success-text:   #6EE7A8;
  --warning-text:   #FBC56B;
  --danger-text:    #FCA5A5;
  --success-soft:   rgba(30, 142, 90, 0.18);
  --warning-soft:   rgba(193, 125, 34, 0.2);
