/* ========================================
   COLOR PICKERS
   /* = */

html[data-design="classic"] .color-picker {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 4px 0;
}
html[data-design="classic"] .color-dot {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  cursor: pointer;
  border: 2px solid transparent;
  transition: all 0.15s;
  box-shadow: var(--shadow-xs);
}
html[data-design="classic"] .color-dot.selected {
  border-color: var(--gray-800);
  box-shadow: 0 0 0 3px rgba(0, 0, 0, 0.15);
  transform: scale(1.1);
}
html[data-design="classic"] .icon-dot {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  cursor: pointer;
  border-radius: var(--radius-md);
  border: 2px solid transparent;
  transition: all 0.15s;
}
html[data-design="classic"] .icon-dot.selected {
  border-color: var(--brand-500);
  background: var(--brand-50);
}
html[data-design="classic"] .icon-dot:hover {
  background: var(--gray-100);
}

/* ========================================
/* ========================================
   THEME SWITCHER
   /* = */

html[data-design="classic"] .theme-switcher-wrapper {
  position: relative;
}
/* theme-switcher-btn base styles are in layout.css with all topbar icon buttons */

html[data-design="classic"] .theme-switcher-panel {
  position: absolute;
  right: 0;
  top: 50px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-xl);
  z-index: 300;
  width: 360px;
  overflow: hidden;
  animation: classic-slideUp 0.2s ease;
}

html[data-design="classic"] .theme-switcher-header {
  padding: 14px 18px;
  font-size: 13px;
  font-weight: 700;
  color: var(--gray-700);
  border-bottom: 1px solid var(--border);
  background: var(--gray-50);
  letter-spacing: 0.02em;
}

html[data-design="classic"] .theme-switcher-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  padding: 14px;
  max-height: 420px;
  overflow-y: auto;
}

html[data-design="classic"] .theme-card {
  background: var(--gray-50);
  border: 2px solid var(--border);
  border-radius: var(--radius-md);
  padding: 12px;
  cursor: pointer;
  transition: all 0.18s;
  position: relative;
}
html[data-design="classic"] .theme-card:hover {
  border-color: var(--brand-400);
  background: var(--brand-50);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}
html[data-design="classic"] .theme-card.active {
  border-color: var(--brand-500);
  background: var(--brand-50);
  box-shadow: 0 0 0 1px var(--brand-500);
}

html[data-design="classic"] .theme-swatches {
  display: flex;
  gap: 3px;
  margin-bottom: 8px;
  border-radius: 6px;
  overflow: hidden;
  height: 28px;
}
html[data-design="classic"] .theme-swatch {
  flex: 1;
  height: 100%;
}

html[data-design="classic"] .theme-card-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--gray-800);
  margin-bottom: 2px;
}
html[data-design="classic"] .theme-card-desc {
  font-size: 10px;
  color: var(--gray-500);
  line-height: 1.4;
}
html[data-design="classic"] .theme-card-active-badge {
  position: absolute;
  top: 8px;
  right: 8px;
  background: var(--brand-500);
  color: #fff;
  font-size: 9px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: var(--radius-full);
}

html[data-design="classic"][data-theme="dark"] .theme-switcher-panel {
  background: var(--bg-card);
  border-color: var(--border);
}
html[data-design="classic"][data-theme="dark"] .theme-switcher-header {
  background: var(--gray-50);
  border-color: var(--border);
}
html[data-design="classic"][data-theme="dark"] .theme-card {
  background: var(--gray-100);
  border-color: var(--border);
}
html[data-design="classic"][data-theme="dark"] .theme-card:hover {
  background: var(--gray-200);
}
html[data-design="classic"][data-theme="dark"] .theme-card.active {
  background: var(--gray-200);
}
html[data-design="classic"][data-theme="dark"] .theme-switcher-btn:hover {
  background: var(--gray-100);
}

/* ========================================
   LIVE CLOCK  TOPBAR
   /* = */

html[data-design="classic"] .live-clock {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  padding: 0 14px;
  border-right: 1px solid var(--border);
  margin-right: 4px;
  gap: 1px;
  cursor: default;
  user-select: none;
}
html[data-design="classic"] .live-clock-time {
  display: flex;
  align-items: baseline;
  gap: 0;
}
html[data-design="classic"] .live-clock-hm {
  font-size: 17px;
  font-weight: 800;
  color: var(--gray-800);
  letter-spacing: -0.5px;
  font-variant-numeric: tabular-nums;
}
html[data-design="classic"] .live-clock-sec {
  font-size: 10px;
  font-weight: 600;
  color: var(--gray-400);
  font-variant-numeric: tabular-nums;
  margin-left: 1px;
  align-self: flex-start;
  margin-top: 3px;
}
html[data-design="classic"] .live-clock-period {
  font-size: 9px;
  font-weight: 700;
  color: var(--gray-400);
  margin-left: 4px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  align-self: flex-start;
  margin-top: 3px;
}
html[data-design="classic"] .live-clock-date {
  font-size: 10px;
  color: var(--gray-400);
  font-weight: 400;
  display: flex;
  align-items: center;
  gap: 3px;
  white-space: nowrap;
}
html[data-design="classic"] .live-clock-weekday {
  font-weight: 600;
  color: var(--gray-600);
}
html[data-design="classic"] .live-clock-tz {
  color: var(--gray-400);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.2px;
  margin-left: 1px;
}

/* Hide date on small screens */
@media (max-width: 768px) {
  html[data-design="classic"] .live-clock { display: none; }
}

html[data-design="classic"][data-theme="dark"] .live-clock-hm     { color: #e2eff8; }
html[data-design="classic"][data-theme="dark"] .live-clock-sec    { color: #6b90b0; }
