  border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  color: var(--gray-600, var(--gray-600));
  transition: all 0.15s;
  flex-shrink: 0;
  box-sizing: border-box;
}
html[data-design="classic"] .ds-trigger:hover {
  background: var(--gray-100, var(--gray-100));
  border-color: var(--border, var(--border));
  color: var(--gray-900, var(--gray-900));
}

/* Inner pill  gradient border + label */
html[data-design="classic"] .ds-trigger-inner {
  display: flex;
  align-items: center;
  gap: 5px;
  height: 34px;
  padding: 0 9px;
  border-radius: 8px;
  box-sizing: border-box;
  background: linear-gradient(#fff, #fff) padding-box,
              linear-gradient(135deg, var(--danger), #f97316, var(--warning), var(--success), var(--brand-500)) border-box;
  border: 1.5px solid transparent;
  transition: all 0.15s;
}
html[data-design="classic"] .ds-trigger:hover .ds-trigger-inner {
  background: linear-gradient(var(--gray-50,var(--gray-50)), var(--gray-50,var(--gray-50))) padding-box,
              linear-gradient(135deg, var(--danger), #f97316, var(--warning), var(--success), var(--brand-500)) border-box;
  box-shadow: 0 0 12px rgba(99,102,241,0.2);
}
html[data-design="classic"] .ds-trigger-icon {
  flex-shrink: 0;
  color: var(--gray-600, var(--gray-600));
  transition: color 0.13s;
}
html[data-design="classic"] .ds-trigger:hover .ds-trigger-icon { color: var(--gray-800, var(--gray-800)); }
html[data-design="classic"] .ds-trigger-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: var(--gray-600, var(--gray-600));
  white-space: nowrap;
  transition: color 0.13s;
}
html[data-design="classic"] .ds-trigger:hover .ds-trigger-label { color: var(--gray-900, var(--gray-900)); }

/* Dark mode */
