html[data-design="classic"][data-theme="dark"] .ds-trigger-inner {
  background: linear-gradient(rgba(255,255,255,0.07), rgba(255,255,255,0.07)) padding-box,
              linear-gradient(135deg, var(--danger), #f97316, var(--warning), var(--success), var(--brand-500)) border-box;
}
