html[data-design="classic"][data-theme="dark"] .ds-trigger:hover .ds-trigger-icon { color: #fff; }
html[data-design="classic"][data-theme="dark"] .ds-trigger-label { color: rgba(255,255,255,0.7); }
html[data-design="classic"][data-theme="dark"] .ds-trigger:hover .ds-trigger-label { color: #fff; }

/* Panel */
html[data-design="classic"] .ds-panel {
