}
html[data-design="classic"] .ds-close:hover { background: var(--gray-100, var(--gray-100)); color: var(--gray-700, var(--gray-700)); }
html[data-design="classic"][data-theme="dark"] .ds-close:hover { background: rgba(255,255,255,0.07); color: #fff; }

/* Search */
html[data-design="classic"] .ds-search-wrap {
  display: flex; align-items: center; gap: 8px;
