  color: var(--gray-400, var(--gray-400));
}
html[data-design="classic"][data-theme="dark"] .ds-search-wrap { background: var(--gray-900); border-color: rgba(255,255,255,0.08); }
html[data-design="classic"] .ds-search {
  flex: 1; border: none; background: transparent;
  font-size: 13px; color: var(--gray-700, var(--gray-700));
