}
html[data-design="classic"][data-theme="dark"] .ds-search { color: rgba(255,255,255,0.8); }
html[data-design="classic"] .ds-search::placeholder { color: var(--gray-400, var(--gray-400)); }
html[data-design="classic"] .ds-search-clear {
  background: none; border: none; color: var(--gray-400, var(--gray-400));
