}
html[data-design="classic"] .ds-search-clear:hover { background: var(--gray-100, var(--gray-100)); }

/* Category tabs */
html[data-design="classic"] .ds-cats {
  display: flex; gap: 4px; flex-wrap: wrap;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border, var(--border));
  background: var(--gray-50, var(--gray-50));
}
html[data-design="classic"][data-theme="dark"] .ds-cats {
  background: rgba(255,255,255,0.02);
  border-color: rgba(255,255,255,0.07);
}
html[data-design="classic"] .ds-cat {
  display: flex; align-items: center; gap: 4px;
  padding: 4px 10px;
  border-radius: var(--radius-full);
  font-size: 11px; font-weight: 600;
  background: transparent;
  border: 1px solid var(--border, var(--border));
  color: var(--gray-500, var(--gray-500));
  cursor: pointer;
  transition: all 0.12s;
