}
html[data-design="classic"] .ds-cat:hover { background: var(--gray-100, var(--gray-100)); color: var(--gray-800, var(--gray-800)); }
html[data-design="classic"] .ds-cat.active {
  background: var(--brand-500, var(--brand-500));
  border-color: var(--brand-500, var(--brand-500));
  color: #fff;
}
html[data-design="classic"][data-theme="dark"] .ds-cat { border-color: rgba(255,255,255,0.1); color: rgba(255,255,255,0.45); }
html[data-design="classic"][data-theme="dark"] .ds-cat:hover { background: rgba(255,255,255,0.07); color: rgba(255,255,255,0.85); }
html[data-design="classic"] .ds-cat-count {
  font-size: 9px;
  background: rgba(0,0,0,0.1);
  padding: 1px 4px;
  border-radius: var(--radius-full);
}
html[data-design="classic"] .ds-cat.active .ds-cat-count { background: rgba(255,255,255,0.25); }

/* Grid */
html[data-design="classic"] .ds-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  padding: 14px;
  max-height: 420px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--border,var(--border)) transparent;
}
html[data-design="classic"] .ds-grid::-webkit-scrollbar { width: 4px; }
html[data-design="classic"] .ds-grid::-webkit-scrollbar-thumb { background: var(--border,var(--border)); border-radius: 2px; }

html[data-design="classic"] .ds-empty {
  grid-column: 1/-1;
