}
html[data-design="classic"] .ds-empty button { color: var(--brand-500,var(--brand-500)); background:none; border:none; cursor:pointer; font-weight:600; }

/* Design card */
html[data-design="classic"] .ds-card {
  position: relative;
  border: 2px solid var(--border, var(--border));
  border-radius: 12px;
  overflow: hidden;
  cursor: pointer;
  transition: all 0.16s;
  background: var(--gray-50, var(--gray-50));
}
html[data-design="classic"] .ds-card:hover {
  border-color: var(--brand-400, var(--brand-400));
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(99,102,241,0.15);
}
html[data-design="classic"] .ds-card.active {
