html[data-design="classic"][data-theme="dark"] .ds-card:hover { border-color: var(--brand-500); }

/* Color strip preview */
html[data-design="classic"] .ds-preview {
  display: flex;
  height: 22px;
  overflow: hidden;
}
html[data-design="classic"] .ds-swatch { flex: 1; }

/* Mini layout preview */
html[data-design="classic"] .ds-mini-layout {
  display: flex;
  height: 52px;
  overflow: hidden;
}
html[data-design="classic"] .ds-mini-sidebar {
  width: 22px;
  padding: 5px 4px;
  display: flex;
  flex-direction: column;
  gap: 3px;
  flex-shrink: 0;
}
html[data-design="classic"] .ds-mini-item { height: 3px; border-radius: 2px; }
html[data-design="classic"] .ds-mini-main { flex: 1; display: flex; flex-direction: column; }
html[data-design="classic"] .ds-mini-topbar { height: 10px; flex-shrink: 0; }
html[data-design="classic"] .ds-mini-content {
  flex: 1;
  display: flex;
  gap: 3px;
  padding: 3px;
}
html[data-design="classic"] .ds-mini-card { flex: 1; border-radius: 3px; }

/* Card info */
html[data-design="classic"] .ds-card-info {
  padding: 6px 8px;
  background: var(--bg-card, #fff);
}
html[data-design="classic"][data-theme="dark"] .ds-card-info { background: rgba(255,255,255,0.03); }
html[data-design="classic"] .ds-card-name {
  font-size: 11px; font-weight: 700;
  color: var(--gray-800, var(--gray-800));
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
html[data-design="classic"][data-theme="dark"] .ds-card-name { color: rgba(255,255,255,0.85); }
html[data-design="classic"] .ds-card-cat {
  font-size: 9px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.06em;
  color: var(--gray-400, var(--gray-400));
  margin-top: 1px;
}

/* Active badge */
html[data-design="classic"] .ds-active-badge {
  position: absolute; top: 6px; right: 6px;
  background: var(--brand-500, var(--brand-500));
  color: #fff;
  font-size: 9px; font-weight: 700;
  padding: 2px 6px;
  border-radius: var(--radius-full);
}
/* Delete button (custom designs) */
html[data-design="classic"] .ds-delete-btn {
  position: absolute; bottom: 34px; right: 6px;
  background: var(--danger); color: #fff;
  border: none; border-radius: var(--radius-full);
  font-size: 9px; font-weight: 700;
  width: 16px; height: 16px;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer; opacity: 0; transition: opacity 0.13s;
}
html[data-design="classic"] .ds-card:hover .ds-delete-btn { opacity: 1; }

/*  Custom Design Builder  */
