  padding: 16px;
  max-height: 560px;
  overflow-y: auto;
  scrollbar-width: thin;
}
html[data-design="classic"] .ds-custom-title {
  font-size: 14px; font-weight: 800;
  color: var(--gray-800, var(--gray-800));
