html[data-design="classic"] .ds-lp-topbar { height: 18px; display: flex; align-items: center; gap: 4px; padding: 0 6px; }

/* Grid of color pickers */
html[data-design="classic"] .ds-custom-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-bottom: 16px;
}
