/* === ROADMAP + RAID + BUDGET ================================ */
html[data-design="classic"] .roadmap-wrap { background:var(--bg-card); border:1px solid var(--border); border-radius:var(--radius-lg); overflow:hidden; }
html[data-design="classic"] .roadmap-header-title { font-size:14px; font-weight:800; color:var(--gray-700); padding:14px 16px; border-bottom:1px solid var(--border); }
html[data-design="classic"] .roadmap-months { display:flex; border-bottom:1px solid var(--border); background:var(--gray-50); }
html[data-design="classic"] .roadmap-month  { flex:1; text-align:center; font-size:11px; font-weight:600; color:var(--gray-500); padding:6px 0; border-right:1px solid var(--border); }
html[data-design="classic"] .roadmap-month:last-child { border-right:none; }
html[data-design="classic"] .roadmap-today-wrap { position:relative; height:0; }
html[data-design="classic"] .roadmap-today-line { position:absolute; top:0; width:2px; height:9999px; background:var(--danger); opacity:0.4; z-index:1; pointer-events:none; }
html[data-design="classic"] .roadmap-rows { padding:8px 0; }
html[data-design="classic"] .roadmap-row  { display:flex; align-items:center; gap:0; min-height:36px; border-bottom:1px solid var(--border); }
html[data-design="classic"] .roadmap-row:last-child { border-bottom:none; }
html[data-design="classic"] .roadmap-row-label { width:160px; flex-shrink:0; font-size:12px; font-weight:600; color:var(--gray-600); padding:0 12px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
html[data-design="classic"] .roadmap-row-track { flex:1; position:relative; height:28px; background:var(--gray-50); border-left:1px solid var(--border); }
html[data-design="classic"] .roadmap-bar { position:absolute; height:22px; top:3px; border-radius:4px; display:flex; align-items:center; min-width:20px; transition:opacity .15s; }
html[data-design="classic"] .roadmap-bar:hover { opacity:0.8; }
html[data-design="classic"] .roadmap-bar-label { font-size:10px; font-weight:700; color:#fff; padding:0 6px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }

/* RAID */
html[data-design="classic"] .raid-panel { background:var(--bg-card); border:1px solid var(--border); border-radius:var(--radius-lg); padding:18px; }
html[data-design="classic"] .raid-panel-header { display:flex; justify-content:space-between; align-items:flex-start; gap:10px; flex-wrap:wrap; margin-bottom:14px; }
html[data-design="classic"] .raid-panel-title  { font-size:14px; font-weight:800; color:var(--gray-700); }
html[data-design="classic"] .raid-type-filter  { padding:4px 10px; border:1px solid var(--border); border-radius: var(--radius-full); font-size:11px; font-weight:600; background:none; color:var(--gray-500); cursor:pointer; transition:all .15s; }
html[data-design="classic"] .raid-type-filter.active { background:rgba(99,102,241,0.08); }
html[data-design="classic"] .raid-form { background:var(--gray-50); border:1px solid var(--border); border-radius:var(--radius-sm); padding:14px; margin-bottom:14px; display:flex; flex-direction:column; gap:10px; }
html[data-design="classic"] .raid-table { display:flex; flex-direction:column; gap:0; }
html[data-design="classic"] .raid-table-header { display:grid; grid-template-columns:120px 1fr 100px 80px 100px 1fr 70px; gap:8px; padding:8px 10px; background:var(--gray-50); border-bottom:1px solid var(--border); font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:.08em; color:var(--gray-400); }
html[data-design="classic"] .raid-table-row    { display:grid; grid-template-columns:120px 1fr 100px 80px 100px 1fr 70px; gap:8px; padding:10px; border-bottom:1px solid var(--border); align-items:start; font-size:12px; }
html[data-design="classic"] .raid-table-row:last-child { border-bottom:none; }
html[data-design="classic"] .raid-table-row:hover { background:var(--gray-50); }
html[data-design="classic"] .raid-type-badge   { padding:2px 7px; border-radius: var(--radius-full); font-size:10px; font-weight:700; white-space:nowrap; }
html[data-design="classic"] .raid-entry-title  { min-width:0; }
html[data-design="classic"] .raid-title-text   { font-weight:700; color:var(--gray-700); }
html[data-design="classic"] .raid-title-desc   { font-size:11px; color:var(--gray-400); margin-top:2px; }
html[data-design="classic"] .raid-owner        { font-size:11px; color:var(--gray-500); }
html[data-design="classic"] .raid-impact-badge { font-weight:700; }
html[data-design="classic"] .raid-status-badge { font-weight:700; font-size:11px; }
html[data-design="classic"] .raid-mitigation   { font-size:11px; color:var(--gray-500); }
html[data-design="classic"] .raid-empty        { padding:20px; text-align:center; font-size:12px; color:var(--gray-400); }

/* Budget */
html[data-design="classic"] .budget-summary    { display:grid; grid-template-columns:repeat(4,1fr); gap:10px; margin-bottom:12px; }
html[data-design="classic"] .budget-stat       { text-align:center; padding:12px; background:var(--gray-50); border:1px solid var(--border); border-radius:var(--radius-md); }
html[data-design="classic"] .budget-stat-num   { font-size:20px; font-weight:800; color:var(--gray-800); }
html[data-design="classic"] .budget-stat-label { font-size:11px; color:var(--gray-400); margin-top:2px; }
html[data-design="classic"] .budget-burn-bar   { height:8px; background:var(--gray-100); border-radius: var(--radius-full); overflow:hidden; margin-bottom:12px; }
html[data-design="classic"] .budget-burn-fill  { height:100%; border-radius: var(--radius-full); transition:width .4s; }
html[data-design="classic"] .budget-actions    { display:flex; gap:8px; align-items:center; margin-bottom:12px; flex-wrap:wrap; }
html[data-design="classic"] .budget-expense-form { background:var(--gray-50); border:1px solid var(--border); border-radius:var(--radius-sm); padding:12px; margin-bottom:12px; }
html[data-design="classic"] .budget-expenses   { display:flex; flex-direction:column; gap:0; }
html[data-design="classic"] .budget-expense-row { display:flex; align-items:center; gap:10px; padding:8px 0; border-bottom:1px solid var(--border); font-size:12px; }
html[data-design="classic"] .budget-expense-row:last-child { border-bottom:none; }
html[data-design="classic"] .budget-expense-cat    { font-size:10px; font-weight:700; padding:2px 6px; background:rgba(99,102,241,0.1); color:var(--brand-500); border-radius: var(--radius-full); flex-shrink:0; }
html[data-design="classic"] .budget-expense-desc   { flex:1; color:var(--gray-700); }
html[data-design="classic"] .budget-expense-amount { font-weight:700; color:var(--gray-700); min-width:70px; text-align:right; }
html[data-design="classic"] .budget-expense-date   { font-size:11px; color:var(--gray-400); min-width:80px; }
html[data-design="classic"] .budget-empty { padding:16px; text-align:center; font-size:12px; color:var(--gray-400); }

/* Goal alignment map */
html[data-design="classic"] .alignment-map-wrap    { background:var(--bg-card); border:1px solid var(--border); border-radius:var(--radius-lg); overflow:hidden; }
html[data-design="classic"] .alignment-map-controls { display:flex; align-items:center; gap:8px; padding:10px 14px; background:var(--gray-50); border-bottom:1px solid var(--border); }
html[data-design="classic"] .alignment-map-hint    { font-size:11px; color:var(--gray-400); margin-left:8px; }
html[data-design="classic"] .alignment-map-canvas  { overflow:hidden; min-height:300px; user-select:none; }

/* Report builder */
html[data-design="classic"] .report-builder        { background:var(--bg-card); border:1px solid var(--border); border-radius:var(--radius-lg); padding:20px; margin-bottom:20px; }
html[data-design="classic"] .report-builder-title  { font-size:14px; font-weight:800; color:var(--gray-700); margin-bottom:16px; }
html[data-design="classic"] .report-metrics-grid   { display:flex; flex-wrap:wrap; gap:8px; }
html[data-design="classic"] .report-metric-chip    { display:inline-flex; align-items:center; gap:6px; padding:6px 12px; border:1.5px solid var(--border); border-radius: var(--radius-full); font-size:12px; font-weight:600; color:var(--gray-600); cursor:pointer; transition:all .15s; }
html[data-design="classic"] .report-metric-chip input { display:none; }
html[data-design="classic"] .report-metric-chip.active { border-color:var(--brand-500); background:rgba(99,102,241,0.08); color:var(--brand-500); }
html[data-design="classic"] .report-metric-type    { font-size:9px; font-weight:700; padding:1px 5px; background:var(--gray-100); border-radius:3px; color:var(--gray-400); }
html[data-design="classic"] .report-schedule-note  { font-size:12px; color:var(--gray-500); margin-top:6px; }
html[data-design="classic"] .report-builder-preview { margin-top:16px; padding:14px; background:var(--gray-50); border:1px dashed var(--border); border-radius:var(--radius-sm); }
html[data-design="classic"] .report-builder-preview-title { font-size:13px; font-weight:700; color:var(--gray-700); margin-bottom:6px; }
html[data-design="classic"] .report-preview-note { font-size:12px; color:var(--gray-400); }


/* ── src/styles/velocity.css ── */
/* === SPRINT VELOCITY + CYCLE TIME ========================== */
html[data-design="classic"] .velocity-chart-card   { background:var(--bg-card); border:1px solid var(--border); border-radius:var(--radius-lg); padding:18px; margin-bottom:16px; }
html[data-design="classic"] .velocity-chart-header { display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:16px; }
html[data-design="classic"] .velocity-chart-title  { font-size:14px; font-weight:800; color:var(--gray-700); }
html[data-design="classic"] .velocity-chart-sub    { font-size:12px; color:var(--gray-400); margin-top:2px; }
html[data-design="classic"] .velocity-bars         { display:flex; gap:8px; align-items:flex-end; height:120px; padding-bottom:24px; position:relative; }
html[data-design="classic"] .velocity-bar-group    { display:flex; flex-direction:column; align-items:center; gap:3px; flex:1; height:100%; position:relative; }
html[data-design="classic"] .velocity-bar-track    { flex:1; width:100%; position:relative; display:flex; align-items:flex-end; }
html[data-design="classic"] .velocity-bar-total    { width:100%; background:var(--gray-100); border-radius:4px 4px 0 0; position:absolute; bottom:0; transition:height .4s; }
html[data-design="classic"] .velocity-bar-done     { width:100%; background:var(--brand-500); border-radius:4px 4px 0 0; position:absolute; bottom:0; z-index:1; transition:height .4s; }
html[data-design="classic"] .velocity-avg-line     { position:absolute; left:0; right:0; height:2px; background:var(--danger); border-top:2px dashed var(--danger); z-index:2; }
html[data-design="classic"] .velocity-bar-label    { font-size:9px; color:var(--gray-400); text-align:center; font-weight:600; position:absolute; bottom:-18px; white-space:nowrap; }
html[data-design="classic"] .velocity-bar-num      { font-size:11px; font-weight:800; color:var(--brand-500); position:absolute; bottom:-34px; }
html[data-design="classic"] .velocity-completion   { font-size:9px; font-weight:700; position:absolute; bottom:-46px; }
html[data-design="classic"] .cycle-time-bar        { display:flex; align-items:center; gap:6px; padding:10px 0 0; border-top:1px solid var(--border); margin-top:12px; font-size:12px; flex-wrap:wrap; }
html[data-design="classic"] .cycle-time-label      { color:var(--gray-500); }
html[data-design="classic"] .cycle-time-value      { font-weight:800; color:var(--brand-500); }


/* ── src/styles/portfolioplus.css ── */
/* === PORTFOLIO+ (Releases, Initiatives, Changes, Programmes) === */
html[data-design="classic"] .pplus-toolbar { display:flex; justify-content:space-between; align-items:center; margin-bottom:16px; flex-wrap:wrap; gap:8px; }
html[data-design="classic"] .pplus-table   { background:var(--bg-card); border:1px solid var(--border); border-radius:var(--radius-lg); overflow:hidden; }
html[data-design="classic"] .pplus-table-head { display:grid; grid-template-columns:100px 1fr 120px 100px 110px 120px 90px; gap:10px; padding:10px 14px; background:var(--gray-50); border-bottom:1px solid var(--border); font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:.08em; color:var(--gray-400); }
html[data-design="classic"] .pplus-table-row  { display:grid; grid-template-columns:100px 1fr 120px 100px 110px 120px 90px; gap:10px; padding:12px 14px; border-bottom:1px solid var(--border); align-items:start; font-size:12px; }
html[data-design="classic"] .pplus-table-row:last-child { border-bottom:none; }
html[data-design="classic"] .pplus-table-row:hover { background:var(--gray-50); }
html[data-design="classic"] .pplus-version-chip { font-family:monospace; font-size:12px; font-weight:700; color:var(--brand-500); background:rgba(99,102,241,0.1); padding:2px 8px; border-radius:4px; white-space:nowrap; }
html[data-design="classic"] .pplus-row-title { font-weight:700; color:var(--gray-700); margin-bottom:2px; }
html[data-design="classic"] .pplus-row-meta  { font-size:11px; color:var(--gray-400); }
html[data-design="classic"] .pplus-status-chip { font-size:10px; font-weight:700; padding:2px 8px; border-radius: var(--radius-full); white-space:nowrap; }
html[data-design="classic"] .pplus-priority-chip { font-size:10px; font-weight:700; padding:2px 6px; border-radius: var(--radius-full); background:var(--gray-100); }
html[data-design="classic"] .pplus-empty { padding:24px; text-align:center; font-size:12px; color:var(--gray-400); }

/* Initiatives */
html[data-design="classic"] .pplus-initiative-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(300px,1fr)); gap:14px; }
html[data-design="classic"] .pplus-initiative-card { background:var(--bg-card); border:1px solid var(--border); border-radius:var(--radius-lg); padding:16px; display:flex; flex-direction:column; gap:10px; }
html[data-design="classic"] .pplus-initiative-header { display:flex; justify-content:space-between; align-items:flex-start; gap:8px; }
html[data-design="classic"] .pplus-initiative-name   { font-size:14px; font-weight:800; color:var(--gray-800); margin-bottom:3px; }
html[data-design="classic"] .pplus-initiative-meta   { display:flex; gap:6px; flex-wrap:wrap; align-items:center; font-size:11px; color:var(--gray-400); }
html[data-design="classic"] .pplus-initiative-desc   { font-size:12px; color:var(--gray-600); line-height:1.5; }
html[data-design="classic"] .pplus-initiative-rationale { font-size:11px; color:var(--purple); background:rgba(139,92,246,0.08); padding:6px 10px; border-radius:var(--radius-sm); font-style:italic; }
html[data-design="classic"] .pplus-initiative-links { display:flex; gap:6px; flex-wrap:wrap; }
html[data-design="classic"] .pplus-link-chip { font-size:10px; font-weight:600; padding:2px 8px; background:var(--gray-100); border-radius: var(--radius-full); color:var(--gray-500); }
html[data-design="classic"] .pplus-progress-bar  { flex:1; height:6px; background:var(--gray-100); border-radius: var(--radius-full); overflow:hidden; }
html[data-design="classic"] .pplus-progress-fill { height:100%; background:var(--brand-500); border-radius: var(--radius-full); transition:width .4s; }
html[data-design="classic"] .pplus-initiative-progress { display:flex; flex-direction:column; gap:4px; }
html[data-design="classic"] .pplus-multi-select { display:flex; flex-wrap:wrap; gap:6px; }
html[data-design="classic"] .pplus-multi-chip { display:inline-flex; align-items:center; gap:5px; padding:4px 10px; border:1px solid var(--border); border-radius: var(--radius-full); font-size:11px; font-weight:600; color:var(--gray-600); cursor:pointer; }
html[data-design="classic"] .pplus-multi-chip input { display:none; }
html[data-design="classic"] .pplus-multi-chip.active { border-color:var(--brand-500); background:rgba(99,102,241,0.08); color:var(--brand-500); }

/* Programmes */
html[data-design="classic"] .pplus-programme-list { display:flex; flex-direction:column; gap:12px; }
html[data-design="classic"] .pplus-programme-card { background:var(--bg-card); border:1px solid var(--border); border-radius:var(--radius-lg); padding:16px; }
html[data-design="classic"] .pplus-programme-header { display:flex; justify-content:space-between; align-items:flex-start; gap:10px; margin-bottom:10px; }
html[data-design="classic"] .pplus-programme-left { flex:1; }
html[data-design="classic"] .pplus-milestone-count { font-size:11px; font-weight:700; color:var(--gray-500); }
html[data-design="classic"] .pplus-prog-bar-wrap { display:flex; align-items:center; gap:8px; margin-bottom:8px; }
html[data-design="classic"] .pplus-milestone-panel { border-top:1px solid var(--border); margin-top:10px; padding-top:10px; }
html[data-design="classic"] .pplus-milestone-list  { display:flex; flex-direction:column; gap:6px; margin-bottom:10px; }
html[data-design="classic"] .pplus-milestone-row   { display:flex; align-items:center; gap:8px; font-size:12px; }
html[data-design="classic"] .pplus-milestone-row input { accent-color:var(--brand-500); cursor:pointer; }
html[data-design="classic"] .pplus-milestone-title { flex:1; color:var(--gray-700); }
html[data-design="classic"] .pplus-milestone-title.done { text-decoration:line-through; color:var(--gray-400); }
html[data-design="classic"] .pplus-milestone-date  { font-size:11px; color:var(--gray-400); }
html[data-design="classic"] .pplus-milestone-owner { font-size:11px; color:var(--gray-400); }
html[data-design="classic"] .pplus-milestone-add   { display:flex; gap:6px; flex-wrap:wrap; }
html[data-design="classic"] .pplus-milestone-add input { flex:1; min-width:120px; }


/* ── src/styles/sprint-extra.css ── */
/* === SPRINT EXTRA (burnup, predictability, SAFe, grooming) == */
html[data-design="classic"] .sprint-page-tabs  { display:flex; gap:6px; margin-bottom:16px; }
html[data-design="classic"] .sprint-burnup-card, html[data-design="classic"] .sprint-predict-card, html[data-design="classic"] .pi-panel, html[data-design="classic"] .grooming-panel {
  background:var(--bg-card); border:1px solid var(--border); border-radius:var(--radius-lg); padding:18px; margin-bottom:14px;
}
html[data-design="classic"] .sprint-chart-title { font-size:14px; font-weight:800; color:var(--gray-700); margin-bottom:10px; }
html[data-design="classic"] .sprint-chart-empty { font-size:12px; color:var(--gray-400); padding:20px; text-align:center; }
html[data-design="classic"] .sprint-chart-legend { display:flex; align-items:center; gap:8px; font-size:11px; color:var(--gray-500); margin-bottom:10px; }
html[data-design="classic"] .sprint-legend-dot   { width:10px; height:10px; border-radius:50%; display:inline-block; }

/* Burnup */
html[data-design="classic"] .sprint-burnup-bars  { display:flex; gap:4px; align-items:flex-end; height:100px; margin-bottom:10px; }
html[data-design="classic"] .sprint-burnup-col   { flex:1; display:flex; flex-direction:column; align-items:center; gap:2px; height:100%; }
html[data-design="classic"] .sprint-burnup-track { flex:1; width:100%; position:relative; display:flex; align-items:flex-end; }
html[data-design="classic"] .sprint-burnup-scope { position:absolute; bottom:0; width:100%; background:var(--gray-100); border-radius:4px 4px 0 0; }
html[data-design="classic"] .sprint-burnup-done  { position:absolute; bottom:0; width:70%; left:15%; border-radius:4px 4px 0 0; z-index:1; transition:height .4s; }
html[data-design="classic"] .sprint-burnup-label { font-size:9px; color:var(--gray-400); }
html[data-design="classic"] .sprint-burnup-stats { display:flex; gap:16px; font-size:12px; color:var(--gray-500); border-top:1px solid var(--border); padding-top:8px; }

/* Predictability */
html[data-design="classic"] .sprint-predict-score { font-size:36px; font-weight:900; display:flex; align-items:baseline; gap:8px; margin:10px 0; }
html[data-design="classic"] .sprint-predict-label { font-size:13px; font-weight:600; color:var(--gray-500); }
html[data-design="classic"] .sprint-predict-table { display:flex; flex-direction:column; gap:6px; }
html[data-design="classic"] .sprint-predict-row   { display:flex; align-items:center; gap:8px; }
html[data-design="classic"] .sprint-predict-name  { font-size:12px; color:var(--gray-600); min-width:100px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
html[data-design="classic"] .sprint-predict-bar-track { flex:1; height:6px; background:var(--gray-100); border-radius: var(--radius-full); overflow:hidden; }
html[data-design="classic"] .sprint-predict-bar   { height:100%; border-radius: var(--radius-full); transition:width .4s; }
html[data-design="classic"] .sprint-predict-pct   { font-size:11px; font-weight:700; min-width:35px; text-align:right; }
html[data-design="classic"] .sprint-predict-note  { font-size:11px; color:var(--gray-400); margin-top:10px; border-top:1px solid var(--border); padding-top:8px; }

/* SAFe PI Panel */
html[data-design="classic"] .pi-header       { display:flex; align-items:flex-start; justify-content:space-between; gap:10px; margin-bottom:14px; }
html[data-design="classic"] .pi-title        { font-size:14px; font-weight:800; color:var(--gray-700); }
html[data-design="classic"] .pi-subtitle     { font-size:12px; color:var(--gray-400); }
html[data-design="classic"] .pi-name-input   { font-size:14px; font-weight:700; border:none; border-bottom:2px solid var(--brand-400); background:transparent; color:var(--gray-700); padding:2px 4px; }
html[data-design="classic"] .pi-section-label { font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:.08em; color:var(--gray-400); margin-bottom:6px; }
html[data-design="classic"] .pi-goal-row     { display:flex; align-items:center; gap:8px; padding:6px 0; border-bottom:1px solid var(--border); font-size:12px; }
html[data-design="classic"] .pi-goal-text    { flex:1; color:var(--gray-700); }
html[data-design="classic"] .pi-conf-select  { font-size:11px; font-weight:700; border:none; background:transparent; cursor:pointer; }
html[data-design="classic"] .pi-add-row      { display:flex; gap:6px; margin-top:8px; }
html[data-design="classic"] .pi-add-row input { flex:1; }
html[data-design="classic"] .pi-iterations   { display:grid; grid-template-columns:repeat(auto-fill,minmax(160px,1fr)); gap:8px; }
html[data-design="classic"] .pi-iteration    { background:var(--gray-50); border:1px solid var(--border); border-radius:var(--radius-sm); padding:10px; }
html[data-design="classic"] .pi-iter-num     { font-size:10px; font-weight:700; color:var(--gray-400); margin-bottom:3px; }
html[data-design="classic"] .pi-iter-name    { font-size:12px; font-weight:700; color:var(--gray-700); margin-bottom:4px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
html[data-design="classic"] .pi-iter-pts     { font-size:11px; color:var(--gray-500); margin-bottom:4px; }
html[data-design="classic"] .pi-iter-bar     { height:4px; background:var(--gray-100); border-radius: var(--radius-full); overflow:hidden; }
html[data-design="classic"] .pi-iter-fill    { height:100%; background:var(--brand-500); border-radius: var(--radius-full); }

/* Grooming */
html[data-design="classic"] .grooming-header     { display:flex; justify-content:space-between; align-items:center; margin-bottom:10px; flex-wrap:wrap; gap:6px; }
html[data-design="classic"] .grooming-selected-badge { font-size:11px; font-weight:700; color:var(--brand-500); background:rgba(99,102,241,0.1); padding:2px 8px; border-radius: var(--radius-full); }
html[data-design="classic"] .grooming-bulk-bar   { display:flex; align-items:center; gap:8px; flex-wrap:wrap; padding:10px 12px; background:rgba(99,102,241,0.05); border:1px solid rgba(99,102,241,0.2); border-radius:var(--radius-sm); margin-bottom:10px; }
html[data-design="classic"] .grooming-bulk-label { font-size:12px; font-weight:600; color:var(--gray-600); }
html[data-design="classic"] .grooming-fib-row    { display:flex; gap:4px; }
html[data-design="classic"] .grooming-fib-btn    { padding:3px 8px; border:1px solid var(--border); border-radius:4px; font-size:12px; font-weight:700; background:var(--bg-card); color:var(--gray-600); cursor:pointer; }
html[data-design="classic"] .grooming-fib-btn.active { background:var(--brand-500); color:#fff; border-color:var(--brand-500); }
html[data-design="classic"] .grooming-priority-select { font-size:12px; padding:3px 6px; border:1px solid var(--border); border-radius:4px; }
html[data-design="classic"] .grooming-task-list  { display:flex; flex-direction:column; gap:0; }
html[data-design="classic"] .grooming-task-row   { display:flex; align-items:center; gap:10px; padding:8px 10px; border-bottom:1px solid var(--border); font-size:12px; cursor:pointer; }
html[data-design="classic"] .grooming-task-row:last-child { border-bottom:none; }
html[data-design="classic"] .grooming-task-row.selected { background:rgba(99,102,241,0.05); }
html[data-design="classic"] .grooming-task-row input { accent-color:var(--brand-500); }
html[data-design="classic"] .grooming-task-title  { flex:1; color:var(--gray-700); }
html[data-design="classic"] .grooming-priority    { font-size:10px; font-weight:700; padding:1px 6px; border-radius: var(--radius-full); }
html[data-design="classic"] .grooming-priority-high   { color:var(--danger); background:rgba(239,68,68,0.1); }
html[data-design="classic"] .grooming-priority-medium { color:var(--warning); background:rgba(245,158,11,0.1); }
html[data-design="classic"] .grooming-priority-low    { color:var(--success); background:rgba(16,185,129,0.1); }
html[data-design="classic"] .grooming-pts  { font-size:11px; color:var(--gray-400); min-width:40px; text-align:right; }


/* ── src/styles/goaldep.css ── */
/* === GOAL DEPENDENCY MAPPING ================================== */
html[data-design="classic"] .goal-dep-panel        { border-top:1px solid var(--border); padding-top:12px; margin-top:10px; }
html[data-design="classic"] .goal-dep-section-title { font-size:11px; font-weight:700; color:var(--gray-500); text-transform:uppercase; letter-spacing:.08em; display:flex; align-items:center; gap:8px; margin-bottom:10px; }
html[data-design="classic"] .goal-dep-count        { font-weight:600; color:var(--brand-500); background:rgba(99,102,241,0.1); padding:1px 7px; border-radius: var(--radius-full); font-size:10px; text-transform:none; letter-spacing:0; }
html[data-design="classic"] .goal-dep-group        { margin-bottom:10px; }
html[data-design="classic"] .goal-dep-group-label  { font-size:11px; font-weight:700; color:var(--gray-500); margin-bottom:6px; }
html[data-design="classic"] .goal-dep-row          { display:flex; align-items:center; gap:8px; padding:6px 0; border-bottom:1px solid var(--border); }
html[data-design="classic"] .goal-dep-row:last-child { border-bottom:none; }
html[data-design="classic"] .goal-dep-row-blocks   { opacity:.7; }
html[data-design="classic"] .goal-dep-conf         { width:8px; height:8px; border-radius:50%; flex-shrink:0; }
html[data-design="classic"] .goal-dep-title        { flex:1; font-size:12px; font-weight:600; color:var(--gray-700); }
html[data-design="classic"] .goal-dep-status       { font-size:10px; font-weight:700; }
html[data-design="classic"] .goal-dep-empty        { font-size:12px; color:var(--gray-400); padding:8px 0; }
html[data-design="classic"] .goal-dep-add-row      { display:flex; gap:6px; align-items:center; margin-top:8px; flex-wrap:wrap; }
html[data-design="classic"] .goal-dep-select       { flex:1; min-width:160px; }


/* ── src/styles/integrations.css ── */
/* === INTEGRATIONS ======================================== */
html[data-design="classic"] .intg-filter-bar  { display:flex; gap:6px; flex-wrap:wrap; margin-bottom:20px; }

/* Tile grid  4 cols on wide, responsive */
html[data-design="classic"] .intg-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 14px;
}

/* Individual tile */
html[data-design="classic"] .intg-tile {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  transition: box-shadow .15s, border-color .15s;
  position: relative;
  overflow: hidden;
}
html[data-design="classic"] .intg-tile::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--intg-color, var(--brand-500));
  opacity: 0;
  transition: opacity .2s;
}
html[data-design="classic"] .intg-tile:hover::before,
html[data-design="classic"] .intg-tile-active::before { opacity: 1; }
html[data-design="classic"] .intg-tile:hover { box-shadow: var(--shadow-sm); border-color: rgba(99,102,241,.2); }
html[data-design="classic"] .intg-tile-active { border-color: rgba(16,185,129,.25); }

html[data-design="classic"] .intg-tile-top     { display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:4px; }
html[data-design="classic"] .intg-tile-icon-wrap {
  width: 40px; height: 40px; border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
html[data-design="classic"] .intg-tile-icon    { font-size: 22px; line-height: 1; }
html[data-design="classic"] .intg-tile-badges  { display:flex; flex-direction:column; align-items:flex-end; gap:3px; }

html[data-design="classic"] .intg-badge-new    {
  font-size: 9px; font-weight: 800; padding: 1px 6px;
  background: rgba(99,102,241,0.12); color: var(--brand-500);
  border-radius: var(--radius-full); letter-spacing: .04em;
}
html[data-design="classic"] .intg-badge-active {
  font-size: 9px; font-weight: 700; color: var(--success);
}

html[data-design="classic"] .intg-tile-name    { font-size: 13px; font-weight: 800; color: var(--gray-800); line-height: 1.2; }
html[data-design="classic"] .intg-tile-tagline { font-size: 11px; color: var(--gray-500); line-height: 1.4; flex: 1; }
html[data-design="classic"] .intg-tile-category {
  font-size: 10px; font-weight: 700; color: var(--gray-400);
  text-transform: uppercase; letter-spacing: .06em; margin-top: 2px;
}
html[data-design="classic"] .intg-tile-lastsync { font-size: 10px; color: var(--gray-400); }

html[data-design="classic"] .intg-tile-actions { display:flex; gap:6px; margin-top:8px; align-items:center; }

/* Toggle pill */
html[data-design="classic"] .intg-toggle-btn {
  font-size: 10px; font-weight: 700; padding: 3px 8px;
  border-radius: var(--radius-full); border: 1px solid var(--border);
  background: var(--gray-100); color: var(--gray-500);
  cursor: pointer; transition: all .15s;
}
html[data-design="classic"] .intg-toggle-btn.on {
  background: rgba(16,185,129,0.12); border-color: rgba(16,185,129,.3);
  color: var(--success);
}

/* Connect / Config button */
html[data-design="classic"] .intg-config-btn {
  flex: 1; padding: 8px 0; border: none; border-radius: var(--radius-sm);
  font-size: 13px; font-weight: 700; color: #fff; cursor: pointer;
  opacity: .9; transition: opacity .15s;
  display: flex; align-items: center; justify-content: center;
  letter-spacing: 0.02em;
}
html[data-design="classic"] .intg-config-btn:hover { opacity: 1; transform: translateY(-1px); }

/* Summary chips in header */
html[data-design="classic"] .intg-summary-chips { display:flex; gap:10px; }
html[data-design="classic"] .intg-summary-chip  {
  display: flex; align-items: center; gap: 5px;
  font-size: 12px; font-weight: 600; color: var(--gray-600);
  background: var(--bg-card); border: 1px solid var(--border);
  padding: 4px 10px; border-radius: var(--radius-full);
}
html[data-design="classic"] .intg-dot          { width:7px; height:7px; border-radius:50%; }
html[data-design="classic"] .intg-dot.connected { background: var(--brand-500); }
html[data-design="classic"] .intg-dot.active    { background: var(--success); }

/* Config drawer */
html[data-design="classic"] .intg-drawer { max-width: 480px; width: 100%; }
html[data-design="classic"] .intg-drawer-header {
  display: flex; align-items: center; gap: 12px;
  margin: -20px -20px 16px; padding: 16px 20px;
  background: var(--gray-50); border-bottom: 1px solid var(--border);
}
html[data-design="classic"] .intg-drawer-icon  {
  width: 44px; height: 44px; border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  font-size: 22px; flex-shrink: 0;
}
html[data-design="classic"] .intg-drawer-title   { font-size: 16px; font-weight: 800; color: var(--gray-800); }
html[data-design="classic"] .intg-drawer-tagline { font-size: 12px; color: var(--gray-500); margin-top: 2px; }
html[data-design="classic"] .intg-drawer-fields  { display:flex; flex-direction:column; gap:10px; margin:4px 0; }
html[data-design="classic"] .intg-drawer-footer  {
  display:flex; gap:8px; justify-content:flex-end;
  border-top: 1px solid var(--border); padding-top: 14px; margin-top: 14px;
}

/* === OUTLOOK SETUP WIZARD ==================================== */
html[data-design="classic"] .intg-wizard { max-width: 520px; width: 100%; }

/* Progress dots + bar */
html[data-design="classic"] .wizard-progress {
  display: flex; align-items: center; gap: 0;
  padding: 16px 20px 0; margin: -20px -20px 0;
  position: relative;
}
html[data-design="classic"] .wizard-progress-bar {
  position: absolute; top: 50%; left: 20px; right: 20px;
  height: 2px; background: var(--gray-100); z-index: 0;
  transform: translateY(-50%);
}
html[data-design="classic"] .wizard-progress-fill { height: 100%; transition: width .4s ease; }
html[data-design="classic"] .wizard-progress-dot {
  width: 10px; height: 10px; border-radius: 50%;
  background: var(--gray-200); border: 2px solid var(--gray-200);
  z-index: 1; flex-shrink: 0; margin: 0 auto;
  transition: all .3s;
}
html[data-design="classic"] .wizard-progress-dot.active {
  background: var(--wc, #0078d4); border-color: var(--wc, #0078d4);
  box-shadow: 0 0 0 3px rgba(0,120,212,.2);
  transform: scale(1.2);
}
html[data-design="classic"] .wizard-progress-dot.done {
  background: var(--wc, #0078d4); border-color: var(--wc, #0078d4);
}

/* Header */
html[data-design="classic"] .wizard-header {
  display: flex; align-items: flex-start; gap: 12px;
  margin: 12px -20px 0; padding: 16px 20px;
  background: var(--gray-50); border-bottom: 1px solid var(--border);
}
html[data-design="classic"] .wizard-step-icon  { font-size: 26px; flex-shrink: 0; margin-top: 2px; }
html[data-design="classic"] .wizard-step-num   { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing:.06em; color: var(--gray-400); }
html[data-design="classic"] .wizard-step-title { font-size: 16px; font-weight: 800; color: var(--gray-800); margin-top: 2px; }

/* Body */
html[data-design="classic"] .wizard-body { padding: 4px 0; min-height: 180px; }

html[data-design="classic"] .wizard-intro p { font-size: 13px; color: var(--gray-600); line-height: 1.6; margin-bottom: 14px; }
html[data-design="classic"] .wizard-prereq { background: rgba(0,120,212,.06); border: 1px solid rgba(0,120,212,.15); border-radius: var(--radius-md); padding: 12px 14px; }
html[data-design="classic"] .wizard-prereq-title { font-size: 12px; font-weight: 700; color: var(--gray-700); margin-bottom: 6px; }
html[data-design="classic"] .wizard-prereq ul { margin: 0; padding-left: 16px; }
html[data-design="classic"] .wizard-prereq li { font-size: 12px; color: var(--gray-600); line-height: 1.8; }

html[data-design="classic"] .wizard-step-body { display: flex; flex-direction: column; gap: 12px; }
html[data-design="classic"] .wizard-step-desc { font-size: 13px; color: var(--gray-600); line-height: 1.5; margin: 0; }
html[data-design="classic"] .wizard-step-action { margin-bottom: 4px; }

html[data-design="classic"] .wizard-portal-btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 9px 16px; background: #0078d4; color: #fff;
  border-radius: var(--radius-sm); font-size: 13px; font-weight: 700;
  text-decoration: none; transition: opacity .15s;
}
html[data-design="classic"] .wizard-portal-btn:hover { opacity: .9; }

html[data-design="classic"] .wizard-steps-list {
  margin: 0; padding-left: 18px;
  display: flex; flex-direction: column; gap: 8px;
}
html[data-design="classic"] .wizard-steps-list li { font-size: 13px; color: var(--gray-600); line-height: 1.5; }
html[data-design="classic"] .wizard-steps-list li strong { color: var(--gray-800); }
html[data-design="classic"] .wizard-steps-list li em { font-style: normal; color: var(--gray-500); }

html[data-design="classic"] .wizard-code {
  font-family: monospace; font-size: 12px;
  background: var(--gray-100); color: var(--brand-500);
  padding: 1px 6px; border-radius: 4px;
}

html[data-design="classic"] .wizard-tip {
  font-size: 12px; color: var(--gray-500);
  background: rgba(245,158,11,.08); border: 1px solid rgba(245,158,11,.2);
  border-radius: var(--radius-sm); padding: 8px 12px;
}

html[data-design="classic"] .wizard-screenshot-hint {
  background: var(--gray-50); border: 1px solid var(--border);
  border-radius: var(--radius-md); padding: 12px; margin: 4px 0;
}
html[data-design="classic"] .wizard-screenshot-row {
  display: flex; align-items: center; gap: 8px;
  padding: 5px 0; font-size: 12px;
}
html[data-design="classic"] .wizard-screenshot-row:first-child { border-bottom: 1px solid var(--border); padding-bottom: 8px; margin-bottom: 4px; }
html[data-design="classic"] .wizard-ss-label  { font-weight: 700; color: var(--gray-700); min-width: 170px; }
html[data-design="classic"] .wizard-ss-arrow  { color: var(--gray-400); }
html[data-design="classic"] .wizard-ss-field  { color: var(--gray-500); }

html[data-design="classic"] .wizard-fields { display: flex; flex-direction: column; gap: 10px; }

html[data-design="classic"] .wizard-perms {
  display: flex; gap: 6px; flex-wrap: wrap; margin-top: 6px;
}

html[data-design="classic"] .wizard-required { color: var(--danger); font-size: 12px; }


/* ── src/styles/channels.css ── */
/* === CHANNELS + STANDUP ====================================== */
html[data-design="classic"] .channel-layout { display:grid; grid-template-columns:220px 1fr; gap:0; height:calc(100vh - 220px); min-height:500px; background:var(--bg-card); border:1px solid var(--border); border-radius:var(--radius-lg); overflow:hidden; }

/* Sidebar */
html[data-design="classic"] .channel-sidebar { border-right:1px solid var(--border); display:flex; flex-direction:column; background:var(--gray-50); }
html[data-design="classic"] .channel-sidebar-header { display:flex; align-items:center; justify-content:space-between; padding:12px 14px; border-bottom:1px solid var(--border); }
html[data-design="classic"] .channel-sidebar-title { font-size:12px; font-weight:800; text-transform:uppercase; letter-spacing:.06em; color:var(--gray-500); }
html[data-design="classic"] .channel-create-form { padding:10px; display:flex; flex-direction:column; gap:6px; background:var(--bg-card); border-bottom:1px solid var(--border); }
html[data-design="classic"] .channel-create-form input, html[data-design="classic"] .channel-create-form select { font-size:12px; }
html[data-design="classic"] .channel-list { flex:1; overflow-y:auto; padding:6px 0; }
html[data-design="classic"] .channel-list-item { display:flex; align-items:center; gap:6px; width:100%; padding:6px 14px; font-size:13px; font-weight:500; color:var(--gray-600); background:none; border:none; cursor:pointer; transition:background .1s; text-align:left; }
html[data-design="classic"] .channel-list-item:hover { background:var(--gray-100); }
html[data-design="classic"] .channel-list-item.active { background:rgba(99,102,241,.1); color:var(--brand-500); font-weight:700; }
html[data-design="classic"] .channel-list-hash { color:var(--gray-400); font-weight:700; }
html[data-design="classic"] .channel-list-name { flex:1; }
html[data-design="classic"] .channel-list-badge { font-size:12px; }
html[data-design="classic"] .channel-empty-sidebar { font-size:11px; color:var(--gray-400); padding:12px 14px; }

/* Main view */
html[data-design="classic"] .channel-main { display:flex; flex-direction:column; overflow:hidden; }
html[data-design="classic"] .channel-view { display:flex; flex-direction:column; height:100%; }
html[data-design="classic"] .channel-view-header { display:flex; align-items:center; gap:10px; padding:12px 16px; border-bottom:1px solid var(--border); background:var(--bg-card); flex-shrink:0; }
html[data-design="classic"] .channel-view-icon { font-size:18px; font-weight:700; color:var(--gray-400); }
html[data-design="classic"] .channel-view-name  { font-size:14px; font-weight:800; color:var(--gray-800); }
html[data-design="classic"] .channel-view-desc  { font-size:11px; color:var(--gray-400); }
html[data-design="classic"] .channel-view-type  { font-size:10px; font-weight:700; padding:2px 8px; background:rgba(99,102,241,.1); color:var(--brand-500); border-radius: var(--radius-full); margin-left:auto; }
html[data-design="classic"] .channel-empty { display:flex; align-items:center; justify-content:center; height:100%; font-size:13px; color:var(--gray-400); }

/* Messages */
html[data-design="classic"] .channel-messages { flex:1; overflow-y:auto; padding:12px 16px; display:flex; flex-direction:column; gap:0; }
html[data-design="classic"] .channel-msg { display:flex; gap:10px; padding:3px 0; }
html[data-design="classic"] .channel-msg:hover { background:var(--gray-50); border-radius:var(--radius-sm); }
html[data-design="classic"] .channel-msg-cont { padding:1px 0; }
html[data-design="classic"] .channel-msg-avatar { width:32px; height:32px; border-radius:50%; background:linear-gradient(135deg,var(--brand-500),var(--purple)); color:#fff; display:flex; align-items:center; justify-content:center; font-size:11px; font-weight:800; flex-shrink:0; margin-top:2px; }
html[data-design="classic"] .channel-msg-avatar-spacer { width:32px; flex-shrink:0; }
html[data-design="classic"] .channel-msg-body { flex:1; min-width:0; }
html[data-design="classic"] .channel-msg-meta { display:flex; align-items:baseline; gap:8px; margin-bottom:2px; }
html[data-design="classic"] .channel-msg-author { font-size:13px; font-weight:700; color:var(--gray-800); }
html[data-design="classic"] .channel-msg-time   { font-size:10px; color:var(--gray-400); }
html[data-design="classic"] .channel-msg-content { font-size:13px; color:var(--gray-700); line-height:1.5; word-break:break-word; }
html[data-design="classic"] .channel-msg-link { font-size:11px; color:var(--brand-500); margin-top:3px; }
html[data-design="classic"] .channel-empty { padding:40px; text-align:center; font-size:13px; color:var(--gray-400); }

/* Input bar */
html[data-design="classic"] .channel-input-bar { display:flex; gap:8px; padding:12px 16px; border-top:1px solid var(--border); background:var(--bg-card); flex-shrink:0; }
html[data-design="classic"] .channel-input { flex:1; padding:8px 12px; border:1px solid var(--border); border-radius:var(--radius-md); font-size:13px; background:var(--gray-50); transition:border-color .15s; }
html[data-design="classic"] .channel-input:focus { border-color:var(--brand-500); background:var(--bg-card); }
html[data-design="classic"] .channel-send-btn { padding:8px 14px; background:var(--brand-500); color:#fff; border:none; border-radius:var(--radius-md); font-size:16px; cursor:pointer; transition:opacity .15s; }
html[data-design="classic"] .channel-send-btn:hover { opacity:.85; }
html[data-design="classic"] .channel-send-btn:disabled { opacity:.4; cursor:not-allowed; }

/* Standup */
html[data-design="classic"] .channel-standup { display:flex; flex-direction:column; gap:16px; }
html[data-design="classic"] .channel-standup-header { display:flex; justify-content:space-between; align-items:flex-start; }
