html[data-design="classic"] .cal-btn-ghost {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  border: 1px solid transparent;
  color: var(--gray-700);
}
html[data-design="classic"] .cal-btn-ghost:hover { background: var(--gray-100); }
html[data-design="classic"] .cal-danger-text { color: var(--danger) !important; }

/* Mini month */
html[data-design="classic"] .cal-mini {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 10px;
}
html[data-design="classic"] .cal-mini-head { display: flex; align-items: center; gap: 2px; margin-bottom: 6px; }
html[data-design="classic"] .cal-mini-title { flex: 1; font-size: 13px; font-weight: 700; color: var(--gray-800); padding-left: 4px; }
html[data-design="classic"] .cal-mini-grid { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); row-gap: 2px; }
html[data-design="classic"] .cal-mini-wd {
  text-align: center;
  font-size: 10.5px;
  font-weight: 600;
  color: var(--gray-500);
  padding: 2px 0 4px;
}
html[data-design="classic"] .cal-mini-day {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 30px;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--gray-800);
  font-size: 12px;
  cursor: pointer;
}
/* The circle is a fixed square, so it stays round and centred whatever the column width. */
html[data-design="classic"] .cal-mini-num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  line-height: 1;
}
html[data-design="classic"] .cal-mini-day:hover .cal-mini-num { background: var(--gray-100); }
html[data-design="classic"] .cal-mini-out { color: var(--gray-400); }
/* Days shown in the main calendar: a soft band across the row. */
html[data-design="classic"] .cal-mini-range { background: var(--brand-50); }
html[data-design="classic"] .cal-mini-range .cal-mini-num { color: var(--brand-700); font-weight: 600; }
html[data-design="classic"] .cal-mini-selected { background: transparent; }
html[data-design="classic"] .cal-mini-selected .cal-mini-num { box-shadow: inset 0 0 0 2px var(--brand-600); background: var(--brand-50); }
html[data-design="classic"] .cal-mini-today .cal-mini-num,
html[data-design="classic"] .cal-mini-day.cal-mini-today:hover .cal-mini-num { background: var(--brand-600); color: #fff; font-weight: 700; }
html[data-design="classic"] .cal-mini-busy::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: 0;
  width: 4px;
  height: 4px;
  margin-left: -2px;
  border-radius: 50%;
  background: var(--brand-500);
}

/* Layers ("My calendars") */
html[data-design="classic"] .cal-layers {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 10px 12px;
}
html[data-design="classic"] .cal-layers-title { font-size: 12px; font-weight: 700; color: var(--gray-700); margin-bottom: 6px; }
html[data-design="classic"] .cal-layer {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 2px;
  font-size: 13px;
  color: var(--gray-800);
  cursor: pointer;
}
html[data-design="classic"] .cal-layer input { accent-color: var(--brand-600); margin: 0; }
html[data-design="classic"] .cal-layer-swatch { width: 10px; height: 10px; border-radius: 3px; flex-shrink: 0; }
html[data-design="classic"] .cal-layer-name { flex: 1; }
html[data-design="classic"] .cal-layer-count { font-size: 11.5px; color: var(--gray-500); font-variant-numeric: tabular-nums; }
html[data-design="classic"] .cal-layer-off { opacity: 0.55; cursor: not-allowed; }
html[data-design="classic"] .cal-layers-note { font-size: 11.5px; color: var(--gray-500); margin: 4px 0 0; }
html[data-design="classic"] .cal-tip { font-size: 11.5px; line-height: 1.5; color: var(--gray-500); margin: 0; }

/* Main pane */
html[data-design="classic"] .cal-main {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
}
html[data-design="classic"] .cal-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
  flex-wrap: wrap;
}
html[data-design="classic"] .cal-today { padding: 6px 12px; }
html[data-design="classic"] .cal-nav { display: inline-flex; }
html[data-design="classic"] .cal-title {
  flex: 1;
  min-width: 0;
  margin: 0 0 0 4px;
  font-size: 17px;
  font-weight: 700;
  color: var(--gray-800);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
html[data-design="classic"] .cal-views {
  display: inline-flex;
  padding: 2px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--gray-50);
}
html[data-design="classic"] .cal-view-btn {
  border: 0;
  background: transparent;
  padding: 5px 12px;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--gray-600);
  border-radius: var(--radius-sm);
  cursor: pointer;
  white-space: nowrap;
}
html[data-design="classic"] .cal-view-btn:hover { color: var(--gray-900); }
html[data-design="classic"] .cal-view-btn.active { background: var(--bg-card); color: var(--brand-600); box-shadow: var(--shadow-xs); }
html[data-design="classic"] .cal-views-select { display: none; }

html[data-design="classic"] .cal-grid { flex: 1; min-height: 0; padding: 0 8px 8px; user-select: none; }

/* FullCalendar inside the grid */
html[data-design="classic"] .cal-grid .fc { --fc-border-color: var(--border); --fc-page-bg-color: var(--bg-card); --fc-today-bg-color: var(--brand-50); --fc-now-indicator-color: #d64545; --fc-non-business-color: rgba(100, 116, 139, 0.06); font-size: 12.5px; }
html[data-design="classic"] .cal-grid .fc .fc-col-header-cell-cushion { padding: 8px 4px; font-weight: 600; color: var(--gray-700); text-decoration: none; }
html[data-design="classic"] .cal-grid .fc .fc-daygrid-day-number { color: var(--gray-700); text-decoration: none; font-size: 12px; }
html[data-design="classic"] .cal-grid .fc .fc-timegrid-slot-label-cushion { color: var(--gray-500); font-size: 11px; }
html[data-design="classic"] .cal-grid .fc .fc-timegrid-slot { height: 2.4em; }
html[data-design="classic"] .cal-grid .fc .fc-timegrid-slot-minor { border-top-style: dotted; }
html[data-design="classic"] .cal-grid .fc .fc-day-today .fc-col-header-cell-cushion,
html[data-design="classic"] .cal-grid .fc .fc-day-today .fc-daygrid-day-number { color: var(--brand-600); font-weight: 700; }
html[data-design="classic"] .cal-grid .fc .fc-highlight { background: rgba(91, 95, 238, 0.14); }
html[data-design="classic"] .cal-grid .fc .fc-timegrid-now-indicator-line { border-width: 2px 0 0; }

html[data-design="classic"] .cal-grid .fc .fc-event { border-radius: 4px; cursor: pointer; }
html[data-design="classic"] .cal-grid .fc .fc-timegrid-event.cal-ev-meeting { border-left: 3px solid rgba(0, 0, 0, 0.25); }
html[data-design="classic"] .cal-grid .fc .cal-ev-done { opacity: 0.6; }
html[data-design="classic"] .cal-grid .fc .cal-ev-cancelled .fc-event-title,
html[data-design="classic"] .cal-grid .fc .cal-ev-cancelled .cal-ev-title { text-decoration: line-through; }
html[data-design="classic"] .cal-grid .fc .fc-daygrid-event { padding: 1px 4px; font-size: 11.5px; }
html[data-design="classic"] .cal-ev-inner { padding: 2px 4px; overflow: hidden; line-height: 1.25; }
html[data-design="classic"] .cal-ev-title { font-weight: 600; font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
html[data-design="classic"] .cal-ev-meta { font-size: 11px; opacity: 0.92; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
html[data-design="classic"] .cal-ev-loc { display: flex; align-items: center; gap: 3px; }

/* Peek card */
html[data-design="classic"] .cal-peek {
  position: fixed;
  z-index: 1200;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  padding: 0 16px 12px;
  overflow: hidden auto;
  max-height: calc(100vh - 16px);
  outline: none;
}
html[data-design="classic"] .cal-peek-sheet {
  left: 0;
  right: 0;
  bottom: 0;
  border-radius: 14px 14px 0 0;
  max-height: 75vh;
}
html[data-design="classic"] .cal-peek-bar { height: 4px; margin: 0 -16px 8px; }
html[data-design="classic"] .cal-peek-head { display: flex; align-items: center; gap: 8px; }
html[data-design="classic"] .cal-peek-kind { flex: 1; display: flex; align-items: center; gap: 8px; font-size: 11.5px; font-weight: 600; color: var(--gray-500); text-transform: uppercase; letter-spacing: 0.04em; }
html[data-design="classic"] .cal-peek-actions { display: flex; gap: 2px; }
html[data-design="classic"] .cal-peek-status { font-size: 10.5px; padding: 1px 7px; border-radius: 999px; background: var(--gray-100); color: var(--gray-700); text-transform: capitalize; letter-spacing: 0; }
html[data-design="classic"] .cal-peek-status-cancelled { background: rgba(214, 69, 69, 0.12); color: var(--danger); }
html[data-design="classic"] .cal-peek-status-completed { background: rgba(30, 142, 90, 0.12); color: var(--success); }
html[data-design="classic"] .cal-peek-title { margin: 4px 0 10px; font-size: 17px; font-weight: 700; color: var(--gray-900); line-height: 1.3; overflow-wrap: anywhere; }
html[data-design="classic"] .cal-strike { text-decoration: line-through; }
html[data-design="classic"] .cal-peek-line { display: flex; align-items: center; gap: 10px; font-size: 13px; color: var(--gray-700); margin: 6px 0; }
html[data-design="classic"] .cal-peek-line > svg { flex-shrink: 0; color: var(--gray-500); }
html[data-design="classic"] .cal-peek-top { align-items: flex-start; }
html[data-design="classic"] .cal-peek-top > svg { margin-top: 2px; }
html[data-design="classic"] .cal-peek-loc { overflow-wrap: anywhere; }
html[data-design="classic"] .cal-peek-sub { font-size: 12px; color: var(--gray-500); }
html[data-design="classic"] .cal-peek-people { list-style: none; margin: 2px 0 0; padding: 0; display: grid; gap: 2px; }
html[data-design="classic"] .cal-peek-agenda { margin: 0; white-space: pre-wrap; font-size: 12.5px; color: var(--gray-600); overflow-wrap: anywhere; }
html[data-design="classic"] .cal-peek-join { display: inline-flex; align-items: center; gap: 6px; margin: 6px 0 4px 24px; text-decoration: none; }
html[data-design="classic"] .cal-peek-foot { display: flex; justify-content: flex-end; border-top: 1px solid var(--border); margin-top: 10px; padding-top: 8px; }

/* Editor */
html[data-design="classic"] .cal-ed-overlay {
  position: fixed;
  inset: 0;
  z-index: 1300;
  background: rgba(15, 23, 42, 0.45);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 6vh 16px 16px;
  overflow-y: auto;
}
html[data-design="classic"] .cal-ed {
  width: 100%;
  max-width: 640px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl, 14px);
  box-shadow: var(--shadow-xl);
  display: flex;
  flex-direction: column;
}
html[data-design="classic"] .cal-ed-head { display: flex; align-items: center; justify-content: space-between; padding: 14px 18px 4px; }
html[data-design="classic"] .cal-ed-head h2 { margin: 0; font-size: 15px; font-weight: 700; color: var(--gray-800); }
html[data-design="classic"] .cal-ed-body { padding: 4px 18px 8px; }
html[data-design="classic"] .cal-ed-title {
  width: 100%;
  border: 0;
  border-bottom: 2px solid var(--border);
  background: transparent;
  font-size: 20px;
  font-weight: 600;
  color: var(--gray-900);
  padding: 8px 2px;
  margin-bottom: 8px;
  border-radius: 0;
}
html[data-design="classic"] .cal-ed-title:focus { outline: none; border-bottom-color: var(--brand-500); }
html[data-design="classic"] .cal-ed-row { display: flex; align-items: center; gap: 12px; padding: 8px 0; }
html[data-design="classic"] .cal-ed-row-top { align-items: flex-start; }
html[data-design="classic"] .cal-ed-row-top .cal-ed-icon { margin-top: 9px; }
html[data-design="classic"] .cal-ed-icon { flex-shrink: 0; color: var(--gray-500); }
html[data-design="classic"] .cal-ed-field { flex: 1; min-width: 0; }
html[data-design="classic"] .cal-ed-input,
html[data-design="classic"] .cal-ed select,
html[data-design="classic"] .cal-ed input[type="date"] {
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-input);
  color: var(--gray-900);
  padding: 7px 9px;
  font-size: 13px;
}
html[data-design="classic"] .cal-ed-input { width: 100%; }
html[data-design="classic"] .cal-ed-agenda { resize: vertical; min-height: 96px; font-family: inherit; }
html[data-design="classic"] .cal-ed-when { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
html[data-design="classic"] .cal-ed-time { min-width: 104px; }
html[data-design="classic"] .cal-ed-to { font-size: 12.5px; color: var(--gray-500); }
html[data-design="classic"] .cal-ed-dur { font-size: 12px; color: var(--gray-500); margin-left: 4px; }
html[data-design="classic"] .cal-ed-warn,
html[data-design="classic"] .cal-ed-conflict { display: flex; align-items: center; gap: 6px; margin-top: 6px; font-size: 12.5px; }
html[data-design="classic"] .cal-ed-warn { color: var(--danger); }
html[data-design="classic"] .cal-ed-conflict { color: var(--warning); }
html[data-design="classic"] .cal-ed-hint { display: flex; align-items: center; gap: 5px; margin-top: 5px; font-size: 12px; color: var(--success); }
html[data-design="classic"] .cal-ed-two { display: flex; gap: 12px; flex-wrap: wrap; }
html[data-design="classic"] .cal-ed-proj { display: flex; align-items: center; gap: 8px; flex: 1; min-width: 180px; }
html[data-design="classic"] .cal-ed-proj select { flex: 1; min-width: 0; }
html[data-design="classic"] .cal-ed-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-input);
  padding: 5px 6px;
}
html[data-design="classic"] .cal-ed-chips:focus-within { border-color: var(--brand-500); }
html[data-design="classic"] .cal-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: 100%;
  padding: 2px 4px 2px 9px;
  border-radius: 999px;
  background: var(--brand-50);
  color: var(--brand-700);
  font-size: 12.5px;
}
html[data-design="classic"] .cal-chip button { display: inline-flex; border: 0; background: transparent; color: inherit; cursor: pointer; padding: 2px; border-radius: 50%; }
html[data-design="classic"] .cal-chip button:hover { background: rgba(91, 95, 238, 0.18); }
html[data-design="classic"] .cal-ed-chip-input { flex: 1; min-width: 140px; border: 0 !important; background: transparent !important; padding: 3px !important; font-size: 13px; color: var(--gray-900); }
html[data-design="classic"] .cal-ed-chip-input:focus { outline: none; }
html[data-design="classic"] .cal-ed-error { margin-top: 6px; padding: 8px 10px; border-radius: var(--radius-sm); background: rgba(214, 69, 69, 0.1); color: var(--danger); font-size: 12.5px; }
html[data-design="classic"] .cal-ed-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 12px 18px;
  border-top: 1px solid var(--border);
  flex-wrap: wrap;
}
html[data-design="classic"] .cal-ed-foot-left,
html[data-design="classic"] .cal-ed-foot-right { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
html[data-design="classic"] .cal-ed-foot-right { margin-left: auto; }
html[data-design="classic"] .cal-ed-kbd { font-size: 11px; color: var(--gray-400); }

/* Tablet: hide the left pane */
@media (max-width: 1024px) {
  html[data-design="classic"] .cal-page { grid-template-columns: minmax(0, 1fr); }
  html[data-design="classic"] .cal-side { display: none; }
  html[data-design="classic"] .cal-new-compact { display: inline-flex; }
}

/* Phone */
@media (max-width: 640px) {
  html[data-design="classic"] .cal-page { height: calc(100vh - 140px); min-height: 480px; }
  html[data-design="classic"] .cal-toolbar { padding: 8px; gap: 6px; }
  html[data-design="classic"] .cal-title { order: 10; flex-basis: 100%; margin: 2px 0 0; font-size: 15px; }
  html[data-design="classic"] .cal-views { display: none; }
  html[data-design="classic"] .cal-views-select { display: block; margin-left: auto; padding: 6px 8px; border: 1px solid var(--border); border-radius: var(--radius-sm); background: var(--bg-input); color: var(--gray-800); font-size: 13px; }
  html[data-design="classic"] .cal-grid { padding: 0 2px 2px; }
  html[data-design="classic"] .cal-ed-overlay { padding: 0; align-items: stretch; }
  html[data-design="classic"] .cal-ed { max-width: none; border-radius: 0; min-height: 100%; }
  html[data-design="classic"] .cal-ed-kbd { display: none; }
  html[data-design="classic"] .cal-ed-time { min-width: 92px; }
}

/* The app's global button/input rules (padding, width:100%, display:block)
   are meant for forms; undo them for the calendar's compact controls. */
html[data-design="classic"] .cal-icon-btn,
html[data-design="classic"] .cal-mini-day,
html[data-design="classic"] .cal-chip button { padding: 0; min-width: 0; min-height: 0; margin: 0; }
html[data-design="classic"] .cal-icon-btn svg,
html[data-design="classic"] .cal-btn-ghost svg,
html[data-design="classic"] .cal-new svg { flex-shrink: 0; }
html[data-design="classic"] .cal-mini-grid { grid-template-columns: repeat(7, minmax(0, 1fr)); }
html[data-design="classic"] .cal-mini-day { width: 100%; }
html[data-design="classic"] .cal-layer input[type="checkbox"] { width: auto; display: inline-block; flex: none; margin: 0; }
html[data-design="classic"] .cal-ed-when input,
html[data-design="classic"] .cal-ed-when select,
html[data-design="classic"] .cal-ed-two select { width: auto; display: inline-block; margin: 0; }
html[data-design="classic"] .cal-ed-proj select { width: auto; flex: 1; }
html[data-design="classic"] .cal-ed-title,
html[data-design="classic"] .cal-ed-input,
html[data-design="classic"] .cal-ed-chip-input { margin-top: 0; margin-bottom: 0; }
html[data-design="classic"] .cal-ed-chip-input { width: auto; display: inline-block; }
html[data-design="classic"] .cal-view-btn { min-width: 0; margin: 0; }

/* ── Scheduling assistant ──────────────────────────────────────── */
html[data-design="classic"] .cal-ed.cal-ed-wide { max-width: 1000px; }
html[data-design="classic"] .cal-ed-assist-btn {
  display: inline-flex; align-items: center; gap: 5px; margin: 0 0 0 auto; padding: 5px 10px; min-width: 0;
  font-size: 12px; font-weight: 600; color: var(--brand-600); background: var(--brand-50);
  border: 1px solid transparent; border-radius: 999px; cursor: pointer;
}
html[data-design="classic"] .cal-ed-assist-btn:hover, html[data-design="classic"] .cal-ed-assist-btn.active { border-color: var(--brand-400); }
html[data-design="classic"] .cal-ed-assist-btn:focus-visible { outline: 2px solid var(--brand-500); outline-offset: 1px; }
html[data-design="classic"] .cal-chip-dot { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; }
html[data-design="classic"] .cal-chip-free { background: #22a559; }
html[data-design="classic"] .cal-chip-busy { background: var(--danger); }
html[data-design="classic"] .cal-chip-unknown { background: var(--gray-400); }

html[data-design="classic"] .sa { margin-top: 10px; border: 1px solid var(--border); border-radius: 10px; background: var(--bg-card); overflow: hidden; }
html[data-design="classic"] .sa-head { display: flex; align-items: center; gap: 4px; padding: 8px 10px; border-bottom: 1px solid var(--border); flex-wrap: wrap; }
html[data-design="classic"] .sa-day { font-size: 13px; color: var(--gray-800); margin: 0 4px; }
html[data-design="classic"] .sa-legend { margin-left: auto; display: flex; gap: 12px; font-size: 11.5px; color: var(--gray-500); flex-wrap: wrap; }
html[data-design="classic"] .sa-legend span { display: inline-flex; align-items: center; gap: 5px; }
html[data-design="classic"] .sa-key { display: inline-block; width: 14px; height: 10px; border-radius: 2px; }
html[data-design="classic"] .sa-key-busy { background: #5b5fee; }
html[data-design="classic"] .sa-key-off { background: repeating-linear-gradient(135deg, var(--gray-200) 0 3px, transparent 3px 6px); border: 1px solid var(--gray-300); }
html[data-design="classic"] .sa-key-mtg { border: 2px solid var(--brand-600); background: rgba(91, 95, 238, 0.12); }
html[data-design="classic"] .sa-status { padding: 8px 12px 0; font-size: 12.5px; color: var(--gray-600); }
html[data-design="classic"] .sa-ok { color: #1a7f45; font-weight: 600; }
html[data-design="classic"] .sa-warn { color: var(--danger); font-weight: 600; }
html[data-design="classic"] .sa-suggest { display: flex; align-items: center; flex-wrap: wrap; gap: 6px; padding: 8px 12px; font-size: 12.5px; color: var(--gray-600); }
html[data-design="classic"] .sa-suggest > svg { color: var(--brand-500); }
html[data-design="classic"] .sa-chip {
  padding: 3px 10px; margin: 0; min-width: 0; font-size: 12px; font-weight: 600; border-radius: 999px; cursor: pointer;
  border: 1px solid var(--brand-200); background: var(--bg-card); color: var(--brand-700);
}
html[data-design="classic"] .sa-chip:hover, html[data-design="classic"] .sa-chip.active { background: var(--brand-600); border-color: var(--brand-600); color: #fff; }
html[data-design="classic"] .sa-chip:focus-visible { outline: 2px solid var(--brand-500); outline-offset: 1px; }

html[data-design="classic"] .sa-grid { display: grid; grid-template-columns: 210px minmax(0, 1fr); border-top: 1px solid var(--border); }
html[data-design="classic"] .sa-names { border-right: 1px solid var(--border); background: var(--bg-card); }
html[data-design="classic"] .sa-name { display: flex; align-items: center; gap: 8px; height: 40px; padding: 0 10px; border-bottom: 1px solid var(--border); min-width: 0; }
html[data-design="classic"] .sa-name-head { height: 26px; font-size: 11px; font-weight: 700; color: var(--gray-500); text-transform: uppercase; letter-spacing: 0.04em; }
html[data-design="classic"] .sa-name-all { font-size: 12.5px; font-weight: 700; color: var(--gray-700); background: var(--gray-50); }
html[data-design="classic"] .sa-av { position: relative; width: 26px; height: 26px; font-size: 10px; overflow: visible; }
html[data-design="classic"] .sa-dot { position: absolute; right: -2px; bottom: -2px; width: 10px; height: 10px; border-radius: 50%; border: 2px solid var(--bg-card); }
html[data-design="classic"] .sa-dot-free { background: #22a559; }
html[data-design="classic"] .sa-dot-busy { background: var(--danger); }
html[data-design="classic"] .sa-dot-unknown { background: var(--gray-400); }
html[data-design="classic"] .sa-name-text { display: flex; flex-direction: column; min-width: 0; line-height: 1.2; }
html[data-design="classic"] .sa-name-main { font-size: 12.5px; font-weight: 600; color: var(--gray-800); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
html[data-design="classic"] .sa-name-sub { font-size: 11px; color: var(--gray-500); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

html[data-design="classic"] .sa-scroll { overflow-x: auto; overflow-y: hidden; }
html[data-design="classic"] .sa-canvas { position: relative; }
html[data-design="classic"] .sa-hours { display: flex; height: 26px; border-bottom: 1px solid var(--border); }
html[data-design="classic"] .sa-hours span { flex-shrink: 0; padding: 6px 0 0 4px; font-size: 10.5px; color: var(--gray-500); border-left: 1px solid var(--border); box-sizing: border-box; }
html[data-design="classic"] .sa-track {
  position: relative; height: 40px; border-bottom: 1px solid var(--border); cursor: pointer;
  background-image: linear-gradient(to right, var(--border) 1px, transparent 1px);
  background-size: 56px 100%;
}
html[data-design="classic"] .sa-track:first-of-type { background-color: var(--gray-50); }
html[data-design="classic"] .sa-track:hover { background-color: rgba(91, 95, 238, 0.04); }
html[data-design="classic"] .sa-off { position: absolute; top: 0; bottom: 0; background: repeating-linear-gradient(135deg, rgba(100, 116, 139, 0.13) 0 3px, transparent 3px 7px); pointer-events: none; }
html[data-design="classic"] .sa-busy { position: absolute; top: 9px; bottom: 9px; border-radius: 3px; background: #5b5fee; pointer-events: auto; }
html[data-design="classic"] .sa-unknown { background-color: transparent; background-image: repeating-linear-gradient(135deg, rgba(100, 116, 139, 0.09) 0 4px, transparent 4px 8px); }
html[data-design="classic"] .sa-meeting {
  position: absolute; top: 26px; bottom: 0; border: 2px solid var(--brand-600); border-radius: 3px;
  background: rgba(91, 95, 238, 0.1); pointer-events: none;
}
html[data-design="classic"] .sa-meeting-clash { border-color: var(--danger); background: rgba(214, 69, 69, 0.08); }
html[data-design="classic"] .sa-hint { margin: 0; padding: 6px 12px 8px; font-size: 11.5px; color: var(--gray-500); }

@media (max-width: 640px) {
  html[data-design="classic"] .sa-grid { grid-template-columns: 130px minmax(0, 1fr); }
  html[data-design="classic"] .sa-legend { display: none; }
  html[data-design="classic"] .cal-ed-assist-btn { margin-left: 0; }
}


/* ── src/styles/pages/change-requests.css ── */
/* Change Requests — self-contained page styles, following the same
   card/list/modal conventions as styles/decisions.css (prefixed .cr- to
   avoid clashing with the .decision-* classes used elsewhere). */

html[data-design="classic"] .cr-card { background:var(--bg-card); border:1px solid var(--border); border-radius:var(--radius-lg); overflow:hidden; transition:box-shadow .15s; margin-bottom:8px; }
html[data-design="classic"] .cr-card:hover { box-shadow:var(--shadow-sm); }
html[data-design="classic"] .cr-card.expanded { border-color:rgba(99,102,241,.3); }

html[data-design="classic"] .cr-card-header { display:flex; justify-content:space-between; align-items:flex-start; padding:14px 16px; cursor:pointer; gap:10px; }
html[data-design="classic"] .cr-card-left { flex:1; min-width:0; }
html[data-design="classic"] .cr-card-right { display:flex; align-items:center; gap:8px; flex-shrink:0; }

html[data-design="classic"] .cr-title { font-weight:600; font-size:14px; color:var(--text-primary); margin-bottom:4px; }
html[data-design="classic"] .cr-meta { display:flex; flex-wrap:wrap; align-items:center; gap:8px; }
html[data-design="classic"] .cr-category { font-size:11px; font-weight:600; padding:2px 8px; border-radius:20px; background:var(--bg-hover); color:var(--gray-500); }
html[data-design="classic"] .cr-impact { font-size:11px; font-weight:700; padding:2px 8px; border-radius:20px; }
html[data-design="classic"] .cr-status { font-size:12px; font-weight:700; padding:3px 10px; border-radius:20px; }
html[data-design="classic"] .cr-by { font-size:11px; color:var(--gray-400); }
html[data-design="classic"] .cr-date { font-size:11px; color:var(--gray-400); }

html[data-design="classic"] .cr-body { padding:0 16px 16px; border-top:1px solid var(--border); }
html[data-design="classic"] .cr-section { margin-top:12px; }
html[data-design="classic"] .cr-section-label { font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.04em; color:var(--gray-500); margin-bottom:4px; }
html[data-design="classic"] .cr-section-text { font-size:13px; color:var(--text-primary); line-height:1.5; white-space:pre-wrap; }
html[data-design="classic"] .cr-approvers { display:flex; flex-wrap:wrap; gap:6px; margin-top:4px; }
html[data-design="classic"] .cr-approver-chip { font-size:11px; padding:2px 8px; border-radius:20px; background:var(--bg-hover); color:var(--gray-600); }
html[data-design="classic"] .cr-approver-chip.current { background:rgba(99,102,241,.12); color:var(--brand-500); font-weight:600; }
html[data-design="classic"] .cr-rejection { margin-top:10px; padding:10px 12px; border-radius:8px; background:rgba(239,68,68,.08); border:1px solid rgba(239,68,68,.2); font-size:13px; color:#b91c1c; }

html[data-design="classic"] .cr-actions { display:flex; flex-wrap:wrap; gap:8px; margin-top:14px; }
html[data-design="classic"] .cr-expand-icon { font-size:11px; color:var(--gray-400); }

html[data-design="classic"] .cr-empty { text-align:center; padding:48px 16px; color:var(--gray-400); }
html[data-design="classic"] .cr-empty-icon { font-size:32px; margin-bottom:8px; }


/* ── src/styles/pages/dashboard.css ── */
/* ============================================================
   DASHBOARD — Layout & Components

   Redesign pass: every color/shadow/radius below now references a
   token from base.css instead of a one-off value, and hover motion is
   reserved for things that are genuinely clickable (buttons, nav
   tiles, list rows) rather than applied to every wrapper card — a
   static grouping container getting a hover-lift is the "same
   interaction on every card" tell of a generated layout.
   ============================================================ */
@keyframes classic-cc3FadeIn { from{opacity:0;transform:translateY(4px)} to{opacity:1;transform:none} }
@keyframes classic-cc3Spin   { to{transform:rotate(360deg)} }
@keyframes classic-dbPulse   { 0%,100%{opacity:1;box-shadow:0 0 0 0 rgba(30,142,90,.35)} 50%{opacity:.7;box-shadow:0 0 0 5px rgba(30,142,90,0)} }

/* ── Overdue modal ────────────────────────────────────────── */
html[data-design="classic"] .overdue-section { border-bottom:1px solid var(--border); padding:14px 22px; }
html[data-design="classic"] .overdue-section:last-child { border-bottom:none; }
html[data-design="classic"] .overdue-section-header { display:flex; align-items:center; gap:8px; font-size:13px; font-weight:700; color:var(--gray-700); margin-bottom:10px; }
html[data-design="classic"] .overdue-item { display:flex; align-items:center; gap:10px; padding:8px 10px; border-radius:var(--radius-md); cursor:pointer; transition:background var(--transition-fast); background:var(--gray-50); margin-bottom:6px; border:1px solid var(--border); }
html[data-design="classic"] .overdue-item:hover { background:var(--brand-50); border-color:var(--brand-200); }
html[data-design="classic"] .overdue-section-body { display:flex; flex-direction:column; gap:4px; }
html[data-design="classic"] .overdue-arrow  { font-size:12px; color:var(--gray-400); margin:0 4px; }
html[data-design="classic"] .overdue-empty  { font-size:13px; color:var(--gray-400); padding:8px 0; }

/* ── Root — scrollable page ─────────────────────────────── */
html[data-design="classic"] .db-root {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 14px 18px 20px;
  overflow-y: auto;
  height: 100%;
  max-height: 100%;
  background: var(--bg-canvas);
  box-sizing: border-box;
  min-height: 0;
}
html[data-design="classic"][data-theme="dark"] .db-root { background: var(--bg-page); }

/* ── Base card — Elevation Tier 1: sits on the canvas ──── */
html[data-design="classic"] .db-card {
  background: var(--surface-1);
  border-radius: var(--radius-lg);
  border: 1px solid var(--card-border);
  padding: 14px 16px;
  box-shadow: var(--elevation-1);
}
html[data-design="classic"][data-theme="dark"] .db-card { background:var(--bg-card); border-color:rgba(255,255,255,.08); }

html[data-design="classic"] .db-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}
html[data-design="classic"] .db-card-title {
  font-size: var(--text-2xs);
  font-weight: 700;
  color: var(--text-muted);
  letter-spacing: .04em;
  display: flex;
  align-items: center;
  gap: 7px;
}
html[data-design="classic"] .db-card-title svg { width: 13px; height: 13px; flex-shrink: 0; color: var(--brand-500); }
html[data-design="classic"] .db-link {
  font-size: 11px;
  font-weight: 700;
  color: var(--brand-600);
  background: none;
  border: none;
  cursor: pointer;
  padding: 2px 2px;
  border-radius: var(--radius-sm);
  transition: color var(--transition-fast);
}
html[data-design="classic"] .db-link:hover { color: var(--brand-700); text-decoration: underline; }
html[data-design="classic"] .db-link:focus-visible { outline: 2px solid var(--border-focus); outline-offset: 2px; }

html[data-design="classic"] .db-empty {
  font-size: 12px;
  color: var(--gray-400);
  padding: 12px 0;
  text-align: center;
}

/* ── Hero ───────────────────────────────────────────────── */
html[data-design="classic"] .db-hero {
  background: var(--surface-1);
  border-radius: var(--radius-lg);
  border: 1px solid var(--card-border);
  box-shadow: var(--elevation-1);
  position: relative;
  overflow: hidden;
}
/* A single brand-color bar, not a five-stop rainbow — the rainbow read
   as decorative flourish with no meaning; one deliberate brand accent
   is the restrained version of the same "this is the hero" signal. */
html[data-design="classic"] .db-hero-bar {
  height: 3px;
  background: var(--brand-500);
}
html[data-design="classic"] .db-hero-body {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 16px;
  flex-wrap: wrap;
}
html[data-design="classic"] .db-hero-left { display:flex; flex-direction:column; gap:8px; flex:1; min-width:0; }
html[data-design="classic"] .db-hero-greeting { font-size:var(--text-xl); font-weight:700; color:var(--text-primary); letter-spacing:-.3px; line-height:1.15; }
html[data-design="classic"] .db-hero-date { font-size:var(--text-sm); color:var(--text-muted); font-weight:500; }

html[data-design="classic"] .db-chips-row { display:flex; flex-wrap:wrap; gap:6px; }
html[data-design="classic"] .cc3-chip { display:flex; align-items:center; gap:4px; padding:4px 10px; border-radius:var(--radius-full); border:1px solid; font-size:var(--text-xs); transition:opacity var(--transition-fast); cursor:pointer; }
html[data-design="classic"] .cc3-chip:hover { opacity: 0.85; }
html[data-design="classic"] .cc3-chip-icon  { display:flex; align-items:center; }
html[data-design="classic"] .cc3-chip-icon svg { width:12px; height:12px; }
html[data-design="classic"] .cc3-chip-value { font-weight:700; font-size:var(--text-xs); }
html[data-design="classic"] .cc3-chip-label { opacity:.8; font-size:var(--text-2xs); font-weight:600; }

html[data-design="classic"] .db-hero-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
  flex-wrap: wrap;
  justify-content: flex-end;
}
html[data-design="classic"] .db-btn {
  font-size: var(--text-xs);
  font-weight: 700;
  padding: 7px 14px;
  border-radius: var(--radius-md);
  border: none;
  cursor: pointer;
  white-space: nowrap;
  transition: background var(--transition-fast), box-shadow var(--transition-fast), transform var(--transition-fast);
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
html[data-design="classic"] .db-btn svg { width: 13px; height: 13px; }
html[data-design="classic"] .db-btn:active { transform: translateY(1px); }
html[data-design="classic"] .db-btn:focus-visible { outline: 2px solid var(--border-focus); outline-offset: 2px; }

/* Buttons get real depth through elevation + a genuine press state,
   not a gradient fill — a flat, saturated fill with a crisp shadow on
   hover reads as more confident than a gradient does. */
html[data-design="classic"] .db-btn-primary  { background:var(--brand-600); color:#fff; box-shadow: var(--elevation-1); }
html[data-design="classic"] .db-btn-primary:hover  { background:var(--brand-700); box-shadow: var(--elevation-2); }
html[data-design="classic"] .db-btn-primary:active { box-shadow: var(--shadow-xs); }

html[data-design="classic"] .db-btn-green  { background:var(--success); color:#fff; box-shadow: var(--elevation-1); }
html[data-design="classic"] .db-btn-green:hover  { background:#176e46; box-shadow: var(--elevation-2); }

html[data-design="classic"] .db-btn-secondary { background:var(--gray-100); color:var(--gray-700); border:1px solid var(--border); }
html[data-design="classic"] .db-btn-secondary:hover { background:var(--gray-200); }

html[data-design="classic"] .db-btn-indigo { background:var(--brand-600); color:#fff; box-shadow: var(--elevation-1); }
html[data-design="classic"] .db-btn-indigo:hover { background:var(--brand-700); box-shadow: var(--elevation-2); }

html[data-design="classic"] .db-live-pill {
  display: flex; align-items: center; gap: 5px;
  padding: 5px 11px; background: rgba(30,142,90,.1);
  border: 1px solid rgba(30,142,90,.25); border-radius: var(--radius-full);
  font-size: 11px; font-weight: 700; color: var(--success);
}
html[data-design="classic"] .db-live-dot {
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--success); animation: classic-dbPulse 2s ease-in-out infinite;
  flex-shrink: 0;
}
html[data-design="classic"] .db-online-row {
  display: flex; align-items: center; gap: 6px;
  margin-top: 6px; padding-top: 6px;
  border-top: 1px solid var(--border);
}

/* ── Hub grid ───────────────────────────────────────────── */
html[data-design="classic"] .db-hub-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 6px;
}
html[data-design="classic"] .db-hub-grid-5 { grid-template-columns: repeat(5, 1fr); }
html[data-design="classic"] .db-hub-grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 6px; }

/* Nav tiles ARE genuinely clickable (each navigates somewhere), so real
   hover feedback belongs here — this is the one place in the dashboard
   where a lift-on-hover is earned rather than decorative. Kept subtle:
   1px, not the previous 2px + colored glow. */
html[data-design="classic"] .cc3-hub-tile {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 12px 6px;
  border-radius: var(--radius-md);
  border: 1px solid var(--card-border);
  background: var(--surface-1);
  cursor: pointer;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast), transform var(--transition-fast);
  text-align: center;
}
html[data-design="classic"] .cc3-hub-tile:hover {
  border-color: var(--brand-200);
  box-shadow: var(--elevation-1);
  transform: translateY(-1px);
}
html[data-design="classic"] .cc3-hub-tile:focus-visible { outline: 2px solid var(--border-focus); outline-offset: 2px; }
html[data-design="classic"][data-theme="dark"] .cc3-hub-tile { background:rgba(255,255,255,.04); border-color:rgba(255,255,255,.08); }

html[data-design="classic"] .cc3-hub-icon-badge {
  display: flex; align-items: center; justify-content: center;
  width: 32px; height: 32px; border-radius: var(--radius-md);
  background: var(--tile-tint, var(--brand-50));
  color: var(--tile-color, var(--brand-600));
  transition: transform var(--transition-fast);
}
html[data-design="classic"] .cc3-hub-icon-badge svg { width: 16px; height: 16px; }
html[data-design="classic"] .cc3-hub-tile:hover .cc3-hub-icon-badge { transform: scale(1.06); }
html[data-design="classic"] .cc3-hub-label { font-size: var(--text-2xs); font-weight: 700; color: var(--text-primary); line-height: 1.2; }
html[data-design="classic"][data-theme="dark"] .cc3-hub-label { color:rgba(255,255,255,.78); }
html[data-design="classic"] .cc3-hub-sub   { font-size: var(--text-2xs); color: var(--gray-400); font-weight: 500; line-height: 1.2; }

/* ── Projects + Goals + Charts row ─────────────────────── */
html[data-design="classic"] .db-pg-row {
  display: grid;
  grid-template-columns: 1fr 280px;
  gap: 8px;
  align-items: stretch;
}

/* Project / Goal item cards */
html[data-design="classic"] .db-item-list { display:flex; flex-direction:column; gap:6px; }

html[data-design="classic"] .cc3-item-card {
  background: var(--gray-50);
  border: 1px solid var(--card-border);
  border-radius: var(--radius-md);
  padding: 9px 12px;
  cursor: pointer;
  transition: background var(--transition-fast), border-color var(--transition-fast);
  width: 100%;
  box-sizing: border-box;
}
html[data-design="classic"] .cc3-item-card:hover { background:var(--brand-50); border-color:var(--brand-200); }
html[data-design="classic"] .cc3-item-card:focus-visible { outline: 2px solid var(--border-focus); outline-offset: 2px; }
html[data-design="classic"][data-theme="dark"] .cc3-item-card { background:rgba(255,255,255,.04); border-color:rgba(255,255,255,.08); }
html[data-design="classic"] .cc3-item-card-top { display:flex; align-items:center; gap:6px; margin-bottom:6px; min-width:0; }
html[data-design="classic"] .cc3-item-dot  { width:7px; height:7px; border-radius:50%; flex-shrink:0; }
html[data-design="classic"] .cc3-item-name { font-size:var(--text-sm); font-weight:600; color:var(--text-primary); flex:1; min-width:0; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
html[data-design="classic"] .cc3-item-bar  { height:4px; background:var(--gray-200); border-radius:var(--radius-full); overflow:hidden; margin-bottom:4px; }
html[data-design="classic"] .cc3-item-fill { height:100%; border-radius:var(--radius-full); transition:width .4s; }
html[data-design="classic"] .cc3-item-pct  { font-size:var(--text-2xs); font-weight:700; color:var(--gray-400); }
html[data-design="classic"] .cc3-item-card .badge { flex-shrink:0; font-size:var(--text-2xs); padding:2px 8px; border-radius:var(--radius-full); font-weight:700; }

/* Charts column */
html[data-design="classic"] .db-charts-col {
  display: flex;
  flex-direction: column;
  gap: 8px;
  height: 100%;
}
html[data-design="classic"] .db-charts-col .db-ai-card { flex: 1; }

/* Chart panel — Elevation Tier 1, same as any other card */
html[data-design="classic"] .cc3-chart-panel {
  background: var(--surface-1); border-radius: var(--radius-lg);
  border: 1px solid var(--card-border); padding: 12px 14px;
  box-shadow: var(--elevation-1);
}
html[data-design="classic"] .cc3-chart-tabs { display:flex; gap:3px; margin-bottom:8px; padding-bottom:6px; border-bottom:1px solid var(--border); }
html[data-design="classic"] .cc3-chart-tab { padding:3px 10px; border-radius:var(--radius-full); font-size:var(--text-xs); font-weight:600; border:1px solid var(--card-border); background:var(--gray-50); color:var(--text-muted); cursor:pointer; transition:background var(--transition-fast), color var(--transition-fast), border-color var(--transition-fast); }
html[data-design="classic"] .cc3-chart-tab:hover { border-color:var(--brand-200); color:var(--brand-600); }
html[data-design="classic"] .cc3-chart-tab.active { background:var(--brand-50); border-color:var(--brand-200); color:var(--brand-700); }
html[data-design="classic"] .cc3-chart-tab:focus-visible { outline: 2px solid var(--border-focus); outline-offset: 2px; }
html[data-design="classic"] .cc3-chart-title { font-size:var(--text-2xs); font-weight:700; letter-spacing:.04em; color:var(--gray-400); margin-bottom:6px; }
html[data-design="classic"] .cc3-chart-empty { font-size:var(--text-xs); color:var(--gray-400); text-align:center; padding:20px 0; }
html[data-design="classic"] .cc3-stat-grid  { display:grid; grid-template-columns:1fr 1fr; gap:6px; margin-top:8px; }
html[data-design="classic"] .cc3-mini-stat  { padding:8px 10px; border-radius:var(--radius-sm); background:var(--gray-50); border-left:3px solid; cursor:pointer; transition:background var(--transition-fast); }
html[data-design="classic"] .cc3-mini-stat:hover { background:var(--brand-50); }
html[data-design="classic"] .cc3-mini-stat:focus-visible { outline: 2px solid var(--border-focus); outline-offset: 2px; }
html[data-design="classic"] .cc3-mini-val   { font-size:18px; font-weight:700; line-height:1; margin-bottom:2px; }
html[data-design="classic"] .cc3-mini-lbl   { font-size:var(--text-2xs); color:var(--gray-400); font-weight:500; }

/* Donut wrap — center label anchors the ring so a single (100%) slice
   reads as "1 of 1 tasks", not as an unlabelled solid circle. */
html[data-design="classic"] .cc3-donut-wrap { position: relative; }
html[data-design="classic"] .cc3-donut-center {
  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
  display: flex; flex-direction: column; align-items: center;
  pointer-events: none;
}
html[data-design="classic"] .cc3-donut-total { font-size: 20px; font-weight: 700; color: var(--text-primary); line-height: 1; }
html[data-design="classic"] .cc3-donut-label { font-size: var(--text-2xs); color: var(--gray-400); font-weight: 600; margin-top: 2px; }

/* ── Insights row ───────────────────────────────────────── */
html[data-design="classic"] .db-insights-row {
  display: grid;
  grid-template-columns: 1fr 280px;
  gap: 8px;
  align-items: stretch;
}
html[data-design="classic"] .db-insights-row .db-ai-card {
  height: 100%;
  box-sizing: border-box;
}
html[data-design="classic"] .db-insights-left { display:flex; flex-direction:column; gap:0; }

/* ── AI insight card — its own dark surface (this module deliberately
   looks distinct, since it's a different kind of content), but no
   radial-gradient glow or multi-stop rainbow border — a flat deep-ink
   fill with one accent line reads as considered rather than decorated,
   and still sits at Elevation Tier 1 like everything else on the page
   instead of an oversized glow-shadow implying it's more important. ── */
html[data-design="classic"] .db-ai-card {
  background: #0F1729;
  border: 1px solid rgba(91,95,238,.35);
  border-radius: var(--radius-lg);
  padding: 12px;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 8px;
  box-shadow: var(--elevation-1);
}
html[data-design="classic"] .db-ai-card::before { content:''; position:absolute; top:0; left:0; right:0; height:2px; background:var(--brand-500); }
html[data-design="classic"] .db-ai-card-top { display:flex; align-items:center; }
html[data-design="classic"] .db-ai-badge { font-size:var(--text-2xs); font-weight:700; color:#fff; background:rgba(91,95,238,.28); padding:4px 11px; border-radius:var(--radius-full); letter-spacing:.03em; border:1px solid rgba(91,95,238,.5); }
html[data-design="classic"] .db-ai-text  { font-size:var(--text-sm); font-weight:500; color:#dbe0ea; line-height:1.6; }
html[data-design="classic"] .db-ai-warn  { color:#e6a23c; font-weight:700; }
html[data-design="classic"] .db-ai-good  { color:#3fcf8e; font-weight:700; }
html[data-design="classic"] .db-ai-stats {
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: 6px;
}
html[data-design="classic"] .db-ai-stat {
  background: rgba(255,255,255,.07);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-sm);
  padding: 8px 6px;
  cursor: pointer;
  transition: background var(--transition-fast);
  text-align: center;
}
html[data-design="classic"] .db-ai-stat:hover { background:rgba(255,255,255,.13); }
html[data-design="classic"] .db-ai-stat:focus-visible { outline: 2px solid #fff; outline-offset: 2px; }
html[data-design="classic"] .db-ai-stat-val { font-size:17px; font-weight:700; line-height:1; margin-bottom:3px; }
html[data-design="classic"] .db-ai-stat-lbl { font-size:var(--text-2xs); color:rgba(255,255,255,.6); font-weight:600; }
html[data-design="classic"] .db-ai-btn {
  background: var(--brand-500);
  color:#fff; border:none; border-radius:var(--radius-md);
  padding:9px 12px; font-size:var(--text-xs); font-weight:700;
  cursor:pointer; transition:background var(--transition-fast), box-shadow var(--transition-fast); width:100%;
  letter-spacing:.02em; box-shadow: var(--elevation-1);
}
html[data-design="classic"] .db-ai-btn:hover { background:var(--brand-400); box-shadow: var(--elevation-2); }
html[data-design="classic"] .db-ai-btn:focus-visible { outline: 2px solid #fff; outline-offset: 2px; }

/* ── Bottom row — Team + AI + Configure ─────────────────── */
html[data-design="classic"] .db-bottom-row {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 8px;
  align-items: stretch;
}
html[data-design="classic"] .db-bottom-row > .db-card {
  display: flex;
  flex-direction: column;
}
html[data-design="classic"] .db-bottom-row > .db-card .db-compact-list {
  flex: 1;
}

/* ── Compact list ───────────────────────────────────────── */
html[data-design="classic"] .db-compact-list { display:flex; flex-direction:column; gap:2px; }
html[data-design="classic"] .db-compact-item {
  display: flex; align-items: center; gap:9px;
  padding: 6px 8px; border-radius: var(--radius-sm);
  cursor: pointer; transition: background var(--transition-fast);
}
html[data-design="classic"] .db-compact-item:hover { background:var(--brand-50); }
html[data-design="classic"] .db-compact-item:focus-visible { outline: 2px solid var(--border-focus); outline-offset: 2px; }
html[data-design="classic"][data-theme="dark"] .db-compact-item:hover { background:rgba(255,255,255,.05); }
html[data-design="classic"] .db-compact-icon { display:flex; align-items:center; justify-content:center; flex-shrink:0; width:20px; color:var(--brand-500); }
html[data-design="classic"] .db-compact-icon svg { width:15px; height:15px; }
html[data-design="classic"] .db-compact-name { font-size:var(--text-sm); font-weight:600; color:var(--text-primary); flex:1; }
html[data-design="classic"] .db-compact-sub  { font-size:var(--text-2xs); color:var(--gray-400); font-weight:500; }
html[data-design="classic"] .db-ai-nudge {
  display:flex; align-items:center; gap:6px; margin-top:8px;
  padding:5px 8px; background:var(--brand-50);
  border:1px dashed var(--brand-200); border-radius:var(--radius-sm);
  cursor:pointer; transition:background var(--transition-fast), border-style var(--transition-fast); font-size:11px; color:var(--text-muted);
}
html[data-design="classic"] .db-ai-nudge:hover { background:var(--brand-100); border-style:solid; color:var(--brand-600); }

/* ── Misc ───────────────────────────────────────────────── */
html[data-design="classic"] .cc3-loading { display:flex; align-items:center; justify-content:center; gap:12px; min-height:260px; font-size:13px; color:var(--text-muted); }
html[data-design="classic"] .cc3-loading-spinner { width:22px; height:22px; border:2px solid var(--gray-200); border-top-color:var(--brand-500); border-radius:50%; animation:classic-cc3Spin .75s linear infinite; }
html[data-design="classic"] .cc3-error-card  { text-align:center; padding:48px 24px; background:var(--surface-1); border-radius:var(--radius-lg); border:1px solid var(--card-border); }
html[data-design="classic"] .cc3-error-icon  { display:flex; align-items:center; justify-content:center; color:var(--danger); margin-bottom:10px; }
html[data-design="classic"] .cc3-error-title { font-size:15px; font-weight:700; color:var(--danger); margin-bottom:4px; }
html[data-design="classic"] .cc3-error-sub   { font-size:12px; color:var(--gray-400); }

/* ── Keep old cc3 classes for backwards compat ──────────── */
html[data-design="classic"] .cc3-empty { font-size:12px; color:var(--gray-400); padding:10px 0; text-align:center; }
html[data-design="classic"] .cc3-item-grid-compact { display:flex; flex-direction:column; gap:5px; }
html[data-design="classic"] .cc3-online-row { display:flex; align-items:center; gap:6px; margin-top:8px; padding-top:7px; border-top:1px solid var(--border); }

/* Respect reduced-motion preference — every transition above becomes instant */
@media (prefers-reduced-motion: reduce) {
  html[data-design="classic"] .db-root, html[data-design="classic"] .db-card, html[data-design="classic"] .db-btn, html[data-design="classic"] .cc3-hub-tile, html[data-design="classic"] .cc3-item-card, html[data-design="classic"] .cc3-chart-tab, html[data-design="classic"] .cc3-mini-stat, html[data-design="classic"] .db-ai-stat, html[data-design="classic"] .db-ai-btn, html[data-design="classic"] .db-compact-item, html[data-design="classic"] .db-ai-nudge, html[data-design="classic"] .db-live-dot {
    animation: none !important;
    transition: none !important;
  }
}

/* ==========================================================================
   Stage 4 — Dashboard in the Studio + Atlas style
   ========================================================================== */
/* The page is a fixed-height flex column; without this, sections were
   allowed to shrink — the hero (greeting, KPI chips, New project / New goal /
   Reminder / Guide) collapsed to 2px and could not be seen at all. */
html[data-design="classic"] .db-root > * { flex-shrink: 0; }
html[data-design="classic"] .db-root { padding: 24px 32px 32px; gap: 14px; background: var(--bg-page); }

/* Hero → the same title row every page opens with */
html[data-design="classic"] .db-hero { background: none; border: 0; box-shadow: none; overflow: visible; border-radius: 0; }
html[data-design="classic"] .db-hero-bar { display: none; }
html[data-design="classic"] .db-hero-body { padding: 0; align-items: flex-start; }
html[data-design="classic"] .db-hero-greeting { margin: 0; font-size: 26px; font-weight: 700; letter-spacing: -0.02em; line-height: 1.2; }
html[data-design="classic"] .db-hero-date { font-size: 14px; color: var(--text-secondary); font-weight: 400; }
html[data-design="classic"] .db-chips-row { margin-top: 6px; }
/* one primary action; the rest are quiet secondary buttons */
html[data-design="classic"] .db-hero-actions .db-btn { height: var(--control-h); padding: 0 14px; border-radius: var(--radius-md); font-size: 13px; font-weight: 600; box-shadow: none; }
html[data-design="classic"] .db-hero-actions .db-btn-primary { background: var(--brand-500); }
html[data-design="classic"] .db-hero-actions .db-btn-primary:hover { background: var(--brand-600); }
html[data-design="classic"] .db-hero-actions .db-btn-green,
html[data-design="classic"] .db-hero-actions .db-btn-indigo,
html[data-design="classic"] .db-hero-actions .db-btn-secondary {
  background: var(--bg-card, #fff);
  color: var(--text-primary);
  border: 1px solid var(--border-strong);
}
html[data-design="classic"] .db-hero-actions .db-btn-green:hover,
html[data-design="classic"] .db-hero-actions .db-btn-indigo:hover,
html[data-design="classic"] .db-hero-actions .db-btn-secondary:hover { background: var(--bg-page); }

/* Cards: flat with a hairline border, like Projects and Tasks */
html[data-design="classic"] .db-card, html[data-design="classic"] .db-ai-card { box-shadow: none; border-color: var(--border); border-radius: var(--radius-lg); }

/* AI cards: light, with the brand as the accent (they were the only dark
   panels on a light page) */
html[data-design="classic"] .db-ai-card { background: var(--bg-card, #fff); border: 1px solid var(--border); padding: 16px; }
html[data-design="classic"] .db-ai-card::before { display: none; }
html[data-design="classic"] .db-ai-badge { color: var(--brand-700); background: var(--brand-50); border-color: var(--brand-200); }
html[data-design="classic"] .db-ai-text { color: var(--text-primary); }
html[data-design="classic"] .db-ai-warn { color: var(--warning-text); }
html[data-design="classic"] .db-ai-good { color: var(--success-text); }
html[data-design="classic"] .db-ai-stat { background: var(--bg-page); border-color: var(--border); }
html[data-design="classic"] .db-ai-stat:hover { background: var(--brand-50); }
html[data-design="classic"] .db-ai-stat:focus-visible { outline-color: var(--brand-500); }
html[data-design="classic"] .db-ai-stat-lbl { color: var(--text-secondary); }
html[data-design="classic"] .db-ai-btn { box-shadow: none; height: var(--control-h); }
html[data-design="classic"] .db-ai-btn:focus-visible { outline-color: var(--brand-500); }

html[data-design="classic"][data-theme="dark"] .db-root { background: var(--bg-page); }
html[data-design="classic"][data-theme="dark"] .db-hero { background: none; }
html[data-design="classic"][data-theme="dark"] .db-ai-card { background: var(--bg-card); border-color: rgba(255,255,255,0.08); }
html[data-design="classic"][data-theme="dark"] .db-ai-badge { color: #C7C8F5; background: rgba(124,128,255,0.16); border-color: rgba(124,128,255,0.3); }
html[data-design="classic"][data-theme="dark"] .db-ai-stat { background: rgba(255,255,255,0.04); border-color: rgba(255,255,255,0.08); }
html[data-design="classic"][data-theme="dark"] .db-hero-actions .db-btn-green,
html[data-design="classic"][data-theme="dark"] .db-hero-actions .db-btn-indigo,
html[data-design="classic"][data-theme="dark"] .db-hero-actions .db-btn-secondary { background: transparent; color: #fff; border-color: rgba(255,255,255,0.18); }

@media (max-width: 768px) { html[data-design="classic"] .db-root { padding: 16px; } }
/* the chart panel had no dark-theme surface */
html[data-design="classic"] .cc3-chart-panel { box-shadow: none; border-color: var(--border); }
html[data-design="classic"][data-theme="dark"] .cc3-chart-panel { background: var(--bg-card); border-color: rgba(255,255,255,0.08); }


