html[data-design="classic"] .dev-card-url  { font-size: 12px; color: var(--gray-400); margin-top: 2px; font-family: monospace; }

html[data-design="classic"] .dev-card-actions { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }

html[data-design="classic"] .dev-card-body { padding: 10px 16px 14px; border-top: 1px solid var(--gray-50); }

html[data-design="classic"] .dev-status-dot.inactive { background: var(--gray-300); }

html[data-design="classic"] .dev-stat { font-size: 11px; color: var(--gray-400); }

html[data-design="classic"] .dev-last-status { font-size: 10px; font-weight: 700; padding: 2px 6px; border-radius: 3px; }

html[data-design="classic"] .dev-last-status.ok     { background: rgba(5,150,105,0.12); color: var(--success); }

html[data-design="classic"] .dev-last-status.failed { background: rgba(220,38,38,0.12); color: var(--danger); }

html[data-design="classic"] .dev-events-row { display: flex; flex-wrap: wrap; gap: 5px; }

html[data-design="classic"] .dev-event-tag {
