html[data-design="classic"] .dev-event-tag.dev-event-all { background: var(--brand-100); color: var(--brand-700); }

html[data-design="classic"] .dev-scope-read  { background: #e0f2fe; color: #0369a1; }

html[data-design="classic"] .dev-scope-write { background: rgba(217,119,6,0.12); color: var(--warning); }

html[data-design="classic"] .dev-secret-row {
