}

html[data-design="classic"] .dev-key-code {
  flex: 1; font-size: 12px; color: #86efac;
  word-break: break-all; font-family: monospace; letter-spacing: 0.03em;
}
/* Docs tab */
html[data-design="classic"] .dev-docs { display: flex; flex-direction: column; gap: 24px; }

html[data-design="classic"] .dev-docs-header h3 { font-size: 18px; font-weight: 800; margin-bottom: 6px; }

html[data-design="classic"] .dev-docs-header p  { font-size: 13px; color: var(--gray-500); }

html[data-design="classic"] .dev-docs-sections {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 12px;
}

html[data-design="classic"] .dev-docs-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 14px 16px;
  box-shadow: var(--shadow-xs);
}

html[data-design="classic"] .dev-docs-card-title { font-size: 14px; font-weight: 700; margin-bottom: 6px; }

html[data-design="classic"] .dev-docs-base { font-size: 11px; color: var(--gray-500); display: block; margin-bottom: 8px; }

html[data-design="classic"] .dev-docs-methods { display: flex; gap: 4px; flex-wrap: wrap; }

html[data-design="classic"] .dev-docs-auth h4  { font-size: 14px; font-weight: 700; margin-bottom: 6px; margin-top: 0; }

html[data-design="classic"] .dev-docs-auth p   { font-size: 13px; color: var(--gray-500); margin-bottom: 8px; }

html[data-design="classic"] .dev-code-block {
  background: var(--gray-900); color: #86efac;
  border-radius: var(--radius-md); padding: 14px 16px;
  font-size: 12px; font-family: monospace; line-height: 1.6;
  overflow-x: auto; display: block; margin-bottom: 20px;
  white-space: pre;
}

html[data-design="classic"] .dev-toast {
  position: fixed; bottom: 80px; right: 24px;
  background: var(--gray-900); color: #fff;
  padding: 10px 18px; border-radius: var(--radius-md);
  font-size: 13px; font-weight: 500;
  z-index: 9999; box-shadow: var(--shadow-xl);
  animation: classic-toast-in 0.2s ease;
}

html[data-design="classic"][data-theme="dark"] .dev-docs-card   { background: var(--bg-card); }

html[data-design="classic"][data-theme="dark"] .dev-key-code    { color: #4ade80; }

html[data-design="classic"][data-theme="dark"] .dev-event-chip  { background: var(--gray-800); color: var(--gray-400); }

html[data-design="classic"][data-theme="dark"] .dev-card-header         { border-color: var(--border); }

html[data-design="classic"][data-theme="dark"] .dev-card-body           { border-color: #1a3550; }

html[data-design="classic"][data-theme="dark"] .dev-docs-card           { background: var(--bg-card); border-color: var(--border); }

html[data-design="classic"][data-theme="dark"] .dev-event-chip          { background: #1a3550; color: var(--gray-600); }

/* ── src/styles/pages/docs-v2.css ── */
/* ==========================================================================
   Docs — Studio + Atlas
   Block styles (headings, lists, to-dos, callouts, quotes, code had none, so
   everything rendered as plain lines), a centred reading column, a calmer
   page tree with actions on hover.
   ========================================================================== */

/* ── Page tree ───────────────────────────────────────────────────────────── */
html[data-design="classic"] .docs-sidebar { background: var(--bg-page); border-right: 1px solid var(--border); }
html[data-design="classic"] .docs-new-page-btn { border-radius: var(--radius-md) !important; height: var(--control-h); font-weight: 600; }
html[data-design="classic"] .docs-tree-label { font-size: 11.5px; font-weight: 700; letter-spacing: 0.05em; color: var(--text-muted); }

html[data-design="classic"] .doc-tree-item-row {
  margin: 1px 6px;
  border-radius: var(--radius-sm);
  cursor: pointer;
}
html[data-design="classic"] .doc-tree-item-row:hover { background: var(--bg-card, #fff); }
html[data-design="classic"] .doc-tree-item-row.is-active { background: var(--brand-50); }
html[data-design="classic"] .doc-tree-item-row:focus-visible { outline: 2px solid var(--brand-500); outline-offset: -2px; }
html[data-design="classic"] .doc-tree-item-top { display: flex; align-items: center; gap: 4px; height: 30px; min-width: 0; }
html[data-design="classic"] .doc-tree-chevron-btn {
  display: inline-flex !important; align-items: center; justify-content: center;
  width: 20px; height: 20px; padding: 0 !important; flex-shrink: 0;
  border: 0; background: none; color: var(--text-muted); border-radius: 4px;
}
html[data-design="classic"] .doc-tree-chevron-btn:hover { background: var(--gray-100); color: var(--text-primary); }
html[data-design="classic"] .doc-tree-chevron-btn svg { transition: transform 0.15s; }
html[data-design="classic"] .doc-tree-chevron-btn svg.open { transform: rotate(90deg); }
html[data-design="classic"] .doc-tree-item-icon { width: 20px; display: inline-flex; justify-content: center; font-size: 14px; color: var(--text-muted); flex-shrink: 0; }
html[data-design="classic"] .doc-tree-item-name {
  flex: 1; min-width: 0;
  font-size: 13.5px; color: var(--text-primary);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
html[data-design="classic"] .doc-tree-item-name.active { color: var(--brand-700); font-weight: 600; }
/* actions sit at the row's end, shown on hover / keyboard focus / open menu */
html[data-design="classic"] .doc-tree-item-row .doc-tree-item-actions {
  display: inline-flex; align-items: center; gap: 0; margin: 0 2px 0 auto;
  opacity: 0; transition: opacity 0.1s;
  position: static; padding: 0; background: none; border: 0; box-shadow: none;
}
html[data-design="classic"] .doc-tree-item-row:hover .doc-tree-item-actions,
html[data-design="classic"] .doc-tree-item-row:focus-within .doc-tree-item-actions,
html[data-design="classic"] .doc-tree-item-actions:has([aria-expanded="true"]) { opacity: 1; }
html[data-design="classic"] .doc-tree-act {
  display: inline-flex !important; align-items: center; justify-content: center;
  width: 24px !important; height: 24px !important; padding: 0 !important;
  border: 0; border-radius: 4px; background: none; color: var(--text-muted);
}
html[data-design="classic"] .doc-tree-act:hover { background: var(--gray-100); color: var(--text-primary); }

/* ── Editor chrome ───────────────────────────────────────────────────────── */
html[data-design="classic"] .docs-topbar { background: var(--bg-card, #fff); border-bottom: 1px solid var(--border); }
html[data-design="classic"] .docs-topbar-right button { border-radius: var(--radius-sm); font-weight: 600; }
html[data-design="classic"] .docs-editor-body { background: var(--bg-card, #fff); }
/* one centred reading column: title, tags, toolbar and blocks line up */
html[data-design="classic"] .docs-editor-body > * { max-width: 760px; margin-left: auto; margin-right: auto; box-sizing: border-box; }
html[data-design="classic"] .docs-blocks-wrap { padding: 4px 0 80px; }
html[data-design="classic"] .doc-block { padding: 2px 40px; max-width: none; border-radius: var(--radius-sm); }
html[data-design="classic"] .doc-format-bar { border-radius: var(--radius-md); }
html[data-design="classic"] .doc-emoji-btn { border-radius: var(--radius-md); }
html[data-design="classic"] .docs-title { font-size: 34px !important; font-weight: 700 !important; letter-spacing: -0.02em; color: var(--text-primary); }

/* ── Blocks ──────────────────────────────────────────────────────────────── */
html[data-design="classic"] .doc-block { display: flex; align-items: flex-start; gap: 8px; }
html[data-design="classic"] .doc-block .doc-block-input { flex: 1; min-width: 0; font-size: 15px; line-height: 1.65; color: var(--text-primary); }
html[data-design="classic"] .doc-block--heading1 { margin-top: 18px; }
html[data-design="classic"] .doc-block--heading1 .doc-block-input { font-size: 26px; font-weight: 700; line-height: 1.3; letter-spacing: -0.015em; }
html[data-design="classic"] .doc-block--heading2 { margin-top: 14px; }
html[data-design="classic"] .doc-block--heading2 .doc-block-input { font-size: 20px; font-weight: 700; line-height: 1.35; }
html[data-design="classic"] .doc-block--heading3 { margin-top: 10px; }
html[data-design="classic"] .doc-block--heading3 .doc-block-input { font-size: 17px; font-weight: 600; line-height: 1.4; }
html[data-design="classic"] .doc-list-dot, html[data-design="classic"] .doc-list-num {
  flex-shrink: 0; min-width: 18px; line-height: 1.65; font-size: 15px;
  color: var(--text-secondary); text-align: right;
}
html[data-design="classic"] .doc-list-num { font-variant-numeric: tabular-nums; }
html[data-design="classic"] .doc-todo-cb { margin-top: 6px !important; width: 16px !important; height: 16px; }
html[data-design="classic"] .doc-block--quote { position: relative; }
html[data-design="classic"] .doc-block--quote .doc-quote-line { align-self: stretch; width: 3px; flex-shrink: 0; border-radius: 2px; background: var(--border-strong); }
html[data-design="classic"] .doc-block--quote .doc-block-input { color: var(--text-secondary); font-style: italic; }
html[data-design="classic"] .doc-block--callout {
  margin: 6px 40px; padding: 12px 14px;
  background: var(--brand-50); border: 1px solid var(--brand-100); border-radius: var(--radius-md);
}
html[data-design="classic"] .doc-callout-emoji { flex-shrink: 0; line-height: 1.65; }
html[data-design="classic"] .doc-block--code {
  margin: 6px 40px; padding: 12px 14px;
  background: #F6F7FA; border: 1px solid var(--border); border-radius: var(--radius-md);
}
html[data-design="classic"] .doc-block--code .doc-block-input { font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace; font-size: 13.5px; }
html[data-design="classic"] .doc-block--divider { padding-top: 8px; padding-bottom: 8px; }
html[data-design="classic"] .doc-block-actions { right: 8px; border-radius: var(--radius-sm); }
html[data-design="classic"] .doc-block-actions button { display: inline-flex; align-items: center; }

html[data-design="classic"] .doc-add-block {
  margin: 6px 40px; padding: 6px 0; width: auto;
  color: var(--text-muted); font-size: 13.5px; cursor: pointer;
}
html[data-design="classic"] .doc-add-block:hover { color: var(--brand-600); }

/* ── Dark ────────────────────────────────────────────────────────────────── */
html[data-design="classic"][data-theme="dark"] .docs-sidebar { background: var(--bg-page); border-color: rgba(255,255,255,0.08); }
html[data-design="classic"][data-theme="dark"] .doc-tree-item-row:hover { background: rgba(255,255,255,0.05); }
html[data-design="classic"][data-theme="dark"] .doc-tree-item-row.is-active { background: rgba(124,128,255,0.16); }
html[data-design="classic"][data-theme="dark"] .doc-tree-item-name.active { color: #C7C8F5; }
html[data-design="classic"][data-theme="dark"] .doc-tree-act:hover,
html[data-design="classic"][data-theme="dark"] .doc-tree-chevron-btn:hover { background: rgba(255,255,255,0.08); }
html[data-design="classic"][data-theme="dark"] .docs-topbar,
html[data-design="classic"][data-theme="dark"] .docs-editor-body { background: var(--bg-card); border-color: rgba(255,255,255,0.08); }
html[data-design="classic"][data-theme="dark"] .doc-block--callout { background: rgba(124,128,255,0.1); border-color: rgba(124,128,255,0.25); }
html[data-design="classic"][data-theme="dark"] .doc-block--code { background: rgba(255,255,255,0.04); border-color: rgba(255,255,255,0.08); }
html[data-design="classic"][data-theme="dark"] .doc-block-actions { background: var(--bg-card); }

/* Title, tags and toolbar sit in the same centred column as the blocks */
html[data-design="classic"] .docs-editor-wrap > .docs-header,
html[data-design="classic"] .docs-editor-wrap > .doc-tags-row {
  width: 100%;
  max-width: 760px;
  margin-left: auto;
  margin-right: auto;
  box-sizing: border-box;
  padding-left: 40px;
  padding-right: 40px;
}
html[data-design="classic"] .docs-editor-wrap > .docs-header { padding-top: 28px; }
html[data-design="classic"] .docs-editor-wrap > .doc-format-bar { padding-left: max(16px, calc((100% - 760px) / 2 + 36px)); padding-right: 16px; }

/* Tree: hidden actions take no room, so names aren't cut short */
html[data-design="classic"] .doc-tree-item-row .doc-tree-item-actions { display: none; opacity: 1; }
html[data-design="classic"] .doc-tree-item-row:hover .doc-tree-item-actions,
html[data-design="classic"] .doc-tree-item-row:focus-within .doc-tree-item-actions,
html[data-design="classic"] .doc-tree-item-actions:has([aria-expanded="true"]) { display: inline-flex; }
/* the title is an <input>; the dark theme gave it a dark fill with dark text */
html[data-design="classic"][data-theme="dark"] .docs-title,
html[data-design="classic"][data-theme="dark"] .docs-title:focus { color: #fff; background: transparent !important; }


/* ── src/styles/pages/docs.css ── */
/* ============================================================
   DOCS — Complete Polished Styles
   ============================================================ */

/* ── Page Shell ──────────────────────────────────────────────*/
html[data-design="classic"] .docs-page {
  display: flex;
  height: calc(100vh - 56px);
  max-height: calc(100vh - 56px);
  overflow: hidden;
  background: var(--gray-50);
  font-family: inherit;
}

/* ── Sidebar ─────────────────────────────────────────────────*/
html[data-design="classic"] .docs-sidebar {
  width: 260px;
  min-width: 260px;
  background: var(--gray-50);
  border-right: 1px solid #e8ecf0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transition: width 0.2s ease, min-width 0.2s ease;
  flex-shrink: 0;
}
html[data-design="classic"] .docs-sidebar--closed { width: 40px; min-width: 40px; }

html[data-design="classic"] .docs-sb-header {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 46px;
  flex-shrink: 0;
}
html[data-design="classic"] .docs-sb-title {
  flex: 1;
  font-weight: 700;
  font-size: 14px;
  color: var(--gray-800);
  display: flex;
  align-items: center;
  gap: 6px;
}
html[data-design="classic"] .docs-sb-toggle {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 16px;
  color: var(--gray-400);
  padding: 3px 6px;
  border-radius: 5px;
  line-height: 1;
  margin-left: auto;
  flex-shrink: 0;
}
html[data-design="classic"] .docs-sb-toggle:hover { background: var(--gray-100); color: var(--gray-600); }

html[data-design="classic"] .docs-sb-search-wrap { padding: 10px 10px 6px; flex-shrink: 0; }
html[data-design="classic"] .docs-sb-search {
  width: 100%;
  padding: 7px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 13px;
  outline: none;
  background: var(--gray-50);
  box-sizing: border-box;
  color: var(--gray-700);
  transition: border-color 0.15s;
}
html[data-design="classic"] .docs-sb-search:focus { border-color: var(--brand-500); background: #fff; }

html[data-design="classic"] .docs-new-page-btn, html[data-design="classic"] .docs-sb-new {
  display: block;
  padding: 8px 14px;
  background: var(--brand-500);
  color: #fff;
  border: none;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  width: calc(100% - 20px);
  margin: 4px 10px 8px;
  text-align: center;
  transition: opacity 0.15s;
}
html[data-design="classic"] .docs-new-page-btn:hover, html[data-design="classic"] .docs-sb-new:hover { opacity: 0.9; }

/* ── Sidebar Tree ────────────────────────────────────────────*/
html[data-design="classic"] .docs-tree {
  flex: 1;
  overflow-y: auto;
  padding: 0 8px 16px;
}
html[data-design="classic"] .docs-tree-label {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gray-400);
  padding: 8px 6px 4px;
}
html[data-design="classic"] .docs-tree-empty {
  font-size: 12px;
  color: var(--gray-400);
  padding: 6px 6px 4px;
  line-height: 1.6;
