html[data-design="classic"] .docs-tree-emoji { font-size: 14px; flex-shrink: 0; }
html[data-design="classic"] .docs-tree-name  { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 13px; }
html[data-design="classic"] .docs-tree-delete {
