html[data-design="classic"] .docs-tree-item:hover .docs-tree-delete { opacity: 1; }
html[data-design="classic"] .docs-tree-delete:hover { color: var(--danger); background: #fee2e2; }
html[data-design="classic"] .docs-tree-children { padding-left: 14px; }

html[data-design="classic"] .docs-search-row {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 6px 8px;
  border: none;
  background: none;
  border-radius: 6px;
  cursor: pointer;
  font-size: 13px;
  color: var(--gray-700);
  text-align: left;
