html[data-design="classic"] .docs-search-row:hover { background: var(--gray-100); }
html[data-design="classic"] .docs-search-row.active { background: rgba(99,102,241,0.1); color: var(--brand-500); font-weight: 600; }

/* ── Main Content ────────────────────────────────────────────*/
html[data-design="classic"] .docs-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: #f4f5f7;
  min-height: 0;
