  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  border-bottom: 1px solid #e8ecf0;
  background: #ffffff;
  gap: 8px;
  flex-shrink: 0;
  min-height: 46px;
}
html[data-design="classic"] .docs-topbar-right {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
