html[data-design="classic"] .docs-wc {
  font-size: 11px;
  color: var(--gray-400);
  margin-right: 6px;
  white-space: nowrap;
}
html[data-design="classic"] .docs-save-label {
  font-size: 11px;
  color: var(--gray-400);
  margin-right: 4px;
  white-space: nowrap;
}
html[data-design="classic"] .docs-save-label.saving { color: var(--warning); }
html[data-design="classic"] .docs-save-label.saved  { color: var(--success); }
html[data-design="classic"] .docs-history-btn {
  padding: 5px 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--gray-50);
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  color: var(--gray-600);
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: 4px;
  transition: all 0.12s;
}
html[data-design="classic"] .docs-history-btn:hover { background: var(--gray-100); border-color: var(--gray-300); color: var(--gray-800); }
html[data-design="classic"] .docs-btn-published { color: var(--success) !important; border-color: rgba(16,185,129,0.3) !important; background: rgba(16,185,129,0.06) !important; }

/* ── Breadcrumb ──────────────────────────────────────────────*/
html[data-design="classic"] .doc-breadcrumb {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  color: var(--gray-500);
  flex: 1;
  min-width: 0;
}
html[data-design="classic"] .doc-bc-root {
  background: none; border: none; cursor: pointer;
  font-size: 12px; color: var(--brand-500); padding: 0; font-weight: 600;
  display: flex; align-items: center; gap: 4px;
}
html[data-design="classic"] .doc-bc-root:hover { text-decoration: underline; }
html[data-design="classic"] .doc-bc-seg { display: flex; align-items: center; gap: 4px; }
html[data-design="classic"] .doc-bc-sep { color: var(--gray-300); }
html[data-design="classic"] .doc-bc-name { color: var(--gray-500); cursor: pointer; }
html[data-design="classic"] .doc-bc-name:hover { color: var(--brand-500); }
html[data-design="classic"] .doc-bc-current { color: var(--gray-800); font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 200px; }

/* ── Collab ──────────────────────────────────────────────────*/
html[data-design="classic"] .collab-presence-bar { display: flex; align-items: center; gap: -4px; }
html[data-design="classic"] .collab-avatar {
  width: 26px; height: 26px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 10px; font-weight: 800; color: #fff;
  border: 2px solid #fff; margin-left: -4px;
  cursor: default;
}
html[data-design="classic"] .collab-avatar-more { background: var(--gray-400); font-size: 9px; }
html[data-design="classic"] .collab-status {
  display: flex; align-items: center; gap: 4px;
  font-size: 11px; font-weight: 600; color: var(--success);
  background: rgba(16,185,129,0.08);
  padding: 3px 8px; border-radius: var(--radius-full);
  border: 1px solid rgba(16,185,129,0.2);
}
html[data-design="classic"] .collab-status-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--success); animation: classic-pulse 1.5s infinite;
}
@keyframes classic-pulse {
  0%, 100% { opacity: 1; } 50% { opacity: 0.4; }
}

/* ── Document Header ─────────────────────────────────────────*/
html[data-design="classic"] .docs-header {
  padding: 24px 48px 10px;
  max-width: 780px;
  display: flex;
  align-items: flex-start;
  gap: 10px;
  flex-shrink: 0;
}
html[data-design="classic"] .docs-title {
  flex: 1;
  font-size: 28px;
  font-weight: 800;
  border: none;
  outline: none;
  color: var(--gray-900);
  background: transparent;
  line-height: 1.25;
  padding: 0;
  font-family: inherit;
  width: 100%;
}
html[data-design="classic"] .docs-title::placeholder { color: var(--gray-300); }

/* ── Tags row ────────────────────────────────────────────────*/
html[data-design="classic"] .doc-tags-row {
  display: flex; align-items: center; gap: 6px;
  padding: 4px 24px 8px; flex-wrap: wrap; flex-shrink: 0;
}
html[data-design="classic"] .doc-tag-category-chip {
  padding: 2px 8px; border-radius: 4px;
  background: rgba(99,102,241,0.1); color: var(--brand-500);
  font-size: 11px; font-weight: 700;
}
html[data-design="classic"] .doc-tag-chip {
  font-size: 11px; padding: 2px 7px; border-radius: 4px;
  background: var(--gray-100); color: var(--gray-500);
}
html[data-design="classic"] .doc-tags-edit-btn {
  background: none; border: none; cursor: pointer;
  font-size: 13px; color: var(--gray-400); padding: 1px 4px; border-radius: 3px;
}
html[data-design="classic"] .doc-tags-edit-btn:hover { color: var(--brand-500); }

/* ── Format Bar ──────────────────────────────────────────────*/
html[data-design="classic"] .doc-format-bar {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 5px 20px;
  border-bottom: 1px solid #e8ecf0;
  background: #f8f9fb;
  flex-shrink: 0;
}
html[data-design="classic"] .doc-format-bar button {
  padding: 4px 9px;
  border: none;
  background: none;
  border-radius: 5px;
  cursor: pointer;
  font-size: 13px;
  color: var(--gray-600);
  transition: background 0.12s;
  line-height: 1.4;
  white-space: nowrap;
  font-family: inherit;
}
html[data-design="classic"] .doc-format-bar button:hover { background: #e8edf3; }
html[data-design="classic"] .doc-format-bar button.active { background: rgba(99,102,241,0.1); color: var(--brand-500); }
html[data-design="classic"] .doc-format-sep {
  width: 1px; height: 18px;
  background: var(--border); margin: 0 4px; flex-shrink: 0;
}
html[data-design="classic"] .doc-format-legend-btn {
  display: inline-flex; align-items: center; gap: 4px;
  font-size: 12px; color: var(--gray-500); padding: 4px 8px;
}
html[data-design="classic"] .doc-format-legend-btn kbd {
  font-size: 11px; background: var(--gray-100);
  border: 1px solid var(--border); border-radius: 3px;
  padding: 1px 4px; font-family: monospace;
}
html[data-design="classic"] .doc-format-legend-btn.active { color: var(--brand-500); }

/* ── Editor Body ─────────────────────────────────────────────*/
html[data-design="classic"] .docs-editor-body {
  flex: 1;
  overflow-y: auto !important;
  overflow-x: hidden;
  padding: 0 0 120px;
  background: #fff;
  min-height: 0;
  height: 0; /* forces flex child to scroll rather than grow */
}
/* Ensure no browser default styling on block inputs */
html[data-design="classic"] .docs-editor-body * {
  box-sizing: border-box;
}
html[data-design="classic"] .docs-editor-body input,
html[data-design="classic"] .docs-editor-body textarea,
html[data-design="classic"] .docs-editor-body [contenteditable] {
  outline: none;
  border: none;
  background: transparent;
}

html[data-design="classic"] .docs-blocks-wrap {
  width: 100%;
  max-width: 780px;
  padding: 8px 0 80px;
}

/* ── Blocks ──────────────────────────────────────────────────*/
html[data-design="classic"] .docs-block {
  position: relative;
  padding: 1px 0;
  border-radius: 4px;
  min-height: 26px;
}
html[data-design="classic"] .docs-block:hover { background: rgba(99,102,241,0.02); }
html[data-design="classic"] .docs-block-inner { outline: none; min-height: 22px; }
html[data-design="classic"] .docs-block-inner:focus { outline: none; }

/* Block types */
html[data-design="classic"] .docs-h1 { font-size: 22px; font-weight: 800; color: var(--gray-900); line-height: 1.3; padding: 4px 0 2px; }
html[data-design="classic"] .docs-h2 { font-size: 17px; font-weight: 700; color: var(--gray-800); line-height: 1.3; padding: 3px 0 2px; }
html[data-design="classic"] .docs-h3 { font-size: 14px; font-weight: 700; color: var(--gray-700); line-height: 1.4; padding: 2px 0; }
html[data-design="classic"] .docs-p  { font-size: 13px; line-height: 1.7; color: var(--gray-700); padding: 1px 0; }
html[data-design="classic"] .docs-blockquote {
  border-left: 3px solid var(--brand-500);
  padding-left: 14px; margin: 4px 0;
  color: var(--gray-500); font-style: italic; font-size: 14px; line-height: 1.7;
}
html[data-design="classic"] .docs-code-block {
  background: var(--gray-900); color: var(--border);
  padding: 14px 16px; border-radius: 8px;
  font-family: 'Menlo', 'Monaco', monospace; font-size: 13px;
  overflow-x: auto; white-space: pre-wrap; margin: 4px 0;
  line-height: 1.6;
}
html[data-design="classic"] .docs-divider { border: none; border-top: 2px solid var(--border); margin: 12px 0; }
html[data-design="classic"] .docs-callout {
  background: rgba(99,102,241,0.06);
  border: 1px solid rgba(99,102,241,0.2);
  border-radius: 8px; padding: 12px 14px; margin: 4px 0;
  font-size: 14px; line-height: 1.65;
}
html[data-design="classic"] .docs-todo { display: flex; align-items: flex-start; gap: 8px; font-size: 14px; line-height: 1.65; }
html[data-design="classic"] .docs-todo-check { margin-top: 3px; cursor: pointer; accent-color: var(--brand-500); flex-shrink: 0; }
html[data-design="classic"] .docs-todo-text { flex: 1; }
html[data-design="classic"] .docs-todo-text.done { text-decoration: line-through; color: var(--gray-400); }
html[data-design="classic"] .docs-bullet  { font-size: 14px; line-height: 1.7; padding: 1px 0; }
html[data-design="classic"] .docs-numbered{ font-size: 14px; line-height: 1.7; padding: 1px 0; }

/* Add block hint */
html[data-design="classic"] .doc-add-block-hint {
  padding: 10px 0 4px;
  font-size: 13px;
  color: var(--gray-300);
  cursor: pointer;
  user-select: none;
  transition: color 0.12s;
}
html[data-design="classic"] .doc-add-block-hint:hover { color: var(--gray-400); }

/* ── Empty state ─────────────────────────────────────────────*/
html[data-design="classic"] .docs-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  text-align: center;
  padding: 40px 32px;
  background: #fff;
  gap: 14px;
}
html[data-design="classic"] .docs-empty-icon { font-size: 56px; line-height: 1; }
html[data-design="classic"] .docs-empty-state h2 { font-size: 24px; font-weight: 800; color: var(--gray-800); margin: 0; }
html[data-design="classic"] .docs-empty-state p  { font-size: 14px; color: var(--gray-500); margin: 0; line-height: 1.6; max-width: 380px; }

html[data-design="classic"] .docs-tpl-shortcuts {
  display: flex; flex-wrap: wrap; gap: 8px;
  justify-content: center; margin-top: 4px;
}
html[data-design="classic"] .docs-tpl-shortcut, html[data-design="classic"] .docs-tpl-btn {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 7px 14px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--gray-50);
  font-size: 12px; font-weight: 500;
  color: var(--gray-600); cursor: pointer;
  transition: all 0.12s;
}
html[data-design="classic"] .docs-tpl-shortcut:hover, html[data-design="classic"] .docs-tpl-btn:hover {
  border-color: var(--brand-500); color: var(--brand-500); background: rgba(99,102,241,0.04);
}

html[data-design="classic"] .docs-select-state {
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  height: 100%; text-align: center; padding: 40px;
  color: var(--gray-400); font-size: 14px; background: #fff;
}
html[data-design="classic"] .docs-select-icon { font-size: 40px; margin-bottom: 12px; }
html[data-design="classic"] .docs-select-list { display: flex; flex-direction: column; gap: 6px; margin-top: 16px; width: 100%; max-width: 300px; }
html[data-design="classic"] .docs-select-item {
  padding: 8px 12px; border: 1px solid var(--border); border-radius: 6px;
  cursor: pointer; font-size: 13px; color: var(--gray-700); text-align: left;
  background: none; transition: background 0.12s;
}
html[data-design="classic"] .docs-select-item:hover { background: var(--gray-100); }

/* ── Template Picker Modal ───────────────────────────────────*/
html[data-design="classic"] .doc-tpl-modal {
  background: #fff;
  border-radius: 16px;
  padding: 28px;
  width: 100%;
  max-width: 560px;
  box-shadow: 0 20px 60px rgba(0,0,0,0.15);
  margin: 0 16px;
}
html[data-design="classic"] .doc-tpl-modal-header {
  display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px;
}
html[data-design="classic"] .doc-tpl-modal-header h2 { margin: 0; font-size: 20px; font-weight: 800; color: var(--gray-900); }
html[data-design="classic"] .doc-tpl-close {
  background: none; border: none; cursor: pointer;
  font-size: 16px; color: var(--gray-400); padding: 4px 8px; border-radius: 6px;
}
html[data-design="classic"] .doc-tpl-close:hover { background: var(--gray-100); }
html[data-design="classic"] .doc-tpl-sub { font-size: 13px; color: var(--gray-500); margin: 0 0 20px; }
html[data-design="classic"] .doc-tpl-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(110px, 1fr));
  gap: 10px;
}
html[data-design="classic"] .doc-tpl-card {
  display: flex; flex-direction: column; align-items: center; gap: 8px;
  padding: 18px 10px;
  background: var(--gray-50);
  border: 1.5px solid var(--border);
  border-radius: 10px; cursor: pointer;
  transition: all 0.15s; text-align: center; min-width: 0;
}
html[data-design="classic"] .doc-tpl-card:hover { border-color: var(--brand-500); background: rgba(99,102,241,0.05); }
html[data-design="classic"] .doc-tpl-emoji { font-size: 26px; line-height: 1; }
html[data-design="classic"] .doc-tpl-card span:last-child {
  font-size: 11px; font-weight: 600; color: var(--gray-700);
  word-break: break-word; overflow-wrap: break-word;
  white-space: normal; display: block; width: 100%; line-height: 1.3;
}
html[data-design="classic"] .doc-tpl-card:hover span:last-child { color: var(--brand-500); }

/* ── Task / Goal Embed ───────────────────────────────────────*/
html[data-design="classic"] .doc-task-embed {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 14px; border: 1px solid var(--border);
  border-radius: 8px; background: var(--gray-50); margin: 4px 0;
}
html[data-design="classic"] .doc-task-embed-icon { font-size: 18px; flex-shrink: 0; }
html[data-design="classic"] .doc-task-embed-info { flex: 1; min-width: 0; }
html[data-design="classic"] .doc-task-embed-title { font-size: 13px; font-weight: 600; color: var(--gray-800); }
html[data-design="classic"] .doc-task-embed-status { font-size: 11px; color: var(--gray-400); margin-top: 2px; }
html[data-design="classic"] .doc-task-embed-remove {
  background: none; border: none; cursor: pointer;
  font-size: 14px; color: var(--gray-400); padding: 2px 4px; border-radius: 3px;
}
html[data-design="classic"] .doc-task-embed-remove:hover { color: var(--danger); }
html[data-design="classic"] .doc-task-embed--missing { border-color: #fecaca; background: #fff5f5; color: var(--danger); }
html[data-design="classic"] .doc-goal-embed { border-color: rgba(99,102,241,0.2); background: rgba(99,102,241,0.03); }
html[data-design="classic"] .doc-goal-progress-bar { height: 4px; background: var(--border); border-radius: 2px; margin: 4px 0; }
html[data-design="classic"] .doc-goal-progress-fill { height: 100%; background: var(--brand-500); border-radius: 2px; }

/* ── Task Picker ─────────────────────────────────────────────*/
html[data-design="classic"] .task-picker-overlay {
  position: fixed; inset: 0; z-index: 9999;
  background: rgba(0,0,0,0.3);
  display: flex; align-items: center; justify-content: center;
}
html[data-design="classic"] .task-picker {
  background: #fff; border-radius: 12px;
  width: 400px; max-height: 480px;
  display: flex; flex-direction: column;
  box-shadow: 0 20px 60px rgba(0,0,0,0.15); overflow: hidden;
}
html[data-design="classic"] .task-picker-header {
  padding: 14px 16px; font-weight: 700; font-size: 14px;
  border-bottom: 1px solid var(--border); color: var(--gray-800);
}
html[data-design="classic"] .task-picker-search {
  padding: 10px 16px; border: none;
  border-bottom: 1px solid var(--border);
  font-size: 14px; outline: none; width: 100%; box-sizing: border-box;
}
html[data-design="classic"] .task-picker-list { flex: 1; overflow-y: auto; padding: 6px; }
html[data-design="classic"] .task-picker-item {
  display: flex; align-items: center; gap: 8px;
  padding: 8px 10px; border-radius: 6px; cursor: pointer;
  font-size: 13px; color: var(--gray-700);
}
html[data-design="classic"] .task-picker-item:hover { background: var(--gray-100); }
html[data-design="classic"] .task-picker-item-title { flex: 1; }
html[data-design="classic"] .task-picker-item-status {
  font-size: 11px; color: var(--gray-400);
  background: var(--gray-100); padding: 1px 6px; border-radius: 4px;
}
html[data-design="classic"] .task-picker-empty { padding: 16px; text-align: center; color: var(--gray-400); font-size: 13px; }

/* ── Publish Panel ───────────────────────────────────────────*/
html[data-design="classic"] .doc-publish-panel {
  margin: 0 16px 8px;
  padding: 14px 16px;
  background: var(--gray-50);
  border: 1px solid var(--border);
  border-radius: 10px;
  flex-shrink: 0;
}
html[data-design="classic"] .doc-publish-title { font-size: 13px; font-weight: 700; margin-bottom: 10px; color: var(--gray-800); }
html[data-design="classic"] .doc-publish-options { display: flex; gap: 6px; margin-bottom: 10px; }
html[data-design="classic"] .doc-publish-opt {
  padding: 6px 14px; border: 1px solid var(--border); border-radius: 6px;
  background: #fff; font-size: 12px; cursor: pointer; font-weight: 500; color: var(--gray-500);
  transition: all 0.12s;
}
html[data-design="classic"] .doc-publish-opt:hover { border-color: var(--brand-500); color: var(--brand-500); }
html[data-design="classic"] .doc-publish-opt.active { background: var(--brand-500); color: #fff; border-color: var(--brand-500); }
html[data-design="classic"] .doc-publish-link-label { font-size: 11px; color: var(--gray-400); display: block; margin-bottom: 6px; }
html[data-design="classic"] .doc-publish-link-row { display: flex; align-items: center; gap: 8px; }
html[data-design="classic"] .doc-publish-slug {
  font-size: 11px; background: #fff; border: 1px solid var(--border);
  border-radius: 4px; padding: 4px 8px; flex: 1; font-family: monospace;
}
html[data-design="classic"] .doc-publish-copy-btn {
  padding: 5px 10px; background: var(--brand-500); color: #fff;
  border: none; border-radius: 5px; cursor: pointer;
  font-size: 11px; font-weight: 600;
}

/* ── Tags Panel ──────────────────────────────────────────────*/
html[data-design="classic"] .doc-tag-panel {
  position: fixed; right: 0; top: 56px; bottom: 0;
  width: 260px; background: #fff;
  border-left: 1px solid var(--border);
  display: flex; flex-direction: column;
  z-index: 200; box-shadow: -4px 0 20px rgba(0,0,0,0.06);
}
html[data-design="classic"] .doc-tag-panel-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 16px; border-bottom: 1px solid var(--border);
  font-weight: 700; font-size: 14px; color: var(--gray-800);
}
html[data-design="classic"] .doc-tag-panel-close { background: none; border: none; cursor: pointer; font-size: 16px; color: var(--gray-400); }
html[data-design="classic"] .doc-tag-panel-body { flex: 1; overflow-y: auto; padding: 12px; }
html[data-design="classic"] .doc-tag-panel-footer { padding: 12px; border-top: 1px solid var(--border); }
html[data-design="classic"] .doc-tag-current { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 12px; }
html[data-design="classic"] .doc-tag-category-badge {
  padding: 3px 8px; border-radius: 4px;
  background: rgba(99,102,241,0.1); color: var(--brand-500);
  font-size: 11px; font-weight: 600;
}
html[data-design="classic"] .doc-tag-badge {
  padding: 3px 8px; border-radius: 4px;
  background: var(--gray-100); color: var(--gray-500); font-size: 11px;
}

/* ── Backlinks ───────────────────────────────────────────────*/
html[data-design="classic"] .doc-backlinks { padding: 10px 16px; border-top: 1px solid var(--gray-100); flex-shrink: 0; }
html[data-design="classic"] .doc-backlinks-header { display: flex; align-items: center; gap: 6px; margin-bottom: 6px; }
html[data-design="classic"] .doc-backlinks-icon { font-size: 14px; }
html[data-design="classic"] .doc-backlinks-label { font-size: 12px; font-weight: 600; color: var(--gray-500); }
html[data-design="classic"] .doc-backlinks-list { display: flex; flex-direction: column; gap: 3px; }
html[data-design="classic"] .doc-backlink-item { font-size: 12px; color: var(--brand-500); cursor: pointer; padding: 2px 0; background: none; border: none; text-align: left; }
html[data-design="classic"] .doc-backlink-item:hover { text-decoration: underline; }

/* ── Wiki chip & menu ────────────────────────────────────────*/
html[data-design="classic"] .doc-wiki-chip {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 1px 7px; border-radius: 4px;
  background: rgba(99,102,241,0.1); color: var(--brand-500);
  font-size: 13px; cursor: pointer; border: 1px solid rgba(99,102,241,0.2);
  text-decoration: none;
}
html[data-design="classic"] .doc-wiki-chip--broken { background: rgba(239,68,68,0.08); color: var(--danger); border-color: rgba(239,68,68,0.2); }
html[data-design="classic"] .doc-wiki-menu {
  position: fixed; z-index: 9999;
  background: #fff; border: 1px solid var(--border);
