html[data-design="classic"] .doc-wiki-emoji { font-size: 16px; }
html[data-design="classic"] .doc-wiki-title { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
html[data-design="classic"] .doc-wiki-empty { padding: 12px; font-size: 12px; color: var(--gray-400); text-align: center; }

/* ── Slash legend ────────────────────────────────────────────*/
html[data-design="classic"] .doc-slash-legend {
  position: absolute; z-index: 500;
  background: #fff; border: 1px solid var(--border);
  border-radius: 10px; padding: 10px;
  width: 240px; box-shadow: 0 8px 24px rgba(0,0,0,0.1);
  max-height: 300px; overflow-y: auto; flex-shrink: 0;
}
html[data-design="classic"] .doc-slash-legend-title {
  font-size: 10px; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.07em; color: var(--gray-400); margin-bottom: 6px; padding: 0 4px;
}
html[data-design="classic"] .doc-slash-item {
  display: flex; align-items: center; gap: 8px;
  padding: 6px 8px; border-radius: 6px; cursor: pointer; font-size: 12px; color: var(--gray-700);
}
html[data-design="classic"] .doc-slash-item:hover { background: var(--gray-100); }
html[data-design="classic"] .doc-slash-item-icon { font-size: 15px; flex-shrink: 0; width: 22px; text-align: center; }
html[data-design="classic"] .doc-slash-item-label { font-weight: 600; }
html[data-design="classic"] .doc-slash-item-desc  { font-size: 10px; color: var(--gray-400); }

/* ── Version history ─────────────────────────────────────────*/
html[data-design="classic"] .doc-vh-body { display: flex; flex-direction: column; gap: 8px; max-height: 380px; overflow-y: auto; }
html[data-design="classic"] .doc-vh-preview-content {
  background: var(--gray-50); border: 1px solid var(--border);
  border-radius: 8px; padding: 16px; font-size: 13px;
  max-height: 280px; overflow-y: auto; line-height: 1.6;
}

/* ── Image block ─────────────────────────────────────────────*/
html[data-design="classic"] .doc-img { max-width: 100%; border-radius: 8px; display: block; margin: 4px 0; }

/* ── Inline comment panel ────────────────────────────────────*/
html[data-design="classic"] .doc-inline-comments-panel {
  width: 280px; flex-shrink: 0;
  border-left: 1px solid var(--border);
  background: #fff; overflow-y: auto;
  padding: 12px;
}
html[data-design="classic"] .doc-inline-comment { padding: 10px; border-radius: 8px; background: var(--gray-50); margin-bottom: 8px; border: 1px solid var(--border); }
html[data-design="classic"] .doc-inline-comment-author { font-size: 11px; font-weight: 700; color: var(--gray-800); margin-bottom: 4px; }
html[data-design="classic"] .doc-inline-comment-text { font-size: 12px; color: var(--gray-600); line-height: 1.5; }

/* ── Doc task picker (inline) ────────────────────────────────*/
html[data-design="classic"] .doc-task-picker {
  position: absolute; z-index: 100;
  background: #fff; border: 1px solid var(--border);
  border-radius: 10px; width: 300px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.1); overflow: hidden;
}
html[data-design="classic"] .doc-task-picker-header {
  padding: 10px 12px; font-size: 12px; font-weight: 700;
  color: var(--gray-500); border-bottom: 1px solid var(--border);
}
html[data-design="classic"] .doc-task-picker-search {
  width: 100%; padding: 8px 12px; border: none;
  border-bottom: 1px solid var(--border); font-size: 13px; outline: none; box-sizing: border-box;
}
html[data-design="classic"] .doc-task-picker-list { max-height: 200px; overflow-y: auto; }
html[data-design="classic"] .doc-task-picker-item { display: flex; align-items: center; gap: 8px; padding: 7px 12px; cursor: pointer; font-size: 13px; }
html[data-design="classic"] .doc-task-picker-item:hover { background: var(--gray-100); }
html[data-design="classic"] .doc-task-picker-dot { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; }
html[data-design="classic"] .doc-task-picker-title { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
html[data-design="classic"] .doc-task-picker-status { font-size: 11px; color: var(--gray-400); }
html[data-design="classic"] .doc-task-picker-empty { padding: 12px; text-align: center; font-size: 12px; color: var(--gray-400); }

/* ── Spinner ─────────────────────────────────────────────────*/
html[data-design="classic"] .docs-spinner {
  width: 32px; height: 32px; margin: 60px auto;
  border: 3px solid var(--border);
  border-top-color: var(--brand-500);
  border-radius: 50%;
  animation: classic-docs-spin 0.7s linear infinite;
}
@keyframes classic-docs-spin { to { transform: rotate(360deg); } }

/* ── DB block ────────────────────────────────────────────────*/
html[data-design="classic"] .doc-db-title { font-size: 16px; font-weight: 700; color: var(--gray-800); display: block; outline: none; margin-bottom: 8px; }
html[data-design="classic"] .doc-db-table-wrap { overflow-x: auto; }

/* ── Dark mode ───────────────────────────────────────────────*/
html[data-design="classic"][data-theme="dark"] .docs-page,
html[data-design="classic"][data-theme="dark"] .docs-sidebar  { background: #0f1117; border-color: #2d3548; }
html[data-design="classic"][data-theme="dark"] .docs-sb-header,
html[data-design="classic"][data-theme="dark"] .docs-editor-wrap,
html[data-design="classic"][data-theme="dark"] .docs-topbar,
html[data-design="classic"][data-theme="dark"] .docs-header,
html[data-design="classic"][data-theme="dark"] .docs-editor-body,
html[data-design="classic"][data-theme="dark"] .docs-empty-state,
html[data-design="classic"][data-theme="dark"] .docs-select-state { background: #1a1f2e; border-color: #2d3548; }
html[data-design="classic"][data-theme="dark"] .doc-format-bar { background: #161b27; border-color: #2d3548; }
html[data-design="classic"][data-theme="dark"] .doc-format-bar button { color: var(--gray-400); }
html[data-design="classic"][data-theme="dark"] .doc-format-bar button:hover { background: #252b3b; }
html[data-design="classic"][data-theme="dark"] .docs-tree-item { color: var(--gray-300); }
html[data-design="classic"][data-theme="dark"] .docs-tree-item:hover { background: #252b3b; }
html[data-design="classic"][data-theme="dark"] .docs-tree-item--active { background: rgba(99,102,241,0.15); }
html[data-design="classic"][data-theme="dark"] .docs-title { color: var(--border); }
html[data-design="classic"][data-theme="dark"] .docs-h1, html[data-design="classic"][data-theme="dark"] .docs-h2 { color: var(--border); }
html[data-design="classic"][data-theme="dark"] .docs-p, html[data-design="classic"][data-theme="dark"] .docs-h3 { color: var(--gray-300); }
html[data-design="classic"][data-theme="dark"] .doc-task-embed { background: #252b3b; border-color: #2d3548; }
html[data-design="classic"][data-theme="dark"] .doc-tpl-modal { background: #1a1f2e; }
html[data-design="classic"][data-theme="dark"] .doc-tpl-card { background: #252b3b; border-color: #2d3548; }

/* ── Tree Node (doc-tree-*) ─────────────────────────────────*/
html[data-design="classic"] .doc-tree-row {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 5px 4px;
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.1s;
  user-select: none;
  width: 100%;
  box-sizing: border-box;
  position: relative;
  overflow: hidden;
}
html[data-design="classic"] .doc-tree-row:hover {
  background: var(--gray-100);
  overflow: visible;
}
html[data-design="classic"] .doc-tree-row--active { background: rgba(99,102,241,0.1); }
html[data-design="classic"] .doc-tree-row--active:hover { background: rgba(99,102,241,0.15); }

html[data-design="classic"] .doc-tree-chevron {
  background: none; border: none; cursor: pointer;
  font-size: 10px; color: var(--gray-400); padding: 0 2px;
  width: 14px; flex-shrink: 0; line-height: 1;
}
html[data-design="classic"] .doc-tree-chevron:hover { color: var(--gray-600); }

html[data-design="classic"] .doc-tree-icon { font-size: 13px; flex-shrink: 0; }

html[data-design="classic"] .doc-tree-name {
  flex: 1;
  font-size: 12px;
  color: var(--gray-700);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 500;
  min-width: 0;
}
html[data-design="classic"] .doc-tree-row--active .doc-tree-name { color: var(--brand-500); font-weight: 600; }

/* Buttons: hidden by default, shown on hover as a floating pill */
html[data-design="classic"] .doc-tree-btns {
  display: none;
  position: absolute;
  right: 4px;
  top: 50%;
  transform: translateY(-50%);
  align-items: center;
  gap: 1px;
  background: var(--gray-100);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 2px 3px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.08);
  z-index: 10;
}
html[data-design="classic"] .doc-tree-row:hover .doc-tree-btns { display: flex; }

html[data-design="classic"] .doc-tree-btns button {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 12px;
  color: var(--gray-500);
  padding: 2px 5px;
  border-radius: 4px;
  line-height: 1;
  transition: all 0.1s;
  white-space: nowrap;
}
html[data-design="classic"] .doc-tree-btns button:hover { background: var(--border); color: var(--gray-800); }

/* ── Slash Command Legend Modal ─────────────────────────────*/
html[data-design="classic"] .slash-legend-overlay {
  position: fixed;
  inset: 0;
  z-index: 9998;
  background: rgba(0,0,0,0.35);
  display: flex;
  align-items: center;
  justify-content: center;
}
html[data-design="classic"] .slash-legend-panel {
  background: #fff;
  border-radius: 14px;
  width: 100%;
  max-width: 560px;
  max-height: 80vh;
  margin: 0 16px;
  box-shadow: 0 20px 60px rgba(0,0,0,0.18);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
html[data-design="classic"] .slash-legend-header {
  padding: 18px 20px 12px;
  border-bottom: 1px solid var(--gray-100);
  flex-shrink: 0;
}
html[data-design="classic"] .slash-legend-title {
  font-size: 16px;
  font-weight: 800;
  color: var(--gray-900);
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 4px;
}
html[data-design="classic"] .slash-legend-title kbd {
  font-size: 13px;
  background: var(--gray-100);
  border: 1px solid var(--border);
  border-radius: 5px;
  padding: 2px 7px;
  font-family: monospace;
  color: var(--brand-500);
}
html[data-design="classic"] .slash-legend-subtitle {
  font-size: 12px;
  color: var(--gray-400);
  display: flex;
  align-items: center;
  gap: 4px;
}
html[data-design="classic"] .slash-legend-subtitle kbd {
  font-size: 11px;
  background: var(--gray-50);
  border: 1px solid var(--border);
  border-radius: 3px;
  padding: 1px 5px;
  font-family: monospace;
}
html[data-design="classic"] .slash-legend-close {
  position: absolute;
  top: 16px; right: 16px;
  background: var(--gray-100); border: none;
  border-radius: 6px; cursor: pointer;
  font-size: 14px; color: var(--gray-500);
  padding: 4px 8px;
}
html[data-design="classic"] .slash-legend-close:hover { background: var(--border); color: var(--gray-800); }
html[data-design="classic"] .slash-legend-header { position: relative; }

html[data-design="classic"] .slash-legend-body {
  overflow-y: auto;
  padding: 12px 16px 16px;
}
html[data-design="classic"] .slash-legend-group { margin-bottom: 16px; }
html[data-design="classic"] .slash-legend-group:last-child { margin-bottom: 0; }
html[data-design="classic"] .slash-legend-group-label {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gray-400);
  padding: 0 4px;
  margin-bottom: 6px;
}
html[data-design="classic"] .slash-legend-items {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 4px;
}
html[data-design="classic"] .slash-legend-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.12s;
}
html[data-design="classic"] .slash-legend-item:hover { background: var(--gray-50); }
html[data-design="classic"] .slash-legend-icon {
  width: 32px; height: 32px;
  background: var(--gray-100);
  border-radius: 6px;
  display: flex; align-items: center; justify-content: center;
  font-size: 14px; font-weight: 700; color: var(--gray-600);
  flex-shrink: 0;
}
html[data-design="classic"] .slash-legend-info { flex: 1; min-width: 0; }
html[data-design="classic"] .slash-legend-item-label { font-size: 13px; font-weight: 600; color: var(--gray-800); }
html[data-design="classic"] .slash-legend-item-desc  { font-size: 11px; color: var(--gray-400); margin-top: 1px; }
html[data-design="classic"] .slash-legend-cmd {
  font-size: 10px;
  background: var(--gray-100);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 2px 6px;
  font-family: monospace;
  color: var(--brand-500);
  flex-shrink: 0;
  white-space: nowrap;
}

/* ── Inline slash menu (while typing /) ─────────────────────*/
html[data-design="classic"] .doc-slash-menu {
  position: fixed;
  z-index: 9999;
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 10px;
  width: 220px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.12);
  overflow: hidden;
  max-height: 280px;
  overflow-y: auto;
}
html[data-design="classic"] .doc-slash-menu-label {
  padding: 8px 12px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--gray-400);
  border-bottom: 1px solid var(--gray-100);
}
html[data-design="classic"] .doc-slash-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 12px;
  cursor: pointer;
  font-size: 13px;
  transition: background 0.1s;
}
html[data-design="classic"] .doc-slash-item:hover, html[data-design="classic"] .doc-slash-item--active { background: var(--gray-100); }
html[data-design="classic"] .doc-slash-icon {
  width: 28px; height: 28px;
  background: var(--gray-50); border: 1px solid var(--border);
  border-radius: 5px;
  display: flex; align-items: center; justify-content: center;
  font-size: 13px; font-weight: 700; color: var(--gray-600);
  flex-shrink: 0;
}
html[data-design="classic"] .doc-slash-text { flex: 1; min-width: 0; }
html[data-design="classic"] .doc-slash-name { font-size: 13px; font-weight: 600; color: var(--gray-800); display: block; }
html[data-design="classic"] .doc-slash-hint { font-size: 11px; color: var(--gray-400); display: block; }

/* ── Editor content column centering ────────────────────────*/
html[data-design="classic"] .docs-editor-content-col {
  max-width: 740px;
  margin: 0 auto;
  padding: 0 48px;
  width: 100%;
  box-sizing: border-box;
}

/* ── Add block button ────────────────────────────────────────*/
html[data-design="classic"] .doc-add-block-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 0;
  font-size: 13px;
  color: var(--gray-300);
  cursor: pointer;
  border: none;
  background: none;
  width: 100%;
  text-align: left;
  transition: color 0.12s;
  border-radius: 6px;
}
html[data-design="classic"] .doc-add-block-btn:hover { color: var(--gray-400); }
html[data-design="classic"] .doc-add-block-btn::before {
  content: '+';
  font-size: 16px;
  line-height: 1;
  color: var(--gray-300);
}

/* ── Sidebar improvements ────────────────────────────────────*/
html[data-design="classic"] .docs-sidebar {
  background: var(--gray-50);
}

/* Better page list feel */
html[data-design="classic"] .docs-tree {
  padding: 4px 8px 16px;
}

/* Emoji picker in sidebar */
html[data-design="classic"] .docs-emoji-mini {
  font-size: 14px;
  flex-shrink: 0;
  width: 20px;
  text-align: center;
}

/* ── Editor area ────────────────────────────────────────────*/

/* Topbar polish */
html[data-design="classic"] .docs-topbar {
  background: #fff;
  box-shadow: 0 1px 0 #e8ecf0;
}

/* Title area */
html[data-design="classic"] .docs-title {
  caret-color: var(--brand-500);
  font-size: 24px;
  font-weight: 800;
  line-height: 1.3;
}
html[data-design="classic"] .docs-title:focus { outline: none; }



/* Tags row in editor */
html[data-design="classic"] .doc-tags-row {
  padding: 2px 48px 8px;
  display: flex; align-items: center; gap: 6px; flex-wrap: wrap; flex-shrink: 0;
}

/* ── doc-block (used directly in Docs.jsx) ──────────────────*/
html[data-design="classic"] .doc-block {
  position: relative;
  padding: 2px 48px;
  min-height: 26px;
  max-width: 780px;
}
html[data-design="classic"] .doc-block:hover { background: rgba(99,102,241,0.02); }

/* Block actions — hide by default, show on hover */
html[data-design="classic"] .doc-block-actions {
  position: absolute;
  right: 48px;
  top: 50%;
  transform: translateY(-50%);
  display: none;
  align-items: center;
  gap: 2px;
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 2px 4px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.08);
  z-index: 10;
}
html[data-design="classic"] .doc-block:hover .doc-block-actions { display: flex; }
html[data-design="classic"] .doc-block-actions button {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 12px;
  color: var(--gray-400);
  padding: 3px 5px;
  border-radius: 4px;
  line-height: 1;
  transition: all 0.1s;
}
html[data-design="classic"] .doc-block-actions button:hover { background: var(--gray-100); color: var(--gray-700); }
html[data-design="classic"] .doc-block--focused { background: rgba(99,102,241,0.03); }

/* ── Remove browser focus outlines from contentEditable ─────*/
html[data-design="classic"] .doc-block [contenteditable],
html[data-design="classic"] .doc-block-inner[contenteditable],
html[data-design="classic"] .docs-block-inner[contenteditable],
html[data-design="classic"] .docs-editor-body [contenteditable] {
  outline: none !important;
  border: none !important;
  box-shadow: none !important;
}
html[data-design="classic"] [contenteditable]:focus {
  outline: none !important;
}

/* ── Block input (contentEditable) ──────────────────────────*/
html[data-design="classic"] .doc-block-input {
  outline: none !important;
  border: none !important;
  box-shadow: none !important;
  background: transparent;
  width: 100%;
  min-height: 22px;
  font-size: 13px;
  line-height: 1.7;
  color: var(--gray-700);
  caret-color: var(--brand-500);
  word-break: break-word;
  white-space: pre-wrap;
  overflow: visible;
}
html[data-design="classic"] .doc-block-input:focus {
  outline: none !important;
  border: none !important;
  box-shadow: none !important;
}
html[data-design="classic"] .doc-block-input:empty::before {
  content: attr(data-placeholder);
  color: var(--gray-300);
  pointer-events: none;
}

/* Override any global input/focus styles for doc blocks */
html[data-design="classic"] .doc-block .doc-block-input:focus,
html[data-design="classic"] .doc-block .doc-block-input:focus-visible {
  outline: none !important;
  border: none !important;
  box-shadow: none !important;
  ring: none !important;
}

/* ── Sidebar Tree Items ──────────────────────────────────── */
html[data-design="classic"] .doc-tree-item-row {
  display: flex;
  flex-direction: column;
  padding: 5px 8px;
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.1s;
  user-select: none;
  gap: 4px;
}
html[data-design="classic"] .doc-tree-item-row:hover { background: var(--gray-100); }

html[data-design="classic"] .doc-tree-item-top {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
}
html[data-design="classic"] .doc-tree-chevron-btn {
  background: none; border: none; cursor: pointer;
  font-size: 10px; color: var(--gray-400);
  width: 12px; flex-shrink: 0; padding: 0;
  line-height: 1; text-align: center;
}
html[data-design="classic"] .doc-tree-item-icon { font-size: 13px; flex-shrink: 0; }
html[data-design="classic"] .doc-tree-item-name {
  flex: 1;
  font-size: 12px;
  font-weight: 500;
  color: var(--gray-700);
  white-space: normal;
  word-break: break-word;
  line-height: 1.4;
}
html[data-design="classic"] .doc-tree-item-name.active { color: var(--brand-500); font-weight: 600; }

/* Action buttons: always visible on hover row */
html[data-design="classic"] .doc-tree-item-actions {
  display: flex;
  align-items: center;
  gap: 4px;
