html[data-design="classic"] .ma2-main .ma-card + .ma-card { margin-top: 0; }

/* Cards: flat, same language as the rest of the app */
html[data-design="classic"] .ma2-page .ma-card { border-radius: var(--radius-lg); box-shadow: none; padding: 20px 22px; background: var(--bg-card, #fff); }
html[data-design="classic"] .ma2-page .ma-card h2 { font-size: 16px; font-weight: 700; margin: 0 0 6px; }
html[data-design="classic"] .ma2-page .ma-btn { border-width: 1px; border-radius: var(--radius-md); font-weight: 600; min-height: 34px; padding: 0 14px; display: inline-flex; align-items: center; gap: 6px; }
