html[data-design="classic"] .ma2-page .ma-btn.danger { color: var(--danger-text); border-color: #F5C2BC; background: var(--bg-card, #fff); }
html[data-design="classic"] .ma2-page .ma-field input[type="text"], html[data-design="classic"] .ma2-page .ma-field input[type="url"], html[data-design="classic"] .ma2-page .ma-field input[type="datetime-local"], html[data-design="classic"] .ma2-page .ma-field select { border-width: 1px; border-radius: var(--radius-md); }
html[data-design="classic"] .ma2-page .ma-field label, html[data-design="classic"] .ma2-page .ma-legend { color: var(--text-secondary); font-weight: 600; font-size: 12.5px; }
html[data-design="classic"] .ma2-page .ma-hint { color: var(--text-muted); font-size: 12.5px; }
html[data-design="classic"] .ma2-page .ma-banner { border-radius: var(--radius-md); align-items: flex-start; margin-bottom: 14px; background: var(--warning-soft); border-color: #F3D9A8; color: var(--text-primary); }
