/* Your meetings */
html[data-design="classic"] .ma2-list { position: sticky; top: 0; }
html[data-design="classic"] .ma2-list .pg-section-title { margin-bottom: 10px; }
html[data-design="classic"] .ma2-list .ma-list { gap: 6px; }
html[data-design="classic"] .ma2-list .ma-row { border-width: 1px; border-radius: var(--radius-md); padding: 10px 12px; background: var(--bg-card, #fff); display: flex; flex-direction: column; gap: 4px; }
html[data-design="classic"] .ma2-list .ma-row:hover { border-color: var(--border-strong); }
