/* ── Meeting Continuity panel ─────────────────────────────────── */
html[data-design="classic"] .cont-panel {
  background: var(--gray-50, var(--gray-50));
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 14px 16px;
  margin-bottom: 14px;
}
html[data-design="classic"] .cont-panel-header { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 8px; margin-bottom: 8px; }
html[data-design="classic"] .cont-panel-title  { font-size: 14px; font-weight: 700; color: var(--gray-800); }
html[data-design="classic"] .cont-chips { display: flex; gap: 6px; flex-wrap: wrap; }
html[data-design="classic"] .cont-chip {
  font-size: 11px; font-weight: 700; padding: 3px 8px; border-radius: var(--radius-full);
  background: var(--gray-200, var(--border)); color: var(--gray-700, var(--gray-700));
}
html[data-design="classic"] .cont-chip--danger { background: rgba(239,68,68,0.12); color: var(--danger); }
html[data-design="classic"] .cont-chip--warn   { background: rgba(245,158,11,0.12); color: #b45309; }

html[data-design="classic"] .cont-empty { padding: 14px 4px; color: var(--gray-500); font-size: 13px; text-align: center; }

html[data-design="classic"] .cont-section { margin-top: 10px; }
html[data-design="classic"] .cont-section-label { font-size: 12px; font-weight: 700; color: var(--gray-500); margin-bottom: 6px; }

html[data-design="classic"] .cont-row { display: flex; align-items: flex-start; gap: 8px; padding: 6px 4px; border-bottom: 1px solid var(--border); }
html[data-design="classic"] .cont-row:last-child { border-bottom: none; }
html[data-design="classic"] .cont-row--overdue { background: rgba(239,68,68,0.05); border-radius: 6px; }
html[data-design="classic"] .cont-row-dot { width: 8px; height: 8px; border-radius: 50%; margin-top: 4px; flex-shrink: 0; }
html[data-design="classic"] .cont-row-body { flex: 1; min-width: 0; }
html[data-design="classic"] .cont-row-title { font-size: 13px; font-weight: 500; color: var(--gray-700); display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
html[data-design="classic"] .cont-row-meta  { font-size: 11px; color: var(--gray-400); display: flex; gap: 8px; margin-top: 2px; flex-wrap: wrap; }
html[data-design="classic"] .cont-overdue-text { color: var(--danger); font-weight: 600; }
html[data-design="classic"] .cont-row-actions { display: flex; gap: 4px; flex-shrink: 0; }

html[data-design="classic"] .cont-btn {
  font-size: 11px; font-weight: 600; padding: 3px 8px; border-radius: 6px;
  border: 1px solid var(--border); background: #fff; color: var(--gray-600);
  cursor: pointer; white-space: nowrap;
}
html[data-design="classic"] .cont-btn:hover { background: var(--gray-100); }
html[data-design="classic"] .cont-btn--good  { color: var(--success); border-color: rgba(16,185,129,0.35); }
