html[data-design="classic"][data-theme="dark"] .cont-row-meta     { color: #4a7090; }
html[data-design="classic"][data-theme="dark"] .cont-btn          { background: #0f1e30; border-color: #1e3a5a; color: #8cb4d0; }
html[data-design="classic"][data-theme="dark"] .cont-section-label{ color: #4a7090; }

/* ── Projects Discussed block editor (meeting modal) ─────────── */
