}
html[data-design="classic"] .meet-project-discussion-header { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
html[data-design="classic"] .meet-project-discussion-name { font-size: 13px; font-weight: 700; color: var(--gray-800); }
