html[data-design="classic"][data-theme="dark"] .meet-project-discussion { border-color: #1e3a5a; }
html[data-design="classic"][data-theme="dark"] .meet-project-discussion-name { color: #cce0f0; }
html[data-design="classic"][data-theme="dark"] .meet-whats-changed { color: #8cb4d0; }
html[data-design="classic"][data-theme="dark"] .meet-inline-add input { background: #0f1e30; border-color: #1e3a5a; color: #cce0f0; }

/* ── Trends panel ─────────────────────────────────────────────── */
html[data-design="classic"] .trend-panel { padding: 10px 16px; }
html[data-design="classic"] .trend-toggle {
