html[data-design="classic"] .trend-stat { display: flex; flex-direction: column; }
html[data-design="classic"] .trend-stat-num { font-size: 20px; font-weight: 800; color: var(--gray-900); line-height: 1; }
html[data-design="classic"] .trend-stat-label { font-size: 10px; color: var(--gray-400); text-transform: uppercase; letter-spacing: .04em; margin-top: 2px; }
html[data-design="classic"] .trend-chart-block { margin-top: 14px; }
html[data-design="classic"] .trend-chart-title { font-size: 12px; font-weight: 700; color: var(--gray-500); margin-bottom: 4px; }

html[data-design="classic"][data-theme="dark"] .trend-toggle { color: #cce0f0; }
html[data-design="classic"][data-theme="dark"] .trend-stat-num { color: #cce0f0; }
