html[data-design="classic"] .meet-inline-add-narrow { flex: 0 0 110px; }
html[data-design="classic"] .meet-add-type-toggles { display: flex; gap: 6px; margin-top: 6px; }
html[data-design="classic"] .meet-toggle-btn {
