/* ── src/styles/pages/projects.css ── */
/* Projects page — Studio + Atlas (stage 3). Shared pieces are in page-kit.css. */

html[data-design="classic"] .pj-section { margin-bottom: 28px; }
html[data-design="classic"] .pj-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 16px;
  /* every card the same size: equal columns, and every row at least as tall
     as a full card; a card that opens a panel grows its own row only */
  grid-auto-rows: minmax(var(--pj-card-h), auto);
  align-items: stretch;
}
html[data-design="classic"] .pj-page { --pj-card-h: 248px; }

/* ── Card ────────────────────────────────────────────────────────────────── */
html[data-design="classic"] .pj-card {
  height: 100%;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
  padding: 16px 18px 14px;
  background: var(--bg-card, #fff);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  transition: border-color 0.15s, box-shadow 0.15s;
}
html[data-design="classic"] .pj-card:hover { border-color: var(--border-strong); box-shadow: 0 4px 14px rgba(20, 23, 43, 0.06); }
html[data-design="classic"] .pj-card-top { display: flex; align-items: center; gap: 8px; min-height: 24px; }
html[data-design="classic"] .pj-card-top .am-trigger { margin: -4px -8px -4px 0; }
html[data-design="classic"] .pj-spacer { flex: 1; }

html[data-design="classic"] .pj-due {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12.5px;
  color: var(--text-secondary);
  white-space: nowrap;
}
html[data-design="classic"] .pj-due--late { color: var(--danger-text); font-weight: 600; }

html[data-design="classic"] .pj-name {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  font-size: 17px;
  font-weight: 700;
  letter-spacing: -0.01em;
  line-height: 1.3;
  min-width: 0;
}
html[data-design="classic"] .pj-swatch { width: 10px; height: 10px; border-radius: 3px; flex-shrink: 0; }
html[data-design="classic"] .pj-name-link {
  display: inline;
  padding: 0;
  margin: 0;
  border: 0;
  background: none;
  font: inherit;
  color: var(--text-primary);
  text-align: left;
  white-space: normal;
  min-width: 0;
  overflow-wrap: anywhere;
}
html[data-design="classic"] .pj-name-link:hover { color: var(--brand-600); text-decoration: underline; text-underline-offset: 3px; }
