  overflow: hidden;
  min-height: calc(2 * 1.45em);  /* always room for two lines, so cards line up */
}
html[data-design="classic"] .pj-card-text { min-height: 0; }
/* progress + team sit on the card's bottom edge whatever is above them */
html[data-design="classic"] .pj-card > .pj-progress { margin-top: auto; }
html[data-design="classic"] .pj-meta { display: flex; flex-wrap: nowrap; gap: 6px; margin-top: 8px; overflow: hidden; }
html[data-design="classic"] .pj-meta .pj-chip { flex-shrink: 0; max-width: 100%; }
html[data-design="classic"] .pj-chip {
