html[data-design="classic"] .pj-progress-track { flex: 1; height: 8px; border-radius: 4px; background: #E9EBF2; overflow: hidden; }
html[data-design="classic"] .pj-progress-fill { height: 100%; border-radius: 4px; transition: width 0.4s; }
html[data-design="classic"] .pj-progress-num { font-size: 13px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--text-primary); min-width: 34px; text-align: right; }

/* Team line */
