html[data-design="classic"] .settings-error-banner { background: var(--danger-soft); color: var(--danger-text); border: 1px solid #F5C2BC; }

/* "Create another workspace" */
html[data-design="classic"] .ws-callout {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin: 0 0 16px;
  padding: 18px 24px;
