/* Permission chips stay usable by keyboard */
html[data-design="classic"] .ws-perm-chip:focus-within { outline: 2px solid var(--brand-500); outline-offset: 1px; }

/* Dark */
html[data-design="classic"][data-theme="dark"] .settings-section,
html[data-design="classic"][data-theme="dark"] .ws-settings-section,
html[data-design="classic"][data-theme="dark"] .ws-callout,
html[data-design="classic"][data-theme="dark"] .usage-stat-card { background: var(--bg-card); border-color: rgba(255,255,255,0.08); }
html[data-design="classic"][data-theme="dark"] .settings-section-title,
html[data-design="classic"][data-theme="dark"] .ws-settings-section-title { border-color: rgba(255,255,255,0.08); }
html[data-design="classic"][data-theme="dark"] .ws-settings-nav { background: transparent; border: 0; }
html[data-design="classic"][data-theme="dark"] .ws-settings-nav-item:hover { background: rgba(255,255,255,0.05); }
html[data-design="classic"][data-theme="dark"] .ws-settings-nav-item.active { background: rgba(124,128,255,0.16); color: #fff; }
html[data-design="classic"][data-theme="dark"] .usage-stat-icon { background: rgba(124,128,255,0.16); color: #C7C8F5; }
html[data-design="classic"][data-theme="dark"] .settings-success-banner { background: rgba(110,231,168,0.1); border-color: rgba(110,231,168,0.25); }
html[data-design="classic"][data-theme="dark"] .settings-error-banner { background: rgba(252,165,165,0.1); border-color: rgba(252,165,165,0.25); }

/* Narrow: the menu becomes a wrapping row of chips above the content */
