  html[data-design="classic"] .ws-settings-layout { grid-template-columns: 1fr; gap: 16px; }
  html[data-design="classic"] .ws-settings-nav { position: static; display: flex; flex-wrap: wrap; gap: 4px; }
  html[data-design="classic"] .ws-nav-entry { display: contents; }
  html[data-design="classic"] .ws-nav-group { display: none; }
  html[data-design="classic"] .ws-settings-nav-item { width: auto; border: 1px solid var(--border); background: var(--bg-card, #fff); }
}

