html[data-design="classic"] .wt-hours { font-size: 13.5px; font-weight: 600; color: var(--text-primary); font-variant-numeric: tabular-nums; }
html[data-design="classic"] .wt-sub { grid-column: 1 / -1; font-size: 12px; color: var(--text-muted); }
html[data-design="classic"] .wt-total { margin: 0; font-size: 12.5px; color: var(--text-secondary); font-weight: 600; }
html[data-design="classic"] .wt-muted { margin: 0; font-size: 12.5px; color: var(--text-muted); }
html[data-design="classic"] .wt-error { margin: 0; font-size: 12.5px; color: var(--danger-text, #b91c1c); }
html[data-design="classic"] .pj-work { display: flex; align-items: center; gap: 8px; margin-top: 2px; }
html[data-design="classic"] .pj-row-actions { display: inline-flex; align-items: center; gap: 6px; }
html[data-design="classic"] .wt-strip { display: none; }
@media (max-width: 768px) {
  html[data-design="classic"] .wt-strip { display: block; position: sticky; top: 0; z-index: 40; padding: 6px 12px; background: var(--bg-card); border-bottom: 1px solid var(--border); }
  html[data-design="classic"] .wt-strip .wt-chip { display: flex; max-width: none; width: 100%; height: 40px; border-radius: 10px; }
  html[data-design="classic"] .wt-strip .wt-chip-name { max-width: none; flex: 1; font-size: 14px; }
  html[data-design="classic"] .wt-strip .wt-stop { height: 32px; padding: 0 14px; font-size: 13.5px; }
  html[data-design="classic"] .wt-btn { min-height: 42px; padding: 0 16px; font-size: 14px; }
}

